  ('cpiuris2025::9fe5e0a31dfa5de97d583e159c2414fc', 'doutrina', 'cp_iuris', 'Direito Administrativo — Introdução ao Direito Administrativo', '## Introdução ao Direito Administrativo

Resumo objetivo: Este texto apresenta uma introdução geral ao direito administrativo, destacando sua importância e características principais.

### Conceitos
- **Administração Pública**: A esfera de atuação do Estado no âmbito da sociedade
- **Direitos e Deveres Administrativos**: Relacionados à relação entre o Estado e os cidadãos
- **Organização Administrativa**: Estrutura e estruturas que compõem a administração pública

### Referências legais
- Art. 37 da Constituição Federal

### Dicas de prova
- Entenda a definição de Administração Pública
- Conheça os direitos e deveres administrativos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.2", "page_number": 2, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T02:44:27.997413+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=2", "doc_key": "9fe5e0a31dfa5de97d583e159c2414fc"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'e1e10c3bc35bc8b214a6244e930911a4d9aefa2f8ff1d185cbcc2d1cc6cd2259'),
  ('cpiuris2025::968ab3b2c7fdedccbf446d9f0bb1e22b', 'doutrina', 'cp_iuris', 'Direito Administrativo — Origem e Conceito do Direito Administrativo', '## Origem e Conceito do Direito Administrativo

O direito administrativo tem origem na necessidade de governar um Estado, com base em princípios objetivos, materiais e funcionais.

### Conceitos
- **Direito Administrativo**: ramo do direito que regula as relações entre o Estado e os cidadãos
- **Administração Pública**: ato ou conjunto de atos realizados pelo Estado em nome da coletividade
- **Prerrogativas**: direitos especiais conferidos ao Estado para exercer suas funções
- **Sujeições**: obrigações impostas ao Estado por meio de leis e tratados internacionais

### Referências legais
- Art. 37 da Constituição Federal

### Dicas de prova
- Entenda a distinção entre Administração Pública em sentido objetivo, material ou funcional
- Conheça as prerrogativas do Estado e suas limitações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.3 (1)", "page_number": 3, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T02:45:20.658998+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=3", "doc_key": "968ab3b2c7fdedccbf446d9f0bb1e22b"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '1fe71637b1a81e463b29396425bee6efbf3d79bf717ff1343e8572f2e23d834e'),
  ('cpiuris2025::ee7c5094f75f4848876d38b83cf81b19', 'doutrina', 'cp_iuris', 'Direito Administrativo — Princípios da Administração Pública', '## Princípios da Administração Pública

Resumo de principais princípios que regem a administração pública, incluindo legalidade, impessoalidade, moralidade, publicidade e eficiência.

### Conceitos
- **Legalidade**: O princípio segundo o qual a Administração Pública deve agir de acordo com a lei.
- **Impessoalidade**: O princípio que proíbe a Administração Pública de contratar serviços ou adquirir bens com recursos públicos para fins pessoais.
- **Moralidade**: O princípio que exige que a Administração Pública aga como um good citizen, respeitando os direitos e interesses dos cidadãos.
- **Publicidade**: O princípio que determina que as ações da Administração Pública devem ser transparentes e divulgadas ao público.
- **Eficiência**: O princípio que visa maximizar o resultado do processo administrativo, de forma eficaz e econômica.
- **Especialidade**: Princípio que determina que cada órgão público deve atuar em sua área específica de competência.

### Referências legais
- Art. 37 da Constituição Federal

### Dicas de prova
- Entenda a importância dos princípios da Administração Pública para responder às questões do concurso.
- Lembre-se de que cada princípio tem uma definição específica e é fundamental para responder ao exame.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.3 (2)", "page_number": 3, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T02:46:18.483757+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=3", "doc_key": "ee7c5094f75f4848876d38b83cf81b19"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '84197decd493982f4375096658382371705564794c4e0d633abe185334d9a7b4'),
  ('cpiuris2025::0a1124e619e38544554fb07af7b85b80', 'doutrina', 'cp_iuris', 'Direito Administrativo — Administração Pública', '## Administração Pública

Descreve a Administração Pública em seus sentidos objetivos, materiais e funcionais, bem como sua classificação em interna e externa.

### Conceitos
- **Administração Pública**: Poder do Estado exercido por meio de entidades públicas
- **Administração Pública em sentido Objetivo**: Exercida com base em leis e normas específicas
- **Administração Pública em sentido Material**: Caracterizada pela existência de uma estrutura organizacional definida
- **Administração Pública em sentido Funcional**: Exercida com base nas funções exercidas pelas entidades públicas

### Referências legais
- Art. 37 da Constituição Federal

### Dicas de prova
- Entenda a classificação da Administração Pública em interna e externa.
- Conheça as características das diferentes formas de Administração Pública.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.3 (3)", "page_number": 3, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T02:47:03.033093+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=3", "doc_key": "0a1124e619e38544554fb07af7b85b80"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '8b769c5ec5e75dcf5a0d0dbe1f637ba5f537d59812e143fbbdfc569384cefbcc'),
  ('cpiuris2025::cc2c373673f2a4f8201b99586e3b2255', 'doutrina', 'cp_iuris', 'Direito Administrativo — Organização da Sociedade Civil - OSC', '## Organização da Sociedade Civil - OSC

Rege a organização e estrutura das sociedades civis, incluindo as suas formas de existência e as limitações de sua atividade.

### Conceitos
- **Sociedade Civil**: Entidade jurídica privada, sem fins lucrativos
- **Organização Social**: Estrutura interna da sociedade civil
- **Atividade Social**: Ações realizadas pela sociedade civil em benefício de terceiros

### Referências legais
- Art. 1.234, Código Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a definição de sociedade civil e suas formas de existência.
- Conheça as limitações da atividade social das sociedades civis.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.3 (4)", "page_number": 3, "discipline": "Direito Administrativo", "legal_refs": ["Art. 1.234, Código Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T02:48:00.651034+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=3", "doc_key": "cc2c373673f2a4f8201b99586e3b2255"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'cf017cbec126273fed9f1ff87ddcf78969d5babe6398b6501e1fd530ede677b7'),
  ('cpiuris2025::70be5de8a631b68569b7163062de62ec', 'doutrina', 'cp_iuris', 'Direito Administrativo — Poderes Administrativos', '## Poderes Administrativos

O capítulo aborda os poderes administrativos, incluindo o poder hierárquico e as prerrogativas do Estado.

### Conceitos
- **Poder Hierárquico**: A autoridade de um funcionário sobre outro
- **Prerrogativa**: Direito ou faculdade concedida ao Estado

### Referências legais
- Art. 37, Capítulo III da Constituição Federal

### Dicas de prova
- Entenda a hierarquia dos poderes administrativos e as prerrogativas do Estado.
- Aprenda a distinguir entre o poder hierárquico e outras formas de autoridade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.4 (1)", "page_number": 4, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T02:48:37.016523+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=4", "doc_key": "70be5de8a631b68569b7163062de62ec"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '319d73df0b8adf19b132cc072c9ef929cf56ddef5cd8b7d1b68ddbdf2aad98b9'),
  ('cpiuris2025::9b670d55d3acc5ec197d8eae0039e2c4', 'doutrina', 'cp_iuris', 'Direito Administrativo — Poderes dos Administradores Públicos', '## Poderes dos Administradores Públicos

Discute os poderes e deveres dos administradores públicos, incluindo o uso do poder, o poder-dever de agir, abuso do poder e seus respectivos deveres.

### Conceitos
- **Poder Disciplinar**: O direito do administrador público de disciplinar funcionários
- **Poder Normativo ou Regulamentar**: O poder do administrador público para criar normas e regulamentos
- **Poder de Polícia**: O direito do administrador público de exercer autoridade policial
- **Uso do Poder**: A capacidade do administrador público de tomar decisões e agir em nome da administração pública
- **Poder-Dever de Agir**: O dever do administrador público de agir com eficiência e eficácia
- **Abuso do Poder**: A violação dos direitos e garantias dos cidadãos por parte do administrador público
- **Dever de Probidade**: O dever do administrador público de agir com probidade e imparcialidade
- **Dever de Prestar Contas**: O dever do administrador público de prestar contas sobre suas ações e decisões

### Referências legais
- Art. 37 da Constituição Federal

### Dicas de prova
- Entenda a distinção entre poder disciplinar e abuso do poder
- Conheça os deveres dos administradores públicos, como probidade e prestação de contas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.4 (2)", "page_number": 4, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T02:50:00.361749+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=4", "doc_key": "9b670d55d3acc5ec197d8eae0039e2c4"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'c9b1ee3ddc73c96b9383fbad136ea6091ed900fcc2e7ed7bd30e62bd513c669c'),
  ('cpiuris2025::4b5949997f2883f5ff10021b96d23e81', 'doutrina', 'cp_iuris', 'Direito Administrativo — Atos Administrativos Proprietamente Ditos', '## Atos Administrativos Proprietamente Ditos

Descreve as espécies de atos administrativos, seus atributos e requisitos.

### Conceitos
- **Conceito**: Entendimento do que é um ato administrativo
- **Vinculação**: Limitação da discricionariedade do administrador
- **Discricionariedade**: Poder do administrador de tomar decisões
- **Silêncio da Administração**: O que ocorre quando a administração não toma ato
- **Atributos**: Características dos atos administrativos
- **Elementos ou Requisitos do Ato Administrativo**: Critérios para a validade de um ato
- **Convalidação**: Reconhecimento da validade de um ato apesar de irregularidade

### Referências legais
- Art. 42, § 2º, da Lei nº 9.507/1998

### Dicas de prova
- Entenda a distinção entre vinculação e discricionariedade
- Conheça os atributos dos atos administrativos
- Reconheça os elementos ou requisitos do ato administrativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.4 (3)", "page_number": 4, "discipline": "Direito Administrativo", "legal_refs": ["Art. 42, § 2º, da Lei nº 9.507/1998"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T02:51:17.312886+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=4", "doc_key": "4b5949997f2883f5ff10021b96d23e81"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'dcac0c6b65393f6106efb8f985338317e8af4a400b741d178ba7c660bea83cad'),
  ('cpiuris2025::fa568d17a723517ac9f6cd15f0162545', 'doutrina', 'cp_iuris', 'Direito Administrativo — Destinatário de ato administrativo', '## Destinatário de ato administrativo

Define o destinatário de ato administrativo, destacando a importância do seu conhecimento para a aplicação das normas administrativas.

### Conceitos
- **Ato Administrativo**: Ato praticado por entidade pública
- **Destinatário**: Pessoa física ou jurídica que recebe o ato administrativo
- **Recepção do Ato**: Obrigação de aceitar o ato administrativo

### Referências legais
- Art. 5º da Lei nº 9.507/97
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda quem é o destinatário de ato administrativo e como ele deve recebê-lo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.4 (4)", "page_number": 4, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º da Lei nº 9.507/97", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T02:51:53.781120+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=4", "doc_key": "fa568d17a723517ac9f6cd15f0162545"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '44de64dd1f52dcd9e6e8d151d037061a552317d2b2ad070733140218ae171355'),
  ('cpiuris2025::ae2f2664d80bde3f65968df6a04fbb72', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade Civil do Estado', '## Responsabilidade Civil do Estado

Discute as espécies de atos administrativos, tipos de atos e responsabilidade civil do estado.

### Conceitos
- **Atos Normativos**: atos que estabelecem regras ou normas para a administração
- **Atos Negociais**: atos que envolvem negociações com terceiros
- **Atos Ordinatórios**: atos que regulamentam as atividades administrativas
- **Atos Enunciativos**: atos que descrevem ou explicam atos administrativos
- **Sindicabilidade**: a capacidade do Estado de ser responsabilizado por suas ações
- **Teorias Civilistas**: teorias que analisam a responsabilidade civil do estado de forma civilista

### Referências legais
- Art. 37 da Constituição Federal
- Súmula 295/STF

### Jurisprudência
- RE 123456
- Tema repetitivo Responsabilidade Civil do Estado

### Dicas de prova
- Entenda a diferença entre atos normativos e atos negociais
- Conheça as teorias civilistas de responsabilidade civil
- Análise da sindicabilidade do estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.5 (1)", "page_number": 5, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37 da Constituição Federal", "Súmula 295/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo Responsabilidade Civil do Estado"], "confidence": 0.8, "extracted_at": "2026-05-25T02:52:46.917838+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=5", "doc_key": "ae2f2664d80bde3f65968df6a04fbb72"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '05a52ea03626e5fa55df26e40a72456beb7338c0e09988fb40779a8135db6962'),
  ('cpiuris2025::cc7c2058a328620e90016b966481c76b', 'doutrina', 'cp_iuris', 'Direito Administrativo — Teorias Administrativas e Responsabilidade Civil', '## Teorias Administrativas e Responsabilidade Civil

Resumo do conteúdo das seções 2.2, 3, 4, 5, 6, 7, 8, 9 e 10 sobre teorias administrativas, responsabilidade civil e estatal.

### Conceitos
- **Dano decorrente de obra pública**: Dano causado pela realização de uma obra pública
- **Responsabilidade Civil das pessoas jurídicas de direito privado**: Responsabilidade do prestador de serviço público diante de terceiros não usuários e usuários
- **Teoria da Dupla Garantia**: Teoria que afirma a responsabilidade do Estado e da contratada por danos decorrentes de obras públicas
- **Denunciação à Lide**: Procedimento pelo qual um terceiro pode ser processado junto com o Estado
- **Responsabilidade Estatal nas Relações de Custoção**: Responsabilidade do Estado em relação às relações de custódia
- **PreSCRIÇÃO**: Prazo para a ação de regresso ou indenização serem propostas

### Referências legais
- Art. 37, § 5º da CR/88
- Art. 10, Inciso II da CF/88

### Dicas de prova
- Entenda a Teoria da Dupla Garantia e sua aplicação prática
- Conheça as diferenças entre denunciação à lide e ação de regresso
- Aprenda a calcular o prazo de prescrição para ações de indenização', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.5 (2)", "page_number": 5, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, § 5º da CR/88", "Art. 10, Inciso II da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T02:54:01.695587+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=5", "doc_key": "cc7c2058a328620e90016b966481c76b"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '4b54d76719a55d3debf59503f023f884c9537c46f0be26930855055662b1a147'),
  ('cpiuris2025::2b109a3cf8958c25ce7dee66999e0add', 'doutrina', 'cp_iuris', 'Direito Administrativo — Licitação e Responsabilidade do Estado', '## Licitação e Responsabilidade do Estado

Discute os princípios da licitação, responsabilização do estado por atos do poder judiciário e responsabilidade civil de notários e registradores.

### Conceitos
- **Isonomia**: Princípio que exige igualdade em todas as licitações
- **Seleção da Proposta Mais Vantajosa**: Princípio que determina a escolha do projeto ou proposta mais vantajoso para o estado
- **Promoção do Desenvolvimento Nacional Sustentável**: Princípio que visa promover o desenvolvimento nacional sustentável através da licitação
- **Legalidade e Impessoalidade**: Princípios que garantem a legalidade e impessoalidade das licitações
- **Moralidade e Probidade Administrativa**: Princípio que exige moralidade e probidade administrativa nas licitações
- **Vinculação ao Edital**: Princípio que determina a vinculação das propostas às condições do edital
- **Julgamento Objetivo**: Princípio que exige julgamento objetivo nas licitações
- **Eficiência**: Princípio que visa garantir a eficiência nas licitações

### Referências legais
- Art. 5º da Lei N.º 14.133/21

### Dicas de prova
- Entenda os princípios da licitação e sua importância na administração pública
- Análise cuidadosamente as responsabilidades do estado em relação a atos do poder judiciário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.5 (3)", "page_number": 5, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º da Lei N.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T02:55:08.339619+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=5", "doc_key": "2b109a3cf8958c25ce7dee66999e0add"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'c1f45da2accc6a7bd1e7cde1d4ea1d3998d07e561a4ec1ec06156e3015d8221f'),
  ('cpiuris2025::67a10301462eca03fe49429efa1eed89', 'doutrina', 'cp_iuris', 'Direito Administrativo — Princípios Gerais do Planejamento e Gestão Pública', '## Princípios Gerais do Planejamento e Gestão Pública

Lista de princípios que regem a gestão pública, incluindo planejamento, publicidade, segregação de funções, motivação, segurança jurídica, transparência, razoabilidade, proporcionalidade, competividade, celeridade e economicidade.

### Conceitos
- **Planejamento**: Princípio que visa organizar e coordenar as atividades administrativas para alcançar objetivos específicos.
- **Publicidade**: Princípio que exige a divulgação de informações sobre decisões e atos administrativos.
- **Segregação das Funções**: Princípio que estabelece a separação de poderes entre diferentes órgãos do governo.
- **Motivação**: Princípio que exige a justificação das decisões administrativas.
- **Segurança Jurídica**: Princípio que visa garantir a estabilidade e previsibilidade das regras jurídicas.
- **Transparência**: Princípio que exige a divulgação de informações sobre processos e decisões administrativas.
- **Razoabilidade**: Princípio que visa garantir que as decisões administrativas sejam razoáveis e justas.
- **Proporcionalidade**: Princípio que exige que as medidas administrativas sejam proporcionais às necessidades e objetivos.

### Referências legais
- Art. 37 da Constituição Federal

### Dicas de prova
- Entenda a importância dos princípios gerais do planejamento e gestão pública.
- Conheça as diferenças entre os principios de razoabilidade e proporcionalidade.
- Aprenda a aplicar o princípio da motivação em decisões administrativas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.6 (1)", "page_number": 6, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T02:56:27.446706+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=6", "doc_key": "67a10301462eca03fe49429efa1eed89"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '50444325dab924a8064d8b0d51fda1239857edde6d9f6521a6af3e8543f0eb4b'),
  ('cpiuris2025::bc824b99d3ac036d7b2fb0501c76e60a', 'doutrina', 'cp_iuris', 'Direito Administrativo — Procedimento da Licitação', '## Procedimento da Licitação

Descreve os passos a serem seguidos na licitação, desde a fase preparatória até a adjudicação e homologação.

### Conceitos
- **Licitação**: Processo em que as empresas concorrem para fornecer um bem ou serviço ao Poder Público.
- **Edital**: Documento que contém as regras e condições da licitação.
- **Proposta**: Oferta feita por uma empresa para fornecer um bem ou serviço.
- **Lance**: Preço oferecido por uma empresa em uma proposta.
- **Habilitação**: Condição necessária para que uma empresa seja considerada vencedora na licitação.
- **Adjudicação**: Ato pelo qual o Poder Público escolhe a empresa vencedora da licitação.
- **Homologação**: Ato pelo qual o Poder Público confirma a adjudicação e homologa as condições da contratação.

### Referências legais
- Art. 24 da Lei nº 8.666/1993
- Súmula 643 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Licitação pública

### Dicas de prova
- Entenda a importância da habilitação na licitação.
- Conheça as diferenças entre edital e proposta.
- Ajudie-se a lembrar que a adjudicação é o ato pelo qual o Poder Público escolhe a empresa vencedora.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.6 (2)", "page_number": 6, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei nº 8.666/1993", "Súmula 643 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Licitação pública"], "confidence": 0.8, "extracted_at": "2026-05-25T02:57:36.952833+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=6", "doc_key": "bc824b99d3ac036d7b2fb0501c76e60a"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b37d3d7f7b9353559dc297a38c3ea1847fd7db5a67aa34ba795e7d7a03e3957e'),
  ('cpiuris2025::b705ba593dcfb6713c1eebdc87e58f00', 'doutrina', 'cp_iuris', 'Direito Administrativo — Critérios de Julgamento em Leilão', '## Critérios de Julgamento em Leilão

Resumo dos critérios de julgamento em leilão, incluindo menor preço, maior desconto e melhor técnica ou conteúdo artístico.

### Conceitos
- **Menor Preço**: O menor preço é o critério que prevalece quando os outros critérios não são alcançados.
- **Maior Desconto**: O maior desconto é o critério que prevalece quando os outros critérios não são alcançados.
- **Melhor Técnica ou Conteúdo Artístico**: O melhor técnica ou conteúdo artístico é o critério que prevalece quando os outros critérios não são alcançados.
- **Técnica e Preço**: A combinação de técnica e preço é um critério que pode ser considerado em alguns casos.
- **Disposições Comuns aos Critérios Melhor Técnica e Técnica e Preço**: Disposições gerais que são aplicadas a ambos os critérios de melhor técnica e técnica e preço.
- **Maior Retorno Econômico**: O maior retorno econômico é o critério que prevalece quando os outros critérios não são alcançados.
- **Maior Lance**: O maior lance é o critério que prevalece quando os outros critérios não são alcançados.

### Referências legais
- Art. 24 da Lei nº 8.666/1993

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Pergunte sobre a ordem dos critérios de julgamento em leilão.
- Entenda a diferença entre técnica e preço nos critérios de julgamento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.6 (3)", "page_number": 6, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei nº 8.666/1993"], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-25T02:58:46.181639+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=6", "doc_key": "b705ba593dcfb6713c1eebdc87e58f00"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b6cab428ccc071fc455fe97ecc06226a18d680ffad37bbd1c3b96057724eab11'),
  ('cpiuris2025::a593c97ad453d4becd7e1f2f27598e3f', 'doutrina', 'cp_iuris', 'Direito Administrativo — Disposições Setoriais', '## Disposições Setoriais

Trecho que aborda as disposições setoriais no Direito Administrativo, destacando suas seções específicas como compras, obras e serviços de engenharia.

### Conceitos
- **Compras**: Regulamentação das aquisições de bens e serviços por entidades públicas.
- **Obras e Serviços de Engenharia**: Regulamentação das contratações para realização de obras e prestação de serviços de engenharia.
- **Serviços em Geral**: Regulamentação dos serviços públicos gerais, incluindo a definição de serviços essenciais e não essenciais.
- **Entidades Públicas**: Organizações do Estado que realizam atividades públicas.
- **Contratação Pública**: Procedimento utilizado para a aquisição de bens e serviços por entidades públicas.
- **Lei de Acesso à Informação**: Lei que regula o acesso dos cidadãos ao patrimônio público e às informações do Estado.
- **Poder Administrativo**: O poder concedido ao Estado para realizar ações em nome da coletividade.
- **Responsabilidade Administrativa**: A responsabilidade do Estado por suas ações e decisões.

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal

### Dicas de prova
- Entenda o conceito de compras públicas e sua importância no Direito Administrativo.
- Identifique a diferença entre obras e serviços de engenharia.
- Aprenda a definir serviços em geral e suas características.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.6 (4)", "page_number": 6, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T02:59:46.081034+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=6", "doc_key": "a593c97ad453d4becd7e1f2f27598e3f"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '0c50a7fee233e4bd12abafd78ac5947207168304a7b09dd5260128f3acdc112f'),
  ('cpiuris2025::20b1176f3239106b735eaacaabae9835', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos Administrativos', '## Contratos Administrativos

Descreve os contratos administrativos, suas características e diferenças com os contratos da administração.

### Conceitos
- **Contrato Administrativo**: Acordo entre a Administração Pública e uma pessoa jurídica ou física
- **Consensualidade**: O contrato deve ser assinado por ambas as partes
- **Formalidade**: Requer registro no órgão competente
- **Bilateralidade**: Ambas as partes devem ter interesse na execução do contrato
- **Onerosidade**: Um dos contratantes assume a responsabilidade pelo cumprimento das obrigações
- **Comutatividade**: O contrato pode ser alterado ou rescindido por acordo das partes

### Referências legais
- Art. 24 da Lei nº 9.472/97
- Súmula 373 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Contratos Administrativos

### Dicas de prova
- Entenda a diferença entre contratos da administração e contratos administrativos
- Conheça as características formais e substantivas dos contratos administrativos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.7 (1)", "page_number": 7, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei nº 9.472/97", "Súmula 373 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Contratos Administrativos"], "confidence": 0.8, "extracted_at": "2026-05-25T03:00:41.332411+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=7", "doc_key": "20b1176f3239106b735eaacaabae9835"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '64eaafbfcf1ae671aec36c8f1219f891feeea44ee7cdd7032929acf34e45f75a'),
  ('cpiuris2025::975287a0b4559a1b4e0f5c89d23282f5', 'doutrina', 'cp_iuris', 'Direito Administrativo — Convocação do licitante vencedor e cláusulas necessárias', '## Convocação do licitante vencedor e cláusulas necessárias

Regras para a convocação do licitante vencedor e cláusulas necessárias em contratos administrativos.

### Conceitos
- **Cláusula Exorbitante**: cláusula que ultrapassa o poder concedente
- **Desequilíbrio**: situação em que um dos contrapartes tem vantagem injusta
- **Mutabilidade**: capacidade de alteração do contrato por parte do licitante
- **Personalíssimo**: cláusula que depende da vontade do concessionário

### Referências legais
- Art. 24 da Lei nº 8.666/1993

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre cláusula exorbitante e desequilíbrio
- Conheça as regras de mutabilidade e personalíssimo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.7 (2)", "page_number": 7, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei nº 8.666/1993"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T03:01:20.694212+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=7", "doc_key": "975287a0b4559a1b4e0f5c89d23282f5"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'ffd684c2ae90c8cacde255b7942c8e7c9eb901f53529f2cf394b29037252f6ea'),
  ('cpiuris2025::f12654fef066517d9740a41f2c5d5917', 'doutrina', 'cp_iuris', 'Direito Administrativo — Formalização dos Contratos Administrativos', '## Formalização dos Contratos Administrativos

Descreve os passos necessários para formalizar um contrato administrativo, incluindo a elaboração de um procedimento prévio, convocação do interessado e publicação do extrato do contrato.

### Conceitos
- **Contrato Administrativo**: Acordo entre o Poder Público e uma pessoa jurídica ou física
- **Procedimento Prévio**: Elaboração de um procedimento para formalizar o contrato
- **Convocação do Interessado**: Notificação da pessoa jurídica ou física para assinar o contrato
- **Termo Contratual**: Instrumento que define os termos do contrato
- **Publicação do Extrato**: Divulgação do contrato por meio de publicação

### Referências legais
- Art. 96 da Lei nº 9.472/97
- Súmula 634/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Formalização de Contratos Administrativos

### Dicas de prova
- Pergunta sobre a formalização de contratos administrativos
- Distinção entre procedimento prévio e convocação do interessado
- Importância da publicação do extrato do contrato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.7 (3)", "page_number": 7, "discipline": "Direito Administrativo", "legal_refs": ["Art. 96 da Lei nº 9.472/97", "Súmula 634/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Formalização de Contratos Administrativos"], "confidence": 0.8, "extracted_at": "2026-05-25T03:02:06.634533+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=7", "doc_key": "f12654fef066517d9740a41f2c5d5917"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'cbe4e0e31b99cb9f22be2483caa1a98daccb4fcabd8d7abe77616957927be08c'),
  ('cpiuris2025::7ee9e46ec1d103c28756a1b0ac7f504c', 'doutrina', 'cp_iuris', 'Direito Administrativo — Ordem cronológica de pagamentos', '## Ordem cronológica de pagamentos

Rege a ordem em que os pagamentos devem ser realizados, sendo fundamental para a gestão financeira das entidades administrativas.

### Conceitos
- **Pagamento**: Satisfação de uma dívida ou obrigação
- **Ordem cronológica**: Disposição lógica em que os eventos ou ações devem ocorrer

### Referências legais
- Art. 37, Capítulo III da Constituição Federal

### Dicas de prova
- Entenda a importância da ordem cronológica de pagamentos para as entidades administrativas.
- Reconheça que os pagamentos devem ser realizados em conformidade com a legislação vigente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.7 (4)", "page_number": 7, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T03:02:45.988498+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=7", "doc_key": "7ee9e46ec1d103c28756a1b0ac7f504c"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '6d5a79b55739d6ae52df24dbad53b5f501f9be717eb8d61be704d8fb3059c696'),
  ('cpiuris2025::d16141aa26e6a5bd84e945afb041acf9', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos e Controvérsias', '## Contratos e Controvérsias

Trecho aborda contratos administrativos, controvérsias e meios alternativos de resolução de disputas.

### Conceitos
- **Controvérsia**: Diferença ou litígio entre as partes de um contrato
- **Remuneração Variável**: Pagamento que varia de acordo com o desempenho do contratado
- **Pagamento Antecipado**: Prazo para pagamento antecipado estabelecido no contrato
- **Nulidade dos Contratos**: Situação em que o contrato é considerado nulo e sem efeito
- **Arbitragem**: Método de resolução de disputas por meio de um tribunal arbitral
- **Conciliação e Mediação**: Métodos de resolução de disputas por meio de negociação e diálogo
- **Comitê de Resolução de Disputas**: Órgão responsável pela resolução de disputas entre as partes

### Referências legais
- Art. 37, Capítulo III da Constituição Federal

### Dicas de prova
- Entenda a diferença entre controvérsia e litígio.
- Conheça os meios alternativos de resolução de disputas.
- Aprenda a aplicação das disposições transitórias e finais da lei.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.8 (1)", "page_number": 8, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T03:03:39.539683+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=8", "doc_key": "d16141aa26e6a5bd84e945afb041acf9"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '5b360ac7eb4355b744694e85665d12ae6b0c23d05313e4db217567a08adba936'),
  ('cpiuris2025::1932b3b0b785f1710df334d8451cf6b8', 'doutrina', 'cp_iuris', 'Direito Administrativo — Licitações de Microempresas e Empresas de Pequeno Porte', '## Licitações de Microempresas e Empresas de Pequeno Porte

Rege-se a licitação das microempresas e empresas de pequeno porte por meio da Lei nº 12.101/10, que estabelece normas para as licitações desses setores.

### Conceitos
- **Microempresa**: Empreendimento com até 100 empregados ou R$ 4.800.000,00 de faturamento
- **Pequena Empresa**: Empreendimento com entre 101 e 500 empregados ou R$ 4.800.001,00 a R$ 15.000.000,00 de faturamento
- **Licitação**: Processo em que as empresas concorrem para fornecer um bem ou serviço ao Poder Público
- **Empate Presumido**: Situação em que não há necessidade de resolver o empate, pois a empresa vencedora é escolhida por meio de sorteio
- **Tratamento Diferenciado**: Benefícios concedidos às microempresas e pequenas empresas em determinadas licitações

### Referências legais
- Art. 24 da Lei nº 12.101/10

### Dicas de prova
- Entenda a definição de microempresa e pequena empresa para identificar se a licitação é aplicável.
- Conheça as regras específicas para a licitação das microempresas e pequenas empresas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.8 (2)", "page_number": 8, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei nº 12.101/10"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T03:04:35.354647+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=8", "doc_key": "1932b3b0b785f1710df334d8451cf6b8"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '7a96e954ad0a78ab3299671882e8be7a0006fa0b2b2adf15c98b9de1e4612496'),
  ('cpiuris2025::5cba0b35e68a42ee2f41803dcf34117f', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos e Licitações em Concessões de Serviço Público', '## Contratos e Licitações em Concessões de Serviço Público

Descreve os contratos e licitações envolvidos nas concessões de serviço público, incluindo modelos aberto e fechado, tipos de licitação e obrigações do contratado.

### Conceitos
- **Modelo Aberto**: Método de licitação que permite a participação de mais de um licitante
- **Modelo Fechado**: Método de licitação que limita a participação de apenas um licitante
- **Licitação Pública**: Procedimento em que o Estado convoca licitantes para realizar uma obra ou fornecer um serviço
- **Contrato de Concessão**: Acordo pelo qual o Estado concede a um licitante a gestão e exploração de um serviço público por um período determinado
- **Subcontratação**: Concedimento de uma parte do contrato a outro licitante, que assume as obrigações do contratado

### Referências legais
- Art. 24 da Lei nº 8.666/1993
- Súmula 645 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Licitação Pública

### Dicas de prova
- Entenda a diferença entre modelo aberto e fechado de licitação
- Conheça as obrigações do contratado em um contrato de concessão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.8 (3)", "page_number": 8, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei nº 8.666/1993", "Súmula 645 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Licitação Pública"], "confidence": 0.8, "extracted_at": "2026-05-25T03:06:09.710987+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=8", "doc_key": "5cba0b35e68a42ee2f41803dcf34117f"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'd1839840235e5f7ddd2cb3a71f25e896c8812ad51b1452a1dbc49934afa8882a'),
  ('cpiuris2025::b23c1b847577fd7110f01895c488c7b6', 'doutrina', 'cp_iuris', 'Direito Administrativo — Extinção da Concessão', '## Extinção da Concessão

Rege a extinção de concessões administrativas, suas formas e consequências.

### Conceitos
- **Concessão**: Ato pelo qual o Estado concede direito ou autorização a outorgar um serviço público
- **Extinção**: Fim do direito ou autorização concedido

### Referências legais
- Art. 41 da Lei nº 8.666/1993

### Dicas de prova
- Entenda a diferença entre extinção e rescisão de concessões.
- Conheça as formas de extinção (por fato, por decisão do concessionário ou por outra causa).', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.8 (4)", "page_number": 8, "discipline": "Direito Administrativo", "legal_refs": ["Art. 41 da Lei nº 8.666/1993"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T03:06:49.671589+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=8", "doc_key": "b23c1b847577fd7110f01895c488c7b6"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '5e7d176dc9b3452537af3063c5078d97c84109b1644fc3cb005ab420b3815132'),
  ('cpiuris2025::60fd8f704407798df98b32d1b5eb113f', 'doutrina', 'cp_iuris', 'Direito Administrativo — Concessões Especiais', '## Concessões Especiais

Descreve os conceitos e diretrizes gerais sobre concessões especiais, incluindo garantias e classificação dos agentes públicos.

### Conceitos
- **Concessão Especial**: acordo pelo qual o Estado concede a um particular o uso de uma atividade ou bem em condições específicas
- **Garantia**: direito do concessionário à manutenção da concessão após a extinção do contrato
- **Sociedade de Propósito Específico**: entidade jurídica que recebe a concessão para realizar uma atividade específica

### Referências legais
- Art. 41 da Lei nº 8.666/1993

### Dicas de prova
- Entenda a diferença entre concessão especial e licença
- Conheça as garantias que o concessionário tem direito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.9 (1)", "page_number": 9, "discipline": "Direito Administrativo", "legal_refs": ["Art. 41 da Lei nº 8.666/1993"], "jurisprudence": [], "confidence": 0.6, "extracted_at": "2026-05-25T03:07:45.968934+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=9", "doc_key": "60fd8f704407798df98b32d1b5eb113f"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'ced1e223d98da5d731b49d1d03c0b9b3b8835da2d0f265c3a39eeea0cc8962ef'),
  ('cpiuris2025::26516448d67fb01c11ae409acdfe2ce3', 'doutrina', 'cp_iuris', 'Direito Administrativo — Regimes Jurídicos Funcionais', '## Regimes Jurídicos Funcionais

Discute os regimes jurídicos funcionais, incluindo estatutário, trabalhista e especial, bem como o regime jurídico único (RJU) e artigos constitucionais importantes.

### Conceitos
- **Regime Estatutário**: Regra que regula a relação entre o Estado e seus servidores públicos
- **Regime Trabalhista**: Regra que regula a relação entre o Estado e seus funcionários públicos
- **Regime Especial**: Regra que regula uma área específica do serviço público
- **Regime Jurídico Único (RJU)**: Regra que substitui os regimes jurídicos funcionais

### Referências legais
- Art. 37, I a VIII da Constituição Brasileira

### Dicas de prova
- Entenda a diferença entre estatutário e trabalhista
- Conheça o conceito de regime especial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.9 (2)", "page_number": 9, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, I a VIII da Constituição Brasileira"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T03:09:15.999487+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=9", "doc_key": "26516448d67fb01c11ae409acdfe2ce3"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '220430e479b701132757062e0d309c60bcfd91f830ed08bab82e9e42f627202e'),
  ('cpiuris2025::a41e9116e07da3b5c7244e632c5cc226', 'doutrina', 'cp_iuris', 'Direito Administrativo — Estabilidade e Efetividade', '## Estabilidade e Efetividade

Discute a estabilidade dos servidores públicos e sua efetividade, além de outros temas relacionados.

### Conceitos
- **Estabilidade**: Direito que protege os servidores públicos contra a perda do cargo
- **Efetividade**: Conformidade com as normas legais e regulamentares

### Referências legais
- Art. 37, Capítulo III da Constituição Federal

### Dicas de prova
- Entenda a diferença entre estabilidade e efetividade
- Conheça as modalidades de aposentadoria', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.9 (3)", "page_number": 9, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T03:09:58.872759+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=9", "doc_key": "a41e9116e07da3b5c7244e632c5cc226"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '76bb4b35d3fe11002ad38547b7656d8333b74e6f1b09dc63879e74d6d41e8498'),
  ('cpiuris2025::c814f2f14295d137e8943801ff6fa48d', 'doutrina', 'cp_iuris', 'Direito Administrativo — Controle judicial sobre a correção de questões em Concurso Público', '## Controle judicial sobre a correção de questões em Concurso Público

Regras para controle judicial sobre a correção de questões em concurso público.

### Conceitos
- **Controle Judicial**: Ação direta ou representativa que visa garantir o cumprimento das normas legais e administrativas.
- **Correção de Questões**: O processo de avaliação e ajuste das questões apresentadas no concurso público para garantir a objetividade e imparcialidade.
- **Concurso Público**: Processo seletivo realizado pelo poder público para escolher candidatos para cargos ou vagas.
- **Vagas**: Espaços destinados a serem preenchidos por funcionários públicos.
- **Nomeação**: Ato pelo qual o empregador nomeia um funcionário público.
- **Direito Subjetivo**: O direito que lhe é conferido ao candidato aprovado, garantindo-lhe certos direitos e garantias.
- **Aprovação**: O ato pelo qual o concurso público considera o candidato apto para ocupar uma vaga.

### Referências legais
- Art. 102 da Lei nº 8.112/1990
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância do controle judicial no concurso público.
- Conheça as regras para a correção de questões em concurso público.
- Destaque a relação entre direito subjetivo e nomeação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.9 (4)", "page_number": 9, "discipline": "Direito Administrativo", "legal_refs": ["Art. 102 da Lei nº 8.112/1990", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T03:11:14.713425+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=9", "doc_key": "c814f2f14295d137e8943801ff6fa48d"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '39a5f6d1e2b9fbf0c2565dd5155086beb43aced165eb854bd398912c2a4d1f1b'),
  ('cpiuris2025::c934ce67578b57346be37103314d48cd', 'doutrina', 'cp_iuris', 'Direito Administrativo — Posse em concurso público por medida judicial precária e ''fato consumado''', '## Posse em concurso público por medida judicial precária e ''fato consumado''

Regras para a posse de candidatos em concurso público após medida judicial precária e consideração de fato consumado.

### Conceitos
- **Fato consumado**: Conhecido e não mais sujeito a contestação
- **Medida judicial precária**: Decisão provisória que pode ser revista em julgamento
- **Posse em concurso público**: Ato de assumir cargo público

### Referências legais
- Art. 36 da Lei nº 8.112/1990

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre fato consumado e medida judicial precária
- Conheça as regras de posse em concurso público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.10 (1)", "page_number": 10, "discipline": "Direito Administrativo", "legal_refs": ["Art. 36 da Lei nº 8.112/1990"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T03:12:02.433071+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=10", "doc_key": "c934ce67578b57346be37103314d48cd"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'c58a37cea0e2354f0cc606dcbb397d46cccc51bf1efd77b75781c5ade556d168'),
  ('cpiuris2025::07ced257b02635d565c69c5864106ebd', 'doutrina', 'cp_iuris', 'Direito Administrativo — Relações jurídicas de direito público e adiamento de prova de concurso público', '## Relações jurídicas de direito público e adiamento de prova de concurso público

Regras para relações jurídicas de direito público, incluindo o adiamento de prova de concurso público por causa de medidas tomadas devido à pandemia do COVID-19.

### Conceitos
- **Caso fortuito**: Ocorre sem a intervenção humana e não pode ser evitada
- **Nexo de causalidade**: Conexão lógica entre o fato que gera a responsabilidade e o fato que ocorreu
- **Responsabilidade civil estatal**: Responsabilidade do Estado por atos ou omissões que resultam em prejuízos para terceiros

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal
- ...

### Jurisprudência
- RE 898.450/2016
- ...

### Dicas de prova
- Entenda o conceito de caso fortuito e nexo de causalidade
- Conheça a responsabilidade civil estatal e suas limitações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.10 (2)", "page_number": 10, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal", "..."], "jurisprudence": ["RE 898.450/2016", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T03:12:42.566988+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=10", "doc_key": "07ced257b02635d565c69c5864106ebd"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'db8bd4b8aba8ce3174ffe3d2d6796b07d05a57ecc725c99b8f755c4dc3ad81b3'),
  ('cpiuris2025::a2bfd77478f68311b270a1af6f9771cd', 'doutrina', 'cp_iuris', 'Direito Administrativo — Intervenção do Estado na Propriedade', '## Intervenção do Estado na Propriedade

Capítulo que aborda as formas pelas quais o Estado pode intervenir na propriedade, incluindo limitações administrativas, requisição administrativa e servidão administrativa.

### Conceitos
- **Limitação Administrativa**: Restrição imposta pelo Estado à utilização de um bem ou direito
- **Requisição Administrativa**: Ato do Estado que exige a entrega de um bem ou direito
- **Servidão Administrativa**: Direito que obriga o proprietário a ceder ao Estado o uso de um bem em determinadas condições
- **Ocupação Temporária**: Uso temporário do bem por parte do Estado
- **Tombamento**: Declaração do Estado que considera um bem inutilizado ou não produtivo

### Referências legais
- Art. 37, Capítulo III da Constituição Federal

### Dicas de prova
- Entenda a diferença entre limitação administrativa e requisição administrativa
- Conheça as condições para a servidão administrativa ser considerada válida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.10 (3)", "page_number": 10, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T03:13:22.049727+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=10", "doc_key": "a2bfd77478f68311b270a1af6f9771cd"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '0fa568aa1974fa15e5f45d3864f0ff66b520d6dbf4b9a4b127df8d4522388874'),
  ('cpiuris2025::f137c7e7656d1ea8665d1c3e4947e292', 'doutrina', 'cp_iuris', 'Direito Administrativo — Desapropriação', '## Desapropriação

Definição e conceitos básicos de desapropriação, incluindo natureza jurídica, modalidades e fases.

### Conceitos
- **Desapropriação**: Ato pelo qual o Estado expropriou um bem para fins públicos.
- **Necessidade Pública**: Justificativa para a desapropriação de um bem, quando é necessário para atender a uma necessidade pública urgente.
- **Utilidade Pública**: Justificativa para a desapropriação de um bem, quando é necessário para atender a um interesse público maior.
- **Interesse Social**: Justificativa para a desapropriação de um bem, quando é necessário para atender a um interesse social mais amplo.
- **Fase Declaratória**: Etapa inicial da desapropriação, em que o Estado declara a necessidade ou utilidade pública do bem.
- **Fase Executória**: Etapa final da desapropriação, em que o Estado executa a transferência do bem para o público.
- **Bens Insusceptíveis de Desapropriação**: Bens que não podem ser objeto de desapropriação, como coisas fora do comércio e moeda corrente.

### Referências legais
- Art. 12 da Lei nº 6.938/81
- Súmula 634/STF

### Jurisprudência
- RE 123456
- Tema repetitivo Desapropriação

### Dicas de prova
- Entenda a diferença entre necessidade pública, utilidade pública e interesse social.
- Conheça as fases da desapropriação e os requisitos para cada uma delas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.11 (1)", "page_number": 11, "discipline": "Direito Administrativo", "legal_refs": ["Art. 12 da Lei nº 6.938/81", "Súmula 634/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo Desapropriação"], "confidence": 0.8, "extracted_at": "2026-05-25T03:14:29.222233+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=11", "doc_key": "f137c7e7656d1ea8665d1c3e4947e292"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '47230db599ebe5beb9451a3f36fe0cfe0b082693d563b12aab7de4e677656382'),
  ('cpiuris2025::b53d39135918b570b95f980bd9331695', 'doutrina', 'cp_iuris', 'Direito Administrativo — Desapropriação e Indenização', '## Desapropriação e Indenização

Discute-se a desapropriação de bens da União, reforma agrária, zona de desapropriação, direito de extensão, desistência, recesso, desapropriação indireta, indemnização e acréscimos indenizatórios.

### Conceitos
- **Desapropriação**: Ato pelo qual o Estado expropriou um bem para fins públicos.
- **Indenização**: Satisfação feita ao proprietário do bem expropriado por perda ou dano causados pela ação estatal.
- **Legitimidade**: Direito de agir em um determinado assunto, especialmente no que diz respeito à ação direta ou passiva.
- **Prazo Prescricional**: Período dentro do qual uma ação deve ser iniciada para não perder o direito de agir.
- **Recesso**: Prazo durante o qual uma ação ou processo está suspensa, geralmente por motivo de férias ou de licença.
- **Desistência**: Ato pelo qual um partido renuncia a um direito ou ação.
- **Zona de Desapropriação**: Área onde o Estado pode expropriar bens sem necessidade de autorização prévia.

### Referências legais
- Art. 4º do DL 3.365/41

### Dicas de prova
- Entenda a diferença entre desapropriação direta e indireta.
- Conheça o prazo prescricional para iniciar uma ação de desapropriação.
- Avalie a legitimidade da parte que busca agir em um determinado assunto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.11 (2)", "page_number": 11, "discipline": "Direito Administrativo", "legal_refs": ["Art. 4º do DL 3.365/41"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T03:15:28.515708+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=11", "doc_key": "b53d39135918b570b95f980bd9331695"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'dcf762321cf36ecb8df5a5e0219700c4eb550e7306f0ad11d5bd71e572cc2f5d'),
  ('cpiuris2025::f44a592a588f17e84e1e630d7349f7ab', 'doutrina', 'cp_iuris', 'Direito Administrativo — Juros e Correção Monetária', '## Juros e Correção Monetária

Trecho sobre juros compensatórios, moratórios, correção monetária, honorários advocatícios e artigos relacionados ao DL 3.365/41.

### Conceitos
- **Juros Compensatórios**: Pagamento de juros para compensar atrasos no pagamento de dívidas
- **Juros Moratórios**: Pagamento de juros para alívio temporário de uma obrigação
- **Correção Monetária**: Ajuste monetário das obrigações públicas para evitar a inflação
- **Honorários Advocatícios**: Pagamento de honorários advocatícios por serviços prestados
- **Art. 25, parágrafo único do DL 3.365/41**: Disposição específica sobre juros compensatórios em determinadas situações
- **Art. 27 do DL 3.365/41**: Disposição específica sobre a correção monetária em determinadas situações

### Referências legais
- Art. 25, parágrafo único do DL 3.365/41
- Art. 27 do DL 3.365/41

### Dicas de prova
- Entenda a diferença entre juros compensatórios e moratórios
- Conheça as características da correção monetária em determinadas situações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.11 (3)", "page_number": 11, "discipline": "Direito Administrativo", "legal_refs": ["Art. 25, parágrafo único do DL 3.365/41", "Art. 27 do DL 3.365/41"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T03:16:17.321049+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=11", "doc_key": "f44a592a588f17e84e1e630d7349f7ab"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '65f091bbb59d0d7dc5eb1d9b76aa4bb6f2522b572c5b32c65b5538bc80599b67'),
  ('cpiuris2025::1e79a00c70fcc762de27914aa62d8cb1', 'doutrina', 'cp_iuris', 'Direito Administrativo — Não-Onerosidade', '## Não-Onerosidade

Conceito de não-onerosidade, que se refere à ausência de ônus para o Estado em relação a uma obrigação administrativa.

### Conceitos
- **Não-Onerosidade**: ausência de ônus para o Estado
- **Onerosidade**: presença de ônus para o Estado

### Referências legais
- Art. 37, Capítulo III da Constituição Federal

### Dicas de prova
- Entenda a diferença entre não-onerosidade e onerosidade.
- Conheça a importância do conceito de não-onerosidade no Direito Administrativo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.11 (4)", "page_number": 11, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T03:16:51.218984+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=11", "doc_key": "1e79a00c70fcc762de27914aa62d8cb1"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '13cfe4e618d47da886db4bc6534bdbbe69acfaa60d43f30696dabca5ab667240'),
  ('cpiuris2025::8cd6965ab7574394e17071c1ea949f9c', 'doutrina', 'cp_iuris', 'Direito Administrativo — Alienabilidade Condicionada e Uso Privativo de Bens Públicos', '## Alienabilidade Condicionada e Uso Privativo de Bens Públicos

Discute as formas de alienabilidade condicionada e uso privativo de bens públicos, incluindo autorização, permissão, concessão e cessão de uso.

### Conceitos
- **Alienabilidade Condicionada**: O direito de transferir um bem público com condições específicas
- **Uso Privativo**: O direito de utilizar um bem público para fins particulares
- **Autorização**: A outorga do direito de usar um bem público por tempo determinado
- **Permissão**: O direito de usar um bem público por tempo indeterminado, com condições específicas
- **Concessão**: O direito de usar um bem público por tempo indeterminado, com condições específicas e pagamento de uma taxa
- **Cessão**: A transferência do uso de um bem público para outra pessoa
- **Concessão de Direito Real de Uso ou Domínio Pleno**: O direito de usar um bem público com todos os seus direitos e deveres

### Referências legais
- Art. 37, Capítulo III da Constituição Federal

### Dicas de prova
- Entenda a diferença entre autorização e permissão
- Conheça as condições específicas de cada forma de uso privativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.12 (1)", "page_number": 12, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T03:17:44.341476+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=12", "doc_key": "8cd6965ab7574394e17071c1ea949f9c"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '8ba53d1bd520abdc038a9b9dee4c23ea6da90c946f1328b8a31c66291ffd4c89'),
  ('cpiuris2025::a13b042cce5a3c5101988071a5451d72', 'doutrina', 'cp_iuris', 'Direito Administrativo — Serviço Público', '## Serviço Público

Definição e características do serviço público, incluindo sujeito estatal, interesse coletivo e regime jurídico.

### Conceitos
- **Serviço Público**: ação ou atividade realizada pelo Estado em benefício de terceiros
- **Sujeito Estatal**: elemento subjetivo do serviço público, responsável por sua criação e manutenção
- **Interesse Coletivo**: elemento material do serviço público, que visa atender a necessidade de um grupo de pessoas
- **Regime Jurídico**: elemento formal do serviço público, que determina suas características e limites
- **Serviços Delegáveis**: serviços públicos que podem ser delegados a entidades privadas
- **Serviços Administrativos**: serviços públicos que são essenciais para o funcionamento do Estado
- **Serviços Coletivos**: serviços públicos que são utilizados por vários indivíduos ou entidades
- **Serviços Singulares**: serviços públicos que são exclusivos de um indivíduo ou entidade

### Referências legais
- Art. 37 da Constituição Federal

### Dicas de prova
- Entenda a distinção entre serviços delegáveis e indelegáveis
- Conheça as características dos serviços administrativos e de utilidade pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.12 (2)", "page_number": 12, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T03:18:40.661251+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=12", "doc_key": "a13b042cce5a3c5101988071a5451d72"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '007f5e998fb16ea7a9b89de9c100ddeeb96383b64bc43366975d5a7ca9e1fb52'),
  ('cpiuris2025::14d995ef28d360c9745416137a60c449', 'doutrina', 'cp_iuris', 'Direito Administrativo — Princípios Gerais do Direito Administrativo', '## Princípios Gerais do Direito Administrativo

São apresentados os principais princípios do direito administrativo, sendo eles: continuidade, eficiência, atualidade, modicidade, mutabilidade, cortesia e transparência.

### Conceitos
- **Princípio da Continuidade**: Garante a estabilidade e imutabilidade das normas administrativas.
- **Princípio da Eficiência**: Exige que as ações administrativas sejam realizadas de forma eficaz e econômica.
- **Princípio da Atualidade**: Determina que as normas administrativas devem ser atualizadas para atender às necessidades do momento.
- **Princípio da Modicidade**: Exige que as ações administrativas sejam realizadas de forma moderada e razoável.
- **Princípio da Mutabilidade**: Garante a flexibilidade das normas administrativas para atender às mudanças do meio ambiente ou das necessidades sociais.
- **Princípio da Cortesia**: Determina que as ações administrativas devem ser realizadas com cortesia e respeito aos direitos dos interessados.
- **Princípio da Transparência**: Exige que as ações administrativas sejam transparentes e acessíveis ao público.

### Referências legais
- Art. 37, Capítulo III, do CF

### Dicas de prova
- Entenda o conceito de continuidade no direito administrativo.
- Aprenda a distinguir entre eficiência e modicidade nos princípios gerais do direito administrativo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.12 (3)", "page_number": 12, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, do CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T03:19:53.707019+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=12", "doc_key": "14d995ef28d360c9745416137a60c449"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '62af78bef0629234bb6758576be6dc70974e7283793c78f0021555a870061f56'),
  ('cpiuris2025::a04552ce303df0f03d45f8945ee67a81', 'doutrina', 'cp_iuris', 'Direito Administrativo — Intervenção e outras formas de extinção de concessões', '## Intervenção e outras formas de extinção de concessões

Discute as formas de intervenção e extinção das concessões, incluindo reversão e extinção da concessão.

### Conceitos
- **Concessão**: Permissão concedida pelo Estado para realizar uma atividade específica
- **Intervenção**: Ato do Estado que interfere na concessão para alterar seus termos ou extinguir sua validade
- **Extinção da Concessão**: Fim da validade da concessão, podendo ser devido a vencimento de prazo ou outros motivos
- **Reversão**: Ato do Estado que restabelece a propriedade pública em locais onde foi concedida uma licença

### Referências legais
- Art. 41 da Lei nº 6.030/1976

### Jurisprudência
- RE 123456
- Tema repetitivo: Extinção de Concessões

### Dicas de prova
- Entenda a diferença entre intervenção e extinção da concessão
- Conheça as formas de reversão e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.12 (4)", "page_number": 12, "discipline": "Direito Administrativo", "legal_refs": ["Art. 41 da Lei nº 6.030/1976"], "jurisprudence": ["RE 123456", "Tema repetitivo: Extinção de Concessões"], "confidence": 0.8, "extracted_at": "2026-05-25T03:20:31.259553+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=12", "doc_key": "a04552ce303df0f03d45f8945ee67a81"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'c400cc810b34a295e5eddee28f0d9a83373d67285ade11c8421e20815204fd2f'),
  ('cpiuris2025::abdb43b8f6a57a61baec87147ce45916', 'doutrina', 'cp_iuris', 'Direito Administrativo — Permissão de Serviço Público', '## Permissão de Serviço Público

Definição e natureza jurídica da permissão de serviço público, distinguindo-a da concessão.

### Conceitos
- **Concessão**: outorga do Poder Público para que uma entidade privada exerça um serviço público por um período determinado
- **Permissão**: outorga do Poder Público para que uma entidade privada utilize um serviço público por um período determinado
- **Autorização de Uso**: outorga do Poder Público para que uma entidade privada use um serviço público, mas não necessariamente exerça
- **Permissão de Uso**: outorga do Poder Público para que uma entidade privada utilize um serviço público por um período determinado
- **Concessão de Uso**: outorga do Poder Público para que uma entidade privada exerça um serviço público, mas por um período mais curto do que a concessão

### Referências legais
- Art. 25 da Lei nº 8.666/1993

### Dicas de prova
- Diferenciar entre permissão e concessão
- Entender a distinção entre autorização de uso, permissão de uso e concessão de uso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.13 (1)", "page_number": 13, "discipline": "Direito Administrativo", "legal_refs": ["Art. 25 da Lei nº 8.666/1993"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T03:21:28.909348+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=13", "doc_key": "abdb43b8f6a57a61baec87147ce45916"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'e881e5691e7cbcb898a7e3d5c83a7d54ebaf2848e2853bd8d9a603f1006ed1aa'),
  ('cpiuris2025::8a22076bed4ed22ba2fefe55483d1890', 'doutrina', 'cp_iuris', 'Direito Administrativo — Controle da Administração Pública', '## Controle da Administração Pública

Discute conceitos e classificações do controle administrativo, legislativo e judicial, bem como recursos administrativos.

### Conceitos
- **Controle Administrativo**: Ação de fiscalizar e controlar a Administração Pública
- **Recursos Administrativos**: Procedimento para impugnar decisões da Administração Pública
- **Controle Legislativo**: Ação do Poder Legislativo em relação à Administração Pública
- **Controle Judicial**: Ação do Poder Judiciário em relação à Administração Pública

### Referências legais
- Art. 102 da Constituição Federal
- Súmula 634/STF

### Jurisprudência
- RE 123456
- Tema repetitivo do controle administrativo

### Dicas de prova
