- Conheça as espécies de controle legislativo e como eles se diferenciam.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.13 (2)", "page_number": 13, "discipline": "Direito Administrativo", "legal_refs": ["Art. 102 da Constituição Federal", "Súmula 634/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo do controle administrativo"], "confidence": 0.8, "extracted_at": "2026-05-25T03:22:23.308156+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=13", "doc_key": "8a22076bed4ed22ba2fefe55483d1890"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'd6ce30e79cbc94e28c87513b6d691d450cbadaa7ca5616200308a055a1ee3bc6'),
  ('cpiuris2025::d499881f90f5e08bbc430b26366d5431', 'doutrina', 'cp_iuris', 'Direito Administrativo — Improbidade Administrativa', '## Improbidade Administrativa

Capítulo que aborda a competência, sujeitos passivo e ativo, responsabilidade sucessória e tipos de improbidade administrativa.

### Conceitos
- **Enriquecimento Ilícito**: Ação em que o administrador ou servidor público é processado por ter obtido vantagem indevida com o patrimônio da entidade pública.
- **Dano ao Erário**: Ação em que o administrador ou servidor público é processado por ter causado prejuízo financeiro à entidade pública.
- **Responsabilidade Sucessória**: O dever de responder pelos atos cometidos no exercício da função pública, mesmo após a extinção do cargo ou da administração.
- **Sujeito Passivo**: A entidade pública ou o Estado que sofre os prejuízos causados pela improbidade administrativa.
- **Sujeito Ativo**: O administrador ou servidor público responsável pelos atos que resultam em improbidade administrativa.
- **Competência**: A autoridade judiciária competente para julgar os processos relacionados à improbidade administrativa.
- **Agentes Políticos**: Os membros do governo ou da administração pública que podem ser responsabilizados por atos de improbidade administrativa.
- **Tipologia de Improbidade**: A classificação dos tipos de improbidade administrativa, como o Enriquecimento Ilícito, Dano ao Erário e outros.

### Referências legais
- Art. 37, Capítulo III da CF
- Súmula 373 do STF

### Jurisprudência
- RE 123456/SP
- Tema repetitivo: Responsabilidade Administrativa

### Dicas de prova
- Entenda a competência e os sujeitos passivo e ativo na improbidade administrativa.
- Conheça as diferentes tipologias de improbidade administrativa e suas consequências.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.13 (3)", "page_number": 13, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III da CF", "Súmula 373 do STF"], "jurisprudence": ["RE 123456/SP", "Tema repetitivo: Responsabilidade Administrativa"], "confidence": 0.8, "extracted_at": "2026-05-25T03:23:27.382265+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=13", "doc_key": "d499881f90f5e08bbc430b26366d5431"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'bc2682469fefda4ef4dfe34c06ecc3cc6e5fa8e11437b0aa51c753156db2d0ad'),
