  ('cpiuris2025::37cb42b96fe86f85a1fa3208041aaf57', 'doutrina', 'cp_iuris', 'Direito Administrativo — Sanções administrativas', '## Sanções administrativas

Discute as sanções administrativas, incluindo a quadra comparativa entre os tipos de improbidade e comentários importantes.

