- Conheça as regras que determinam o início e desenvolvimento do processo administrativo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.14 (2)", "page_number": 14, "discipline": "Direito Administrativo", "legal_refs": ["Art. 3º da Lei nº 9.784/1998", "Súmula 355 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Processo Administrativo"], "confidence": 0.8, "extracted_at": "2026-05-25T03:25:06.043976+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=14", "doc_key": "b2f8ab09f3096cbc1f7f54a9d936beda"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b43ef0b18fbf5c71f9238ec05d2d0d23096035cf5255605013d4309639863a0f'),
  ('cpiuris2025::84587c4320cf14cb0a5d7da3934cabed', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilização em Direito Administrativo', '## Responsabilização em Direito Administrativo

Tratamento da responsabilidade das pessoas jurídicas e dos dirigentes, bem como alterações contratuais e sanções administrativas.

### Conceitos
- **Pessoa Jurídica**: Entidade que pode ser responsabilizada por atos ou omissões
- **Dirigente**: Pessoal que exerce poderes de gestão em uma entidade jurídica
- **Responsabilidade Solidária**: Condição em que a pessoa jurídica e seus dirigentes são responsáveis pela mesma obrigação
- **Sanção Administrativa**: Medida adotada pelo Estado para punir ou corrigir um ato ilegal

### Referências legais
- Art. 5º da Lei nº X
- ...

### Jurisprudência
- RE 123456
- ...

