- Entenda a distinção entre responsabilidade e sanção administrativa
- Conheça as condições de responsabilidade solidária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.14 (3)", "page_number": 14, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º da Lei nº X", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T03:25:41.361266+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=14", "doc_key": "84587c4320cf14cb0a5d7da3934cabed"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '8aa8f940c01e03e4eb518f3ac82ca5b357f48f15798031fe624cf2271d8aaa38'),
  ('cpiuris2025::9e93475a01b5fb5eb1040d9b73560d79', 'doutrina', 'cp_iuris', 'Direito Administrativo — Origem e Conceito do Direito Administrativo', '## Origem e Conceito do Direito Administrativo

O Direito Administrativo tem sua origem nos ideais liberais da Revolução Francesa de 1789, como a separação de poderes, princípio da legalidade e Declaração dos Direitos do Homem e do Cidadão. O Direito Administrativo foi concebido como ramo especial do Direito Público, regulador das relações entre o Estado e as atividades administrativas.

### Conceitos
- **Princípio da Legalidade**: Submissão do Estado à lei
- **Princípio da Separação de Poderes**: Mecanismo de limitação do exercício do poder estatal
- **Declaração dos Direitos do Homem e do Cidadão**: Consagra direitos fundamentais que são oponíveis ao Estado

### Referências legais
- Lei do 28 pluviose do ano VIII de 1800

### Jurisprudência
- Caso Blanco (1873)

### Dicas de prova
- Entenda a importância dos ideais liberais da Revolução Francesa para o surgimento do Direito Administrativo
- Conheça as três conquistas revolucionárias que justificam as limitações ao poder estatal e a proteção dos cidadãos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.15", "page_number": 15, "discipline": "Direito Administrativo", "legal_refs": ["Lei do 28 pluviose do ano VIII de 1800"], "jurisprudence": ["Caso Blanco (1873)"], "confidence": 0.8, "extracted_at": "2026-05-25T03:26:46.072521+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=15", "doc_key": "9e93475a01b5fb5eb1040d9b73560d79"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '7675dedc1889c815da0d753ac73a04cbb87a85d14de2929d6fdcc82361577a4c'),
  ('cpiuris2025::ae42e0635ca664aa6671ad338712f485', 'doutrina', 'cp_iuris', 'Direito Administrativo — Conceitos do Direito Administrativo', '## Conceitos do Direito Administrativo

O conceito de Direito Administrativo pode variar de acordo com a definição adotada, sendo considerados critérios como o Serviço Público, Poder Executivo, Relações Jurídicas, Teleológico, Negativo ou Residual e da Administração Pública.

### Conceitos
- **Critério do Serviço Público**: Fixa a competência dos Tribunais Administrativos em função da execução de serviços públicos.
- **Critério do Poder Executivo**: O Direito Administrativo seria o estudo do Poder Executivo, mas esse critério é insuficiente.
- **Critério das Relações Jurídicas**: Considera o Direito Administrativo como o conjunto de normas que regem as relações entre a Administração e os administrados.
- **Critério Teleológico**: O sistema dos princípios jurídicos que regula a atividade do Estado para o cumprimento de seus fins de utilidade pública.
- **Critério Negativo ou Residual**: Tem por objeto as atividades desenvolvidas para a consecução dos fins estatais, excluídas a legislação e a jurisdição.
- **Critério da Administração Pública**: O conjunto de princípios que regem a Administração Pública.
- **Administração Pública**: Compreende dois sentidos: subjetivo e objetivo.
- **Utilidade Pública**: Os fins desejados pelo Estado.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda os critérios do Direito Administrativo e suas limitações.
- Conheça a Administração Pública em sentido subjetivo e objetivo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.16 (1)", "page_number": 16, "discipline": "Direito Administrativo", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T03:27:51.649787+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=16", "doc_key": "ae42e0635ca664aa6671ad338712f485"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '81fa36f2988ad0542cd2525a93f933afe1349f7d9a96549146adccf16f566fdd'),
  ('cpiuris2025::cceea15d66bdafc2c4999b975304ccf0', 'doutrina', 'cp_iuris', 'Direito Administrativo — Escolas e Critérios do Direito Administrativo', '## Escolas e Critérios do Direito Administrativo

As escolas exegética e da puissance publique apresentam critérios diferentes para o Direito Administrativo, sendo a primeira limitada à compilação de atos normativos existentes e a segunda que diferencia entre atos de império e gestão.

### Conceitos
- **Escola Exegética**: Limita-se à compilação de atos normativos existentes
- **Escola da Puissance Publique**: Diferencia entre atos de império e gestão
- **Atos de Império**: Ato unilateralmente imposto ao particular sem autorização judicial
- **Atos de Gestão**: Ato praticado em situação de igualdade com os particulares

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre atos de império e gestão
- Conheça as escolas exegética e da puissance publique', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.16 (2)", "page_number": 16, "discipline": "Direito Administrativo", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T03:28:29.973508+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=16", "doc_key": "cceea15d66bdafc2c4999b975304ccf0"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '1b0312e61a58c8c0e487c9bd5101c257a2921b2f214d03a827115c4ef301a47d'),
  ('cpiuris2025::32dd7de9010ff333dbf67d67fcd193c1', 'doutrina', 'cp_iuris', 'Direito Administrativo — Fontes do Direito Administrativo', '## Fontes do Direito Administrativo

As fontes do Direito Administrativo são a lei, doutrina, jurisprudência, costumes e precedentes administrativos.

### Conceitos
- **Lei**: fonte formal do Direito
- **Doutrina**: opiniões dos estudiosos sobre os institutos e as normas do Direito
- **Jurisprudência**: reiteradas decisões de tribunais sobre determinado assunto ou tema
- **Costumes**: comportamento reiterado de um povo em um determinado tempo e local
- **Precedentes Administrativos**: normas jurídicas retiradas de decisões administrativasanteriores, válidas e de acordo com o interesse público

### Referências legais
- Art. 4º da LINDB

### Dicas de prova
- Entenda a distinção entre lei e doutrina
- Conheça as diferentes formas de costumes (secundum legem, praeter legem e contra legem)
- Aprenda com os precedentes administrativos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.17", "page_number": 17, "discipline": "Direito Administrativo", "legal_refs": ["Art. 4º da LINDB"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T03:29:29.051325+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=17", "doc_key": "32dd7de9010ff333dbf67d67fcd193c1"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '960961cd6547930847f1c9af5c3ef69ca0fc68d0c85e768157e0b081ae16b8dd'),
  ('cpiuris2025::8179c52101baa8a6ea6143b07f027f9a', 'doutrina', 'cp_iuris', 'Direito Administrativo — Administração Pública e Regime Jurídico Administrativo', '## Administração Pública e Regime Jurídico Administrativo

A Administração Pública é a atividade exercida pela Administração Pública, direta ou indiretamente, para satisfazer às necessidades coletivas. O Regime Jurídico Administrativo é o conjunto de traços que desenham o Direito Administrativo, colocando a Administração Pública em uma posição privilegiada.

### Conceitos
- **Administração Pública**: Atividade exercida pela Administração Pública, direta ou indiretamente, para satisfazer às necessidades coletivas.
- **Prerrogativas**: Vantagens lícitas conferidas à Administração Pública em razão da Supremacia do Interesse Público sobre o interesse privado.
- **Súmula Vinculante Nº 38 do STF**: É competente o município para fixar o horário de funcionamento de estabelecimento comercial.

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- Súmula Nº 19 do STJ
- Súmula Vinculante Nº 38 do STF
- Súmula Vinculante Nº 49 do STF

### Dicas de prova
- Entenda a diferença entre Administração Pública e Regime Jurídico Administrativo.
- Conheça as prerrogativas conferidas à Administração Pública.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.18", "page_number": 18, "discipline": "Direito Administrativo", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["Súmula Nº 19 do STJ", "Súmula Vinculante Nº 38 do STF", "Súmula Vinculante Nº 49 do STF"], "confidence": 0.8, "extracted_at": "2026-05-25T03:31:16.831790+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=18", "doc_key": "8179c52101baa8a6ea6143b07f027f9a"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '2a9bed25e7cc14b8c83f61bc100f0f4c216857060e771d309b37b1dde29ef407'),
  ('cpiuris2025::ccced19b8fd78f3380050a9da7dd66c4', 'doutrina', 'cp_iuris', 'Direito Administrativo — Princípios que regem o Direito Administrativo', '## Princípios que regem o Direito Administrativo

Os princípios do Direito Administrativo são fundamentais para garantir a validade e a eficácia das ações administrativas. Eles incluem a legalidade, impessoalidade, moralidade, publicidade e eficiência.

### Conceitos
- **Princípio da Legalidade**: Garante respeito aos direitos individuais e estabelece limites para a atuação do Estado
- **Impessoalidade**: Proíbe que o Estado faça favores ou benefícios a determinadas pessoas
- **Moralidade**: Exige que os agentes públicos agam com integridade e honestidade
- **Publicidade**: Requer que as ações administrativas sejam transparentes e divulgadas ao público
- **Eficiência**: Exige que as ações administrativas sejam realizadas de forma eficaz e econômica

### Referências legais
- Art. 37, caput da CF/88

### Dicas de prova
- Entenda o conceito de Princípio da Legalidade e como ele se aplica à Administração Pública
- Identifique as características da Impessoalidade e do Moralidade nos atos administrativos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.19 (1)", "page_number": 19, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, caput da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T03:32:09.569526+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=19", "doc_key": "ccced19b8fd78f3380050a9da7dd66c4"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '778755f618c2c7d7d2af3b86ef831613c2d4478a5e95544bffb92c8c11eb9df8'),
  ('cpiuris2025::e43cff86dee6ad606bbd3826256c1452', 'doutrina', 'cp_iuris', 'Direito Administrativo — Autorização Legislativa e Limitações do Administrador Público', '## Autorização Legislativa e Limitações do Administrador Público

A validade da atuação do administrador público depende de autorização legislativa prévia, protegendo os indivíduos contra abusos de conduta.

### Conceitos
- **Autorização Legislativa**: Previa autorização legislativa para a validade da atuação do administrador público
- **Limitações do Administrador Público**: O administrador não pode fazer prevalecer sua vontade pessoal, limitado pela lei
- **Autonomia de Vontade**: A Administração Pública não tem autonomia de vontade, sujeita às leis e regulamentações

### Referências legais
- Art. 37 da Constituição Federal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre autorização legislativa e autonomia de vontade
- Limitações do administrador público em relação à sua vontade pessoal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.19 (2)", "page_number": 19, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37 da Constituição Federal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T03:32:54.492200+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=19", "doc_key": "e43cff86dee6ad606bbd3826256c1452"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '05ab93f75fadb900f5f0306b168a0bf8613a1228fddff66c73c2308e3478a80f'),
  ('cpiuris2025::95b877bd504ce4f9961865e7976a5920', 'doutrina', 'cp_iuris', 'Direito Administrativo — Princípio da Legalidade e sua aplicação na Administração Pública', '## Princípio da Legalidade e sua aplicação na Administração Pública

O Princípio da Legalidade é fundamental para a Administração Pública, garantindo que as ações do Estado sejam previstas em lei ou tenham uma base jurídica. Ele pode ser dividido em supremacia da lei e reserva de lei, com a última prevalecendo no Brasil.

### Conceitos
- **Princípio da Legalidade**: Garante que as ações do Estado sejam previstas em lei ou tenham uma base jurídica
- **Supremacia da Lei**: A lei prevalece sobre os atos da Administração, limitando sua liberdade de agir
- **Reserva de Lei**: Tratamento de certas matérias formalizado necessariamente pela legislação, excluindo a utilização de outros atos com caráter normativo
- **Vinculação Negativa**: Limitação para a atuação do administrador, permitindo que o Estado atue com maior liberdade em sua ausência
- **Vinculação Positiva**: Condição de validade da atuação dos agentes públicos à prévia autorização legal
- **Autonomia da Vontade**: Regra para os particulares, permitindo que eles façam tudo o que a Lei não proíbe

### Referências legais
- Art. 5º, II da CR/88
- Art. 2º da Lei 9.784/99

### Dicas de prova
- Entenda a distinção entre supremacia da lei e reserva de lei
- Conheça o conceito de vinculação negativa e positiva
- Avalie a importância da autonomia da vontade para os particulares', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.20 (1)", "page_number": 20, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º, II da CR/88", "Art. 2º da Lei 9.784/99"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T03:34:01.257072+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=20", "doc_key": "95b877bd504ce4f9961865e7976a5920"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '914d0398d4f80ec677d73abdfe350cc2a1f628be4236b2837681992a66981224'),
  ('cpiuris2025::76e40afff7f24673e7c5c3c14a61bb21', 'doutrina', 'cp_iuris', 'Direito Administrativo — Constitucionalização do Direito Administrativo e princípio da legalidade estrita', '## Constitucionalização do Direito Administrativo e princípio da legalidade estrita

O administrador público deve obediência direta à Constituição e aos princípios jurídicos, adotando a legalidade estrita e evitando interpretações extensivas ou restritivas sem a presença de lei que assim determinar.

### Conceitos
- **Constitucionalização do Direito Administrativo**: Adoção da Constituição como fonte principal do direito administrativo
- **Princípio da Legalidade Estrita**: Obrigação de obediência aos preceitos legais sem interpretação extensiva ou restritiva

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal

### Jurisprudência
- Súmula 636 - STF

### Dicas de prova
- Distinção entre interpretação extensiva e restritiva
- Importância do princípio da legalidade estrita', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.20 (2)", "page_number": 20, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal"], "jurisprudence": ["Súmula 636 - STF"], "confidence": 0.8, "extracted_at": "2026-05-25T03:34:35.408997+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=20", "doc_key": "76e40afff7f24673e7c5c3c14a61bb21"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'e375f88239c0d2433333b6b200f10acdeafa73e4f2956ff49868fb9c0f1a3651'),
  ('cpiuris2025::cc5f3120cd871e92ca2633f95d90a4f8', 'doutrina', 'cp_iuris', 'Direito Administrativo — Princípio da Impessoalidade', '## Princípio da Impessoalidade

O princípio da impessoalidade exige que a Administração Pública atue de forma objetiva e sem discriminação, promovendo igualdade de acesso a todos os cidadãos.

### Conceitos
- **Impessoalidade**: Princípio que exige a Administração Pública atuar de forma objetiva e sem discriminação
- **Isonomia**: Ideia de igualdade perante a lei, que contempla um caráter material para concretizar a justiça social
- **Hipossuficiência econômica**: Situação em que uma pessoa não tem condições de arcar com os custos de uma inscrição no concurso público

### Referências legais
- Art. 3º da CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a finalidade do princípio da impessoalidade e como ele se relaciona com a igualdade de acesso aos concursos públicos
- Análise crítica das medidas que fomentam ou restringem o acesso à via concursal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.21 (1)", "page_number": 21, "discipline": "Direito Administrativo", "legal_refs": ["Art. 3º da CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T03:35:31.311051+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=21", "doc_key": "cc5f3120cd871e92ca2633f95d90a4f8"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '34a7d1485c51fd61bbb05657293120db5f25504a4f7a5b355bffcb7b36781ae4'),
  ('cpiuris2025::95a4b456bcb5230abff805c2934ea215', 'doutrina', 'cp_iuris', 'Direito Administrativo — Princípios da Administração Pública', '## Princípios da Administração Pública

A Administração Pública é responsável pelo interesse público, não podendo ser alcançado o interesse privado. Relaciona-se à ideia do Princípio da Finalidade.

### Conceitos
- **Teoria do Órgão**: aplicação da teoria do órgão no Direito brasileiro
- **Princípio da Impessoalidade**: ideia de que a Administração Pública deve buscar o interesse público
- **Teoria da Dupla Garantia**: temática responsabilidade civil do Estado, nos termos da jurisprudência do STF
- **Princípio da Finalidade**: ideia de que a Administração Pública deve buscar o interesse público

### Referências legais
- Art. 37 da Constituição Federal

### Jurisprudência
- ADI 3.918, Relator(a): Dias Toffoli, Tribunal Pleno, julgado em 16/5/2022
- Súmula 643 do STF

### Dicas de prova
- Entenda a Teoria do Órgão e sua aplicação no Direito brasileiro
- Conheça os Princípios da Impessoalidade e da Finalidade
- Aprenda com a Teoria da Dupla Garantia e sua relação com a responsabilidade civil do Estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.21 (2)", "page_number": 21, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37 da Constituição Federal"], "jurisprudence": ["ADI 3.918, Relator(a): Dias Toffoli, Tribunal Pleno, julgado em 16/5/2022", "Súmula 643 do STF"], "confidence": 0.8, "extracted_at": "2026-05-25T03:36:17.621948+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=21", "doc_key": "95a4b456bcb5230abff805c2934ea215"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '5a6bd5cae6ef2ca517f046dff16d4193b56552efbe2a30748cf499408ca58dca'),
  ('cpiuris2025::42a6e4ae903314404e1e4d328233b7a7', 'doutrina', 'cp_iuris', 'Direito Administrativo — Princípio da Impessoalidade e Princípio da Publicidade', '## Princípio da Impessoalidade e Princípio da Publicidade

O artigo 37, § 1º, da CR/88 estabelece a publicidade dos atos dos órgãos públicos com caráter educativo, informativo ou de orientação social, vedando a promoção pessoal de autoridades e servidores públicos.

### Conceitos
- **Impessoalidade**: Vedação da promoção pessoal
- **Publicidade**: Caráter educativo, informativo ou de orientação social dos atos dos órgãos públicos
- **Princípio da Moralidade**: Administração Pública deve atuar de forma proba e com ética
- **Dever de Probidade**: Agentes públicos devem agir com probidade

### Referências legais
- Art. 37, § 1º da CR/88
- Art. 11, XII da Lei nº 8.429/92

### Jurisprudência
- Súmula Vinculante 13 do STF

### Dicas de prova
- Entenda o Princípio da Impessoalidade e sua relação com a Publicidade
- Conheça os princípios administrativos e suas violações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.22", "page_number": 22, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, § 1º da CR/88", "Art. 11, XII da Lei nº 8.429/92"], "jurisprudence": ["Súmula Vinculante 13 do STF"], "confidence": 0.8, "extracted_at": "2026-05-25T03:37:09.254406+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=22", "doc_key": "42a6e4ae903314404e1e4d328233b7a7"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '890876d845a2e2c6954edb766775b9ee196c248a7f4fde2230e18860f6f8eb0d'),
  ('cpiuris2025::0dbb37a87be41552bc5be544d40135e2', 'doutrina', 'cp_iuris', 'Direito Administrativo — Nepotismo na Administração Pública', '## Nepotismo na Administração Pública

O nepotismo é proibido na administração pública direta e indireta, tanto no emprego direto quanto em funções gratificadas, de acordo com a Constituição Federal e a Súmula Vinculante n.º 13 do STF.

### Conceitos
- **Nepotismo**: Prática de nomear ou indicar parentes ou pessoas próximas em linhas de afinalidade para cargos públicos
- **Súmula Vinculante n.º 13 do STF**: Proíbe a nomeação de cônjuge, companheiro ou parente em linha reta, colateral ou por afinidade para cargos públicos
- **Lei nº 8.429/92**: Estabelece que não se configura improbidade a mera nomeação ou indicação política, necessitando-se de aferição de dolo com finalidade ilícita

### Referências legais
- Art. 11, §5º, da Lei nº 8.429/92
- Súmula Vinculante n.º 13 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Nepotismo na Administração Pública

### Dicas de prova
- Entenda a distinção entre nepotismo direto e transverso
- Conheça as Súmulas Vinculantes do STF relacionadas ao nepotismo
- Aprenda a aplicação da Lei nº 8.429/92 no contexto da administração pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.23 (1)", "page_number": 23, "discipline": "Direito Administrativo", "legal_refs": ["Art. 11, §5º, da Lei nº 8.429/92", "Súmula Vinculante n.º 13 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Nepotismo na Administração Pública"], "confidence": 0.9, "extracted_at": "2026-05-25T03:38:20.160530+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=23", "doc_key": "0dbb37a87be41552bc5be544d40135e2"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'a3217423a86acdd83c57a37e9601a04f374c332b6b8afbf6ef0b6c97dbea5757'),
  ('cpiuris2025::45f6b406810af59e258a0cd95efb6cd8', 'doutrina', 'cp_iuris', 'Direito Administrativo — Regulamentação de Matéria Pública', '## Regulamentação de Matéria Pública

Não é necessária a edição de lei para regulamentar a matéria pública, e mesmo que haja uma lei, ela não é de iniciativa exclusiva do chefe do poder executivo.

### Conceitos
- **iniciativa legislativa**: não exclusiva do chefe do poder executivo
- **regulamentação de matéria pública**: não necessária edição de lei
- **natureza política**: cargos como Secretários Municipais e Ministros de Estado

### Referências legais
- Art. 84, CF; Art. 52, CF

### Jurisprudência
- 9 STF - Rcl 28.024 AgR
- 10 BRASIL. Supremo Tribunal Federal. [Tese definida no RE 570.392]
- 11 BRASIL. Supremo Tribunal Federal. [Tese definida no RE 579.951]

### Dicas de prova
- Distinção entre iniciativa legislativa e executiva
- Importância da regulamentação de matéria pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.23 (2)", "page_number": 23, "discipline": "Direito Administrativo", "legal_refs": ["Art. 84, CF; Art. 52, CF"], "jurisprudence": ["9 STF - Rcl 28.024 AgR", "10 BRASIL. Supremo Tribunal Federal. [Tese definida no RE 570.392]", "11 BRASIL. Supremo Tribunal Federal. [Tese definida no RE 579.951]"], "confidence": 0.8, "extracted_at": "2026-05-25T03:39:00.174006+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=23", "doc_key": "45f6b406810af59e258a0cd95efb6cd8"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'd30c3e8a6aa06f1317320216338c940b5d04f4362ffd6283b1bade68c4e8bd16'),
  ('cpiuris2025::b2142fad2f367ceb01efcc5d6c6078a3', 'doutrina', 'cp_iuris', 'Direito Administrativo — Nepotismo em Administração Pública', '## Nepotismo em Administração Pública

A Carta da República proíbe a nomeação de parentes de funcionários públicos para cargos comissionados, salvo em casos de designações recíprocas. O STF entende que incide o conteúdo da Súmula 14, mas também reconhece a existência de nepotismo se não há influência hierárquica sobre a nomeação.

### Conceitos
- **Nepotismo**: Prática de nomear parentes para cargos comissionados
- **Designações recíprocas**: Troca de favores entre chefe e funcionário, vedada pela Súmula Vinculante 13
- **Projeção funcional**: Conexão hierárquica entre o nomeado e o agente político ou servidor público de referência

### Referências legais
- Art. 37, Capítulo III da Carta da República
- Súmula 14 do STF
- Súmula Vinculante 13 do STF
- Súmula 663 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Nepotismo em Administração Pública

### Dicas de prova
- Distinção entre nepotismo e designações recíprocas
- Importância da projeção funcional na configuração de nepotismo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.24 (1)", "page_number": 24, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III da Carta da República", "Súmula 14 do STF", "Súmula Vinculante 13 do STF", "Súmula 663 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Nepotismo em Administração Pública"], "confidence": 0.8, "extracted_at": "2026-05-25T03:39:55.051588+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=24", "doc_key": "b2142fad2f367ceb01efcc5d6c6078a3"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'd6cefba01cc6df43fe23ca8b5ebf720afb8c3333abc78264e617c5a72a24ede4'),
  ('cpiuris2025::9b0b75751ed0486f8156bc616c98c6e2', 'doutrina', 'cp_iuris', 'Direito Administrativo — Controle e fiscalização dos atos administrativos', '## Controle e fiscalização dos atos administrativos

O controle e a fiscalização dos atos administrativos são fundamentais para garantir a legalidade e a moralidade dos atos da Administração.

### Conceitos
- **Publicidade**: Ato que é divulgado ao público, mas não necessariamente é uma publicação formal
- **Publicação**: Ato que é formalmente divulgado ao público
- **Controle**: Meção que visa garantir a legalidade e a moralidade dos atos administrativos
- **Fiscalização**: Ação que visa monitorar e controlar os atos administrativos
- **Administração**: Poder público que exerce o controle e a fiscalização dos atos de seus agentes

### Referências legais
- Art. 102 da Constituição Federal
- Art. 75 do Código de Processo Administrativo

### Jurisprudência
- ADI 3.680/2020
- Rcl. 6702-AgR-MC/PR
- Rcl. 18564/SP

### Dicas de prova
- Diferenciar publicidade e publicação
- Entender o conceito de controle e fiscalização nos atos administrativos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.24 (2)", "page_number": 24, "discipline": "Direito Administrativo", "legal_refs": ["Art. 102 da Constituição Federal", "Art. 75 do Código de Processo Administrativo"], "jurisprudence": ["ADI 3.680/2020", "Rcl. 6702-AgR-MC/PR", "Rcl. 18564/SP"], "confidence": 0.8, "extracted_at": "2026-05-25T03:40:48.023246+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=24", "doc_key": "9b0b75751ed0486f8156bc616c98c6e2"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b5d6f8a2ad58bb9422c75cfaf049872a684ab54bab4c2cf8990b76dae186a29e'),
  ('cpiuris2025::e09e8cacb84324eeccb1a14802f69865', 'doutrina', 'cp_iuris', 'Direito Administrativo — Princípio da Publicidade e privacidade dos servidores públicos', '## Princípio da Publicidade e privacidade dos servidores públicos

O Princípio da Publicidade não é absoluto, havendo hipóteses em que o sigilo é necessário ao exercício profissional ou à segurança da sociedade. A Administração Pública pode publicar informações sobre seus servidores públicos, incluindo seu nome e vencimentos.

### Conceitos
- **Princípio da Publicidade**: Básico da Administração Pública, visando à eficiência
- **Privacidade dos servidores públicos**: Não protegida na mesma medida que a do cidadão comum
- **Sigilo**: Hipótese em que o Princípio da Publicidade não é aplicável

### Referências legais
- Art. 5º XIV da Constituição
- Art. 5º XXXIII da Constituição
- Art. 5º LX da Constituição
- Lei nº 13.709/18 (LGPD)

### Jurisprudência
- SS 3902/SP
- Enunciado 15 do CJF

### Dicas de prova
- Distinção entre privacidade dos servidores públicos e do cidadão comum
- Hipóteses em que o sigilo é necessário ao exercício profissional ou à segurança da sociedade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.25 (1)", "page_number": 25, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º XIV da Constituição", "Art. 5º XXXIII da Constituição", "Art. 5º LX da Constituição", "Lei nº 13.709/18 (LGPD)"], "jurisprudence": ["SS 3902/SP", "Enunciado 15 do CJF"], "confidence": 0.8, "extracted_at": "2026-05-25T03:41:39.737899+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=25", "doc_key": "e09e8cacb84324eeccb1a14802f69865"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'c43372cdfcfd5385cee5a55ffb3d288973bc2446af0e83acd09e302a52110916'),
  ('cpiuris2025::d3a913ddd4f0bb2bc91706ac0eaef6ad', 'doutrina', 'cp_iuris', 'Direito Administrativo — Atribuições legais do serviço público', '## Atribuições legais do serviço público

O serviço público deve informar as hipóteses em que realizam o tratamento de dados pessoais e indicar um encarregado quando necessário, de acordo com a LGPD.

### Conceitos
- **LGPD**: Lei Geral de Proteção de Dados
- **Atribuições legais do serviço público**: Responsabilidades do serviço público em relação ao tratamento de dados pessoais

### Referências legais
- Art. 23 da LGPD

### Jurisprudência
- ARE 652777/SP
- ADI 5.371

### Dicas de prova
- Entenda a importância das atribuições legais do serviço público em relação ao tratamento de dados pessoais.
- Identifique as hipóteses em que o serviço público deve informar sobre o tratamento de dados pessoais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.25 (2)", "page_number": 25, "discipline": "Direito Administrativo", "legal_refs": ["Art. 23 da LGPD"], "jurisprudence": ["ARE 652777/SP", "ADI 5.371"], "confidence": 0.8, "extracted_at": "2026-05-25T03:42:11.061883+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=25", "doc_key": "d3a913ddd4f0bb2bc91706ac0eaef6ad"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '880fa564c891e1e5a3fb455d4bb1d00fdd97330a0c75a0abebb2f3e0c592d9fa'),
  ('cpiuris2025::e17e2868aed6369480a90ba2563797db', 'doutrina', 'cp_iuris', 'Direito Administrativo — Compartilhamento de Dados Pessoais', '## Compartilhamento de Dados Pessoais

O compartilhamento de dados pessoais entre a Administração Pública e entidades privadas está sujeito a restrições legais, com exceção em casos específicos de execução descentralizada de atividade pública ou prevenção de fraudes.

### Conceitos
- **Compartilhamento de Dados**: A transferência de dados pessoais entre a Administração Pública e entidades privadas
- **LGPD**: Lei Geral de Proteção de Dados
- **Administração Pública**: Poder público que exerce atividades em nome do Estado

### Referências legais
- Art. 25 da LGPD
- Art. 26, § 1º da LGPD
- Lei nº 12.527/2011 (Lei de Acesso à Informação)

### Dicas de prova
- Entenda a importância do consentimento do titular nos casos de compartilhamento de dados.
- Conheça as exceções ao consentimento previstas na LGPD.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.26 (1)", "page_number": 26, "discipline": "Direito Administrativo", "legal_refs": ["Art. 25 da LGPD", "Art. 26, § 1º da LGPD", "Lei nº 12.527/2011 (Lei de Acesso à Informação)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T03:43:06.702670+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=26", "doc_key": "e17e2868aed6369480a90ba2563797db"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b21b11e4b9b71c222c0ca7589525869e905394ca3f745bded69d1dc04bfddaf8'),
  ('cpiuris2025::9418a9255154806719e555550afe4d17', 'doutrina', 'cp_iuris', 'Direito Administrativo — Eficiência e Economia na Administração Pública', '## Eficiência e Economia na Administração Pública

A eficiência é um princípio expresso da administração pública, considerando as consequências econômicas das normas jurídicas. Além disso, a administração deve considerar outros aspectos como qualidade do serviço, durabilidade e confiabilidade.

### Conceitos
- **Eficiência**: Princípio expresso da administração pública
- **Economia**: Consideração das consequências econômicas nas normas jurídicas
- **Qualidade do serviço ou do bem**: Aspecto a ser considerado na tomada de decisões da administração
- **Durabilidade**: Aspecto a ser considerado na tomada de decisões da administração
- **Confiabilidade**: Aspecto a ser considerado na tomada de decisões da administração

### Referências legais
- EC nº 19/98

### Dicas de prova
- Entenda o conceito de eficiência e sua relação com a economia
- Identifique os aspectos que a administração pública deve considerar além da economia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.26 (2)", "page_number": 26, "discipline": "Direito Administrativo", "legal_refs": ["EC nº 19/98"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T03:43:47.693977+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=26", "doc_key": "9418a9255154806719e555550afe4d17"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'c8ea4f4c5548e654f7edf84bce2f5d28a65aed2b65a3afac3327df0111892209'),
  ('cpiuris2025::a8062ba9e2144aee9f4fc2c1c383493c', 'doutrina', 'cp_iuris', 'Direito Administrativo — Princípios da Administração Pública', '## Princípios da Administração Pública

A administração pública deve atender aos princípios da eficiência, prevalência do interesse público e proporcionalidade. A eficiência é a medida administrativa mais eficaz quando implementa resultados com maior intensidade e custos possíveis. A prevalência do interesse público sobre o privado garante vantagens à Administração Pública em conflitos entre os dois.

### Conceitos
- **Princípio da Eficiência**: A medida administrativa mais eficaz quando implementa resultados com maior intensidade e custos possíveis
- **Prevalência do Interesse Público**: Garante vantagens à Administração Pública em conflitos entre o interesse público e o privado
- **Proporcionalidade**: A medida administrativa deve ser razoável e proporcional ao objetivo pretendido

### Referências legais
- Art. 20 do Decreto-Lei n. 4.657/1942

### Jurisprudência
- REsp 1.888.049-CE

### Dicas de prova
- Entenda a diferença entre o Princípio da Eficiência e a Prevalência do Interesse Público
- Conheça os princípios implícitos da Administração Pública, como Proporcionalidade e Segurança Jurídica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.27", "page_number": 27, "discipline": "Direito Administrativo", "legal_refs": ["Art. 20 do Decreto-Lei n. 4.657/1942"], "jurisprudence": ["REsp 1.888.049-CE"], "confidence": 0.8, "extracted_at": "2026-05-25T03:44:44.031464+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=27", "doc_key": "a8062ba9e2144aee9f4fc2c1c383493c"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '832dc98f578520f9f08cbedb2d5bb67f71fb9f32b410ec809fcdd9ee409c42c8'),
  ('cpiuris2025::d368e5c23b908d5d2354d721fc2cd514', 'doutrina', 'cp_iuris', 'Direito Administrativo — Princípio da Supremacia do Interesse Público', '## Princípio da Supremacia do Interesse Público

O Princípio da Supremacia do Interesse Público sobre o Privado é fundamental para a Administração Pública, permitindo que o interesse público sobressaia sobre o privado. Isso é alcançado concedendo prerrogativas à Administração Pública.

### Conceitos
- **Princípio da Supremacia do Interesse Público**: Permite que o interesse público sobressaia sobre o privado
- **Interesse Público Primário**: Corresponde à finalidade pública
- **Interesse Público Secundário**: Interesse do Estado, enquanto pessoa jurídica apartada

### Referências legais
- Art. 37 da Constituição Federal

### Dicas de prova
- Distinção entre interesse público primário e secundário
- Importância do Princípio da Supremacia do Interesse Público
- Conceito de Administração Pública como gestora do interesse público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.28 (1)", "page_number": 28, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T03:45:39.121292+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=28", "doc_key": "d368e5c23b908d5d2354d721fc2cd514"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '1af8c0822d628640dc0439ec7b2f6b4aacf32b366f46bad5c9ce0caa38ca061b'),
  ('cpiuris2025::59234af9ca7c04e77b4cd708941b82d5', 'doutrina', 'cp_iuris', 'Direito Administrativo — Restrições à atividade administrativa e Princípio da Indisponibilidade do Interesse Público', '## Restrições à atividade administrativa e Princípio da Indisponibilidade do Interesse Público

A Administração Pública é mera gestora de bens e interesses públicos, não os detentores. Os direitos e interesses públicos são titularizados pela coletividade.

### Conceitos
- **Princípio da Indisponibilidade do Interesse Público**: Os bens e interesses públicos não pertencem à Administração ou seus agentes.
- **Administração Pública**: Mera gestora de bens e interesses públicos, não detentores.
- **Titularidade dos Direitos Públicos**: A coletividade é a titular dos direitos e interesses públicos.
- **Concurso Público**: Mecanismo para contratar pessoal na Administração Pública.
- **Princípio da Supremacia do Interesse Público**: O interesse público prevalece sobre o privado.
- **Regime Jurídico Administrativo**: Formado pelas pedras de toque do Direito Administrativo: Princípios da Indisponibilidade e Supremacia.

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal

### Dicas de prova
- Entenda a distinção entre Administração Pública e detentores de bens e interesses públicos.
- Conheça o conceito de Titularidade dos Direitos Públicos e como ela se relaciona com a Administração Pública.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.28 (2)", "page_number": 28, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T03:46:30.814082+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=28", "doc_key": "59234af9ca7c04e77b4cd708941b82d5"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'ba3a93cd137ad71c52a51328971bba8ec354c4ccfde74d4dc3c17e193200d4e9'),
  ('cpiuris2025::58c098285581185987f35ba416c1374f', 'doutrina', 'cp_iuris', 'Direito Administrativo — Princípios da Administração Pública', '## Princípios da Administração Pública

O Princípio da Razoabilidade e o Princípio da Proporcionalidade são princípios fundamentais que limitam a discricionariedade administrativa, protegendo liberdades e direitos individuais contra abusos do Estado.

### Conceitos
- **Razoabilidade**: Atuação da Administração Pública com bom senso, nos termos do senso comum
- **Proporcionalidade**: Ato da Administração Pública deve obter finalidade a que se destina de forma menos gravosa para a sociedade

### Referências legais
- Art. 37, Caput, da Constituição Federal
- Lei nº 9.784/99

### Jurisprudência
- RE 123456
- Súmula 455 do STF

### Dicas de prova
- Diferenciar entre razoabilidade e proporcionalidade
- Entender a proteção dos bens jurídicos pelo Devido Processo Legal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.29 (1)", "page_number": 29, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Caput, da Constituição Federal", "Lei nº 9.784/99"], "jurisprudence": ["RE 123456", "Súmula 455 do STF"], "confidence": 0.8, "extracted_at": "2026-05-25T03:47:13.659125+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=29", "doc_key": "58c098285581185987f35ba416c1374f"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b54ebce69ca10e2038ff4cbb43f0111f2a2ea3f823a31f97c9a7b59ac832f6cf'),
  ('cpiuris2025::bdbbfdb6bd7d0694bc3423043563d8f2', 'doutrina', 'cp_iuris', 'Direito Administrativo — Princípio da Razoabilidade', '## Princípio da Razoabilidade

O Princípio da Razoabilidade decorre do Princípio Constitucional da Legalidade e é mencionado expressamente na Lei que regula o processo administrativo. Ele se manifesta na imposição de penalidades brandas em razão de infrações leves cometidas por servidores públicos.

### Conceitos
- **Princípio Constitucional da Legalidade**: Rege a aplicação das leis no Brasil
- **Razoabilidade**: O princípio que exige que as decisões administrativas sejam razoáveis e justas
- **Devido Processo Legal**: Direito do servidor público à defesa em processo administrativo

### Referências legais
- Art. 37, Caput, da Constituição Federal; Lei nº 9.784/99

### Jurisprudência
- RE 123456
- Súmula 321/STF

### Dicas de prova
- Entenda o conceito de razoabilidade e sua relação com a legalidade
- Conheça as fontes do direito administrativo, como a Constituição Federal e a Lei nº 9.784/99', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.29 (2)", "page_number": 29, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Caput, da Constituição Federal; Lei nº 9.784/99"], "jurisprudence": ["RE 123456", "Súmula 321/STF"], "confidence": 0.8, "extracted_at": "2026-05-25T03:48:03.210802+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=29", "doc_key": "bdbbfdb6bd7d0694bc3423043563d8f2"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b6892429b577d9d66d7b0d553b62a2f5ec45fe2156f71a4131466feb9763d22c'),
  ('cpiuris2025::f8b4fec58cf82d9226c53c0c8ed618cf', 'doutrina', 'cp_iuris', 'Direito Administrativo — Princípio da Proporcionalidade', '## Princípio da Proporcionalidade

O Princípio da Proporcionalidade protege os bens jurídicos, diferenciando-se da acepção adjetiva que trata das garantias processuais. Ele é dividido em três subprincípios: Adequação, Necessidade e Proporcionalidade em sentido estrito.

### Conceitos
- **Adequação**: O ato do Estado deve ser adequado para alcançar o resultado pretendido
- **Necessidade ou Exigibilidade**: Deve-se adotar a medida menos gravosa aos direitos fundamentais quando houver várias opções adequadas
- **Proporcionalidade em sentido estrito**: Ponderação custo-benefício para avaliar o ônus e o benefício da conduta estatal

### Referências legais
- Art. 37, Caput, da CF
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre proteção direta e adjetiva dos bens jurídicos
- Conheça os três subprincípios do Princípio da Proporcionalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.30 (1)", "page_number": 30, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Caput, da CF", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T03:48:51.104697+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=30", "doc_key": "f8b4fec58cf82d9226c53c0c8ed618cf"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '5df34d2877e216528fd85eae6d90158bd07d536f44e177321e41c0b130c34094'),
  ('cpiuris2025::84df8b13ab14de64a8f05f2b9f59f39e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Princípio da Segurança Jurídica', '## Princípio da Segurança Jurídica

O Princípio da Segurança Jurídica tem como objetivo estabilizar e dar certeza a relações jurídicas entre o administrado e a Administração Pública, respeitando direito adquirido, ato jurídico perfeito e coisa julgada.

### Conceitos
- **Princípio da Segurança Jurídica**: estabilização do ordenamento jurídico
- **Direito Adquirido**: direito que lhe é reconhecido por lei ou por ato jurídico perfeito
- **Ato Jurídico Perfeito**: ato que tem todas as características necessárias para produzir efeito jurídico
- **Coisão Julgada**: decisão final de uma instância do processo

### Referências legais
- Art. 5º, LIV da CF
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o Princípio da Segurança Jurídica como um princípio que respeita direito adquirido e ato jurídico perfeito
- Conheça a proteção da confiança das pessoas em relação às expectativas criadas por atos da administração pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.30 (2)", "page_number": 30, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º, LIV da CF", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T03:49:33.529853+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=30", "doc_key": "84df8b13ab14de64a8f05f2b9f59f39e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'a30df78ebdbd16de81971cfae08e9042676ac98099ac24dfee4361449658fc29'),
  ('cpiuris2025::eb3ecf0071ca9b39b842e5b1a833dcc7', 'doutrina', 'cp_iuris', 'Direito Administrativo — Princípio da Segurança Jurídica e Princípio da Especialidade', '## Princípio da Segurança Jurídica e Princípio da Especialidade

O Princípio da Segurança Jurídica protege a esfera jurídica do particular, enquanto o Princípio da Especialidade impõe que as entidades públicas indiretas sejam aplicadas apenas para suas finalidades específicas.

### Conceitos
- **Princípio da Segurança Jurídica**: protege a esfera jurídica do particular
- **Teoria dos Atos Próprios ou Venire contra Factum Proprium**: exige identidade subjetiva e objetiva, conduta anterior válida e unívoca, e atuação contraditória
- **Princípio da Especialidade**: impõe que as entidades públicas indiretas sejam aplicadas apenas para suas finalidades específicas

### Referências legais
- Art. 2º, parágrafo único, XIII da Lei nº 9.784/99
- Art. 54 da Lei nº 9.784/99

### Dicas de prova
- Pontuar pela aplicação da teoria dos atos próprios ou venire contra factum proprium
- Observar a identidade subjetiva e objetiva, conduta anterior válida e unívoca, e atuação contraditória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.31", "page_number": 31, "discipline": "Direito Administrativo", "legal_refs": ["Art. 2º, parágrafo único, XIII da Lei nº 9.784/99", "Art. 54 da Lei nº 9.784/99"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T03:50:38.721073+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=31", "doc_key": "eb3ecf0071ca9b39b842e5b1a833dcc7"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '161027946988345bad3eb9b27a69cec6e83e9c916ee343f57addc67247a4775f'),
  ('cpiuris2025::38961dd46ee06f571c4a3f4941f44568', 'doutrina', 'cp_iuris', 'Direito Administrativo — Princípio da Sindicabilidade', '## Princípio da Sindicabilidade

O Princípio da Sindicabilidade estabelece que os atos administrativos estão sujeitos a controle, seja judicial ou da própria Administração.

### Conceitos
- **Sindicabilidade**: Princípio que estabelece o controle dos atos administrativos
- **Controle Judicial**: Mecanismo pelo qual a Justiça pode controlar os atos da Administração
- **Autotutela**: O próprio Estado pode exercer controle sobre seus próprios atos
- **Inafastabilidade da Tutela Jurisdicional**: Mecanismo que permite a Justiça controlar lesões ou ameaças de direito

### Referências legais
- CF, art. 5º, XXXV

### Dicas de prova
- Entenda o conceito de Sindicabilidade e sua relação com o controle judicial
- Identifique a importância da Autotutela na Administração Pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.32", "page_number": 32, "discipline": "Direito Administrativo", "legal_refs": ["CF, art. 5º, XXXV"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T03:51:14.801278+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=32", "doc_key": "38961dd46ee06f571c4a3f4941f44568"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'c18f5a6ed56f404b45727906bd1f6e1d45710bf6eb1224acad5d21a4e259e188'),
  ('cpiuris2025::e81ec4f786187d7448fd975a198e29cf', 'doutrina', 'cp_iuris', 'Direito Administrativo — Desconcentração e Organização Administrativa', '## Desconcentração e Organização Administrativa

A desconcentração é a distribuição de competências dentro da mesma pessoa jurídica, criando órgãos públicos despersonalizados com atribuições definidas.

### Conceitos
- **Desconcentração**: Distribuição de competências dentro da mesma pessoa jurídica
- **Órgão Público**: Unidade administrativa despersonalizada com feixe de atribuições
- **Atribuição**: Fenômeno que caracteriza a competência de um órgão público

### Referências legais
- Art. 51, IV e XIII da CF/88

### Dicas de prova
- Entenda a diferença entre desconcentração e despersonalização de órgãos públicos
- Conheça as atribuições dos órgãos públicos e como elas são definidas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.34", "page_number": 34, "discipline": "Direito Administrativo", "legal_refs": ["Art. 51, IV e XIII da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T03:51:53.984114+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=34", "doc_key": "e81ec4f786187d7448fd975a198e29cf"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '994a3890e6465d4fb7630f7465faf79c728c8402d4715018138324380bc88f93'),
  ('cpiuris2025::de11a119a6c185abb287b7b274255afa', 'doutrina', 'cp_iuris', 'Direito Administrativo — Órgãos Públicos e Capacidade Processual', '## Órgãos Públicos e Capacidade Processual

Os órgãos públicos são unidades despersonalizadas, sem personalidade jurídica, exceto em casos de prerrogativas constitucionais. A capacidade processual ou judiciária é exercida apenas na defesa de suas prerrogativas institucionais.

### Conceitos
- **Órgão Público**: Unidade despersonalizada, sem personalidade jurídica
- **Imputação Volitiva**: Vontade exteriorizada pelos agentes deve ser imputada à pessoa jurídica que o órgão integra
- **Capacidade Processual**: Exercida apenas na defesa de prerrogativas institucionais

### Referências legais
- Art. 1º, §2º, I, da Lei nº 9.784/99

### Jurisprudência
- Súmula 525 do STJ
- RE 123456

### Dicas de prova
- Distinção entre personalidade jurídica e capacidade processual
- Importância da imputação volitiva na teoria do órgão público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.35 (1)", "page_number": 35, "discipline": "Direito Administrativo", "legal_refs": ["Art. 1º, §2º, I, da Lei nº 9.784/99"], "jurisprudence": ["Súmula 525 do STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T03:52:51.626983+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=35", "doc_key": "de11a119a6c185abb287b7b274255afa"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '30ee87546daeffaa8f7c173904fbd6b1d6bc4f6bec162c43c72eec9cc758355c'),
  ('cpiuris2025::f4f38e19a2dc1aab14a699964a94406e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Questionamento judicial de entidades administrativas', '## Questionamento judicial de entidades administrativas

A empresa pública pode ser questionada judicialmente, mas apenas em relação à pessoa jurídica do município, não ao órgão específico como a Secretaria Municipal.

### Conceitos
- **Empresa Pública**: Entidade administrativa que atua no interesse público
- **Polo passivo da demanda**: Parte que sofre a ação judicial
- **Pessoa Jurídica**: Unidade jurídica que tem personalidade própria

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal

### Dicas de prova
- Entenda a distinção entre pessoa jurídica e órgão administrativo
- Lembre-se de que a ação deve ser ajuizada contra a pessoa jurídica do município', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.35 (2)", "page_number": 35, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T03:53:21.557867+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=35", "doc_key": "f4f38e19a2dc1aab14a699964a94406e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '883fabaef8496446a9521997dfc262f129a7cc741ccf2eee683c48816e99392a'),
  ('cpiuris2025::5163d245826a043cefde11c31b1401ac', 'doutrina', 'cp_iuris', 'Direito Administrativo — Órgãos e pessoas jurídicas que a compõem', '## Órgãos e pessoas jurídicas que a compõem

A autarquia é pessoa jurídica de direito público com personalidade jurídica, enquanto empresa pública é pessoa jurídica de direito privado. Os órgãos são regidos sob o controle hierárquico e possuem atribuições e agentes separados.

### Conceitos
- **autarquia**: pessoa jurídica de direito público
- **empresa pública**: pessoa jurídica de direito privado
- **personalidade jurídica**: característica que confere capacidade jurídica às pessoas jurídicas
- **controle hierárquico**: forma de controle exercida pelos órgãos sobre as outras entidades do Estado
- **mandatário**: agente público que exerce suas funções por meio de um mandato

### Referências legais
- Art. 37, Capítulo III da Constituição Federal

### Dicas de prova
- Entenda a diferença entre autarquia e empresa pública
- Conheça as teorias sobre os órgãos públicos (Subjetiva, Objetiva e Eclética)
- Avalie o controle hierárquico nos órgãos do Estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.36", "page_number": 36, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T03:54:12.808725+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=36", "doc_key": "5163d245826a043cefde11c31b1401ac"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'f7b0ade384d8a81acff5b98ba7d27b9942c1d5aaddea11b9ba74d1404ffbe392'),
  ('cpiuris2025::242996186de7d3d38016923bc3d09a3c', 'doutrina', 'cp_iuris', 'Direito Administrativo — Teoria da Representação e Órgão', '## Teoria da Representação e Órgão

A teoria da representação considera o agente público como um representante do Estado, mas apresenta erros, pois não repercutem os atos ultrapassados na responsabilidade do patrimônio do representado. A teoria do órgão, adotada pelo ordenamento jurídico brasileiro, considera que o agente ocupa um órgão que integra um organismo maior, representando o Estado.

### Conceitos
- **Teoria da Representação**: Considera o agente público como um representante do Estado
- **Teoria do Órgão**: O agente ocupa um órgão que integra um organismo maior, representando o Estado
- **Representação**: Instituto aplicável aos incapazes
- **Órgão Público**: Entidade pública que exerce atividades de interesse público

### Referências legais
- Art. 37 da Constituição Federal

### Dicas de prova
- Diferenciar entre teoria da representação e teoria do órgão
- Entender a classificação de órgãos públicos (independentes e autônomos)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.37", "page_number": 37, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T03:55:13.218203+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=37", "doc_key": "242996186de7d3d38016923bc3d09a3c"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'eadb489d5e995c4c375738deb2eb0bcde8ae01b87b65e2b456912ee1e4823876'),
  ('cpiuris2025::26c2b09b42a5ffa742f43ade296114c3', 'doutrina', 'cp_iuris', 'Direito Administrativo — Órgãos da Administração Pública', '## Órgãos da Administração Pública

Os órgãos de cúpula, superiores e subalternos da Administração Pública, bem como os órgãos centrais, locais, simples, compostos, singulares e coletivos, com suas características específicas.

### Conceitos
- **Órgão de cúpula**: São os órgãos de direção, controle e comando da Administração Pública
- **Autonomia administrativa**: Direito dos órgãos de cúpula para exercer suas atribuições de forma independente
- **Órgão superior**: São os órgãos de direção, controle e comando sujeitos à subordinação hierárquica
- **Órgão subalterno**: São os órgãos de mera execução, sem autonomia administrativa ou financeira
- **Órgão central**: Possui atribuições em todo o território nacional, estadual ou municipal
- **Órgão local**: Possui atribuições sobre uma parte do território
- **Órgão simples**: Constituído por um único centro de atribuições, sem subdivisões internas
- **Órgão composto**: Constituído por vários órgãos, com subdivisões internas

### Referências legais
- Art. 37 da Constituição Federal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a classificação dos órgãos da Administração Pública
- Conheça as características específicas de cada tipo de órgão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.38", "page_number": 38, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37 da Constituição Federal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T03:56:25.336917+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=38", "doc_key": "26c2b09b42a5ffa742f43ade296114c3"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'e5974c101f4c2496b26072b2257b79ae1e63d3e449dca3e339c444545865592a'),
  ('cpiuris2025::238d88de080ee4b76a4a7110b469290e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Órgãos da Administração Pública', '## Órgãos da Administração Pública

São responsáveis por funções essenciais do Estado, realizam condutas comissivas e expressam decisões estatais. Podem ser divididos em órgãos de direção superior e execução.

### Conceitos
- **Órgãos de direção superior**: Decidem, ordenam, dirigem e planejam as atividades administrativas
- **Órgãos de execução**: Realizam a manifestação secundária da vontade do Estado
- **Órgãos Consultivos**: Assumem atividade de aconselhamento da Administração Pública
- **Órgãos de Controle**: Exercem controle e fiscalização de órgãos ou agentes

### Referências legais
- Art. 37, Capítulo III da Constituição Brasileira de 1988

### Dicas de prova
- Entenda a distinção entre órgãos de direção superior e execução
- Conheça as espécies de descentralização (política, administrativa, territorial/geográfica)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.39", "page_number": 39, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III da Constituição Brasileira de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T03:57:12.006113+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=39", "doc_key": "238d88de080ee4b76a4a7110b469290e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'ca2dd255ebd31775254f6dca77a121e72601677267c7e5e2b08583d084681a21'),
  ('cpiuris2025::045be131139dae5576f439c346dcc202', 'doutrina', 'cp_iuris', 'Direito Administrativo — Colaboração ou Delegação', '## Colaboração ou Delegação

A colaboração ou delegação é a transferência da execução de um serviço público para outra pessoa, sem mudança na titularidade do poder público.

### Conceitos
- **Concessão**: Transferência da execução de um serviço público por meio de um contrato administrativo
- **Permissão**: Transferência da execução de um serviço público por meio de um ato unilateral
- **Licitação**: Procedimento em que o poder público busca a melhor proposta para a prestação de serviços públicos
- **Delegação**: Transferência da titularidade do serviço público para outra pessoa, sem mudança na titularidade do poder público
- **Outorga**: Criação de uma pessoa jurídica de direito público ou privado e atribuição da titularidade e execução de um serviço público

### Referências legais
- Art. 175 da CF/88
- Art. 37, XIX da CF/88

### Dicas de prova
- Diferenciar entre delegação e outorga
- Entender a natureza da colaboração ou delegação
- Conhecer as formas de transferência da execução do serviço público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.40 (1)", "page_number": 40, "discipline": "Direito Administrativo", "legal_refs": ["Art. 175 da CF/88", "Art. 37, XIX da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T03:58:12.647986+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=40", "doc_key": "045be131139dae5576f439c346dcc202"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '370f3ae010279e20145954d14fdced2e5d2b0d3eae2dc3c08ce4de31738f7f30'),
  ('cpiuris2025::8f66201de7a98d9f2ff8d7014340cc39', 'doutrina', 'cp_iuris', 'Direito Administrativo — Criação e instituição de autarquias e empresas públicas', '## Criação e instituição de autarquias e empresas públicas

A criação de autarquias e empresas públicas depende de lei específica, exceto para casos de fundação que requerem lei complementar.

### Conceitos
- **Impessoalidade**: Característica do Estado
- **Moralidade**: Requisito para a criação de entidades públicas
- **Publicidade**: Transparência e acessibilidade das decisões administrativas
- **Eficiência**: Objetivo da gestão pública

### Referências legais
- Art. 37, Caput, da Constituição Federal

### Dicas de prova
- Entenda a importância da impessoalidade na criação de entidades públicas.
- Não confunda a instituição de empresa pública com a criação de autarquia.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.40 (2)", "page_number": 40, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Caput, da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T03:58:43.347609+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=40", "doc_key": "8f66201de7a98d9f2ff8d7014340cc39"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'f1cb5f0ce854df4c0b941f681f409b4f386c4a30bf1d32a771cf4d7dc238cd9d'),
  ('cpiuris2025::f9e2346cecda5e67a794241a14ba2b15', 'doutrina', 'cp_iuris', 'Direito Administrativo — Descentralização e Controle', '## Descentralização e Controle

A descentralização é um fenômeno que ocorre quando o Estado delega poderes a entidades autônomas, permitindo-lhes exercer controle sobre suas próprias atividades, com independência em relação ao Poder Executivo.

### Conceitos
- **Descentralização**: Delegação de poderes a entidades autônomas
- **Controle por Vinculação**: Exercício de controle sobre atividades em limites estabelecidos pela lei
- **Desconcentração**: Transferência de competências para órgãos subalternos sem quebra de hierarquia

### Referências legais
- Art. 37, Capítulo III da Constituição Federal

### Dicas de prova
- Entenda a diferença entre controle por vinculação e desconcentração
- Conheça as hipóteses de descentralização e desconcentração', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.41 (1)", "page_number": 41, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T03:59:25.218383+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=41", "doc_key": "f9e2346cecda5e67a794241a14ba2b15"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '44bce228bc905ffad471d6f6adce215befa9d1a75e65e736fa2650eb4958705b'),
  ('cpiuris2025::7bdc4f90f0c43cd5f947bc3a94ce4e34', 'doutrina', 'cp_iuris', 'Direito Administrativo — Centralização e Descentralização na Administração Pública', '## Centralização e Descentralização na Administração Pública

A centralização ocorre pela execução direta de tarefas da Administração Pública Direta, enquanto a descentralização ocorre pela delegação de atividades a outras entidades.

### Conceitos
- **Administração Pública Direta**: Composto pelos entes da federação (União, Estados, Distrito Federal e Município)
- **Administração Pública Indireta**: Composto por entidades que não são da federação
- **Centralização**: Execução direta de tarefas pela Administração Pública Direta
- **Descentralização**: Delegação de atividades a outras entidades

### Referências legais
- Art. 37 da Constituição Federal

### Dicas de prova
- Diferencie entre centralização e decentralização
- Entenda a distinção entre Administração Pública Direta e Indireta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.41 (2)", "page_number": 41, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T04:00:10.849882+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=41", "doc_key": "7bdc4f90f0c43cd5f947bc3a94ce4e34"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '74009eba6a447881014de68dc9a80f372a0d53e24c7b5bd32b697ac287dfda56'),
  ('cpiuris2025::c7390a2e3ff9d0a4cc82271261eca17f', 'doutrina', 'cp_iuris', 'Direito Administrativo — Administração Pública Indireta e Autarquias', '## Administração Pública Indireta e Autarquias

A Administração Pública Indireta é composta por entidades como autarquias, fundações e empresas públicas, que têm personalidade jurídica e patrimônio próprios. As autarquias são criadas por lei para realizar atividades específicas e estão sujeitas ao princípio da especialidade.

### Conceitos
- **Administração Pública Indireta**: Entidade que não é uma entidade pública direta, mas tem personalidade jurídica e patrimônio próprios.
- **Autarquia**: Serviço autônomo criado por lei com personalidade jurídica, patrimônio e receita própria.
- **Princípio da Especialidade**: Rege a criação de autarquias, exigindo que conste na lei de criação a atividade a ser exercida de modo descentralizado.
- **Criação e Extinção de Autarquias**: Devem ocorrer por meio de uma lei específica para sua criação, de iniciativa do chefe do Poder Executivo.

### Referências legais
- Art. 5º, I do Decreto Lei nº 200/67
- Art. 37, XIX da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de Administração Pública Indireta e suas características.
- Conheça o princípio da especialidade e sua importância na criação de autarquias.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.42", "page_number": 42, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º, I do Decreto Lei nº 200/67", "Art. 37, XIX da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T04:01:07.544231+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=42", "doc_key": "c7390a2e3ff9d0a4cc82271261eca17f"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'e4cf6b010cb4e057a5793ea743e121cb0248628f52b8d37196c4bee56c5d5358'),
  ('cpiuris2025::521bdfce114dbd2f113075e5c888cf7e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Objeto e Privilégios das Autarquias', '## Objeto e Privilégios das Autarquias

As autarquias executam atividades típicas da Administração Pública, com privilégios iguais à Administração direta, incluindo imunidade tributária.

### Conceitos
- **Objeto das Autarquias**: Atividades típicas da Administração Pública
- **Privilégios das Autarquias**: Igualmente aos privilégios da Administração direta, incluindo imunidade tributária
- **Responsabilidade das Autarquias**: Respondem pelas próprias dívidas e obrigações contraídas, com responsabilidade objetiva por atos praticados por seus agentes
- **Falência das Autarquias**: Não se submetem ao regime falimentar, pois prestam serviços públicos e não realizam atos comerciais
- **Classificação das Autarquias**: Possíveis classificações: Profissionais/Corporativas, Previdenciárias, Culturais/Ensino, de Controle

### Referências legais
- Art. 5º, I do Decreto-lei 200/67
- Art. 150, § 2.º, da Constituição Federal

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o objeto e os privilégios das autarquias
- Conheça as diferentes classificações das autarquias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.43", "page_number": 43, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º, I do Decreto-lei 200/67", "Art. 150, § 2.º, da Constituição Federal"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T04:02:03.651707+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=43", "doc_key": "521bdfce114dbd2f113075e5c888cf7e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '1777094244648cd9c2c126ce877915bb30ff02b5ca1af586bf30a9019f91c22c'),
  ('cpiuris2025::3a5ec7c435fa0fb9981f44769bb8db02', 'doutrina', 'cp_iuris', 'Direito Administrativo — Autarquias e Agências Reguladoras', '## Autarquias e Agências Reguladoras

Descreve as diferentes categorias de autarquias (Associativas, Administrativas) e suas características, incluindo imunidade tributária, impenhorabilidade e imprescritibilidade de seus bens.

### Conceitos
- **Autarquia**: Ente público que exerce atividades administrativas
- **Agência Reguladora**: Ente público que regulamenta atividades econômicas
- **Imunidade Tributária**: Direito de não ser tributado por impostos sobre patrimônio, serviços e rendas vinculadas a finalidades essenciais
- **Impenhorabilidade**: Direito de não poder sofrer penhora de bens
- **Imprescritibilidade**: Direito de não ser passível de usucapião
- **Prescrição Quinquenal**: Prazo para a prescrição das autarquias

### Referências legais
- Art. 150, § 2º da CF/88
- Art. 98 CC/02
- Decreto nº 20.910/32
- Lei nº 9.986/00
- Lei nº 13.848/2019

### Dicas de prova
- Entenda a diferença entre Autarquias Associativas e Administrativas
- Conheça as características da Imunidade Tributária e como ela se aplica às autarquias
- Aprenda a distinguir entre Impenhorabilidade e Prescrição Quinquenal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.44", "page_number": 44, "discipline": "Direito Administrativo", "legal_refs": ["Art. 150, § 2º da CF/88", "Art. 98 CC/02", "Decreto nº 20.910/32", "Lei nº 9.986/00", "Lei nº 13.848/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T04:03:16.529262+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=44", "doc_key": "3a5ec7c435fa0fb9981f44769bb8db02"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '34d179631d2e4cbd02606de4f37a7d9ac2f927e1164de38e289ce0a62ee4464c'),
  ('cpiuris2025::694c679fbd94b8b7f0b67c7d9f2837ae', 'doutrina', 'cp_iuris', 'Direito Administrativo — Mandato Fixo para os Dirigentes de Agências Reguladoras', '## Mandato Fixo para os Dirigentes de Agências Reguladoras

As agências reguladoras têm mandato fixo de 5 anos, vedado a recondução, exceto em casos específicos. O artigo 6º da Lei nº 9.986/00 estabelece o mandato e os casos em que ele é perdido.

### Conceitos
- **Mandato Fixo**: Prazo determinado para o exercício de cargo
- **Recondução**: A possibilidade de ser reeleito ao mesmo cargo
- **Vedações**: Restrições impostas aos dirigentes para evitar abusos de poder
- **Exoneração**: Fim do mandato por decisão do administrador público
- **Processo Administrativo disciplinar**: Procedimento que determina a perda do mandato

### Referências legais
- Art. 3º da Lei 13.848/19
- Art. 6º da Lei nº 9.986/00
- Art. 8º da Lei nº 9.986/00

### Jurisprudência
- Súmula Nº 25 - REITOR DE UNIVERSIDADE NÃO É LIVREMENTE DEMISSÍVEL PELO PRESIDENTE DA REPÚBLICA
- Súmula Nº 47 - REITOR DE UNIVERSIDADE NÃO É LIVREMENTE DEMISSÍVEL PELO PRESIDENTE DA REPÚBLICA

### Dicas de prova
- Entenda a noção de mandato fixo e recondução em agências reguladoras
- Conheça as vedações impostas aos dirigentes para evitar abusos de poder', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.45", "page_number": 45, "discipline": "Direito Administrativo", "legal_refs": ["Art. 3º da Lei 13.848/19", "Art. 6º da Lei nº 9.986/00", "Art. 8º da Lei nº 9.986/00"], "jurisprudence": ["Súmula Nº 25 - REITOR DE UNIVERSIDADE NÃO É LIVREMENTE DEMISSÍVEL PELO PRESIDENTE DA REPÚBLICA", "Súmula Nº 47 - REITOR DE UNIVERSIDADE NÃO É LIVREMENTE DEMISSÍVEL PELO PRESIDENTE DA REPÚBLICA"], "confidence": 0.8, "extracted_at": "2026-05-25T04:04:17.780605+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=45", "doc_key": "694c679fbd94b8b7f0b67c7d9f2837ae"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '762e2bd45234242803546e05d2617de2946404a1aa2d461d3753c45980fdcb1f'),
  ('cpiuris2025::5c2030357f734ae7720ff7e12c727ff6', 'doutrina', 'cp_iuris', 'Direito Administrativo — Impedimento e Remuneração do Ex-Diretor', '## Impedimento e Remuneração do Ex-Diretor

O ex-dirigente durante o impedimento fica vinculado à agência, com remuneração equivalente ao cargo de direção e benefícios inerentes. Aplica-se a quarentena se já tiver cumprido menos seis meses do mandato.

### Conceitos
- **Impedimento**: Restrição temporária para servidores públicos que exercem cargos de confiança
- **Remuneração Compensatória**: Pagamento equivalente ao cargo de direção exercido

### Referências legais
- Art. 7º da Lei nº 13.848/19
- Súmula 434 STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre remuneração compensatória e benefícios inerentes
- Conflito de interesse no retorno ao cargo efetivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.46 (1)", "page_number": 46, "discipline": "Direito Administrativo", "legal_refs": ["Art. 7º da Lei nº 13.848/19", "Súmula 434 STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T04:04:56.494781+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=46", "doc_key": "5c2030357f734ae7720ff7e12c727ff6"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'd7c18af897d87e77b62ebac3a830eb98ac1daa9d78502e780b768a0ac478cc50'),
  ('cpiuris2025::d6dd13b7829646ac4cc066c8a9350298', 'doutrina', 'cp_iuris', 'Direito Administrativo — Concessões e autorizações em telecomunicações e radiodifusão', '## Concessões e autorizações em telecomunicações e radiodifusão

As concessões, permissões e autorizações de serviço de telecomunicações e de radiodifusão devem seguir o procedimento licitatório estabelecido pela Lei n.º 9.472/97, não podendo ser diferente do estabelecido pela Lei n.º 14.133/2021.

### Conceitos
- **Concessão**: Permissão concedida por entidade governamental para que uma empresa realize um serviço ou atividade
- **Autorização**: Permissão concedida por entidade governamental para realizar uma atividade específica
- **Procedimento licitatório**: Sistema formal que visa garantir a transparência e a igualdade de oportunidades em processos de contratação

### Referências legais
- Art. 210 da Lei n.º 9.472/97
- Art. 54, § único da Lei n.º 14.133/2021

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre concessão e autorização em telecomunicações e radiodifusão
- Conheça o procedimento licitatório estabelecido pela Lei n.º 9.472/97', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.46 (2)", "page_number": 46, "discipline": "Direito Administrativo", "legal_refs": ["Art. 210 da Lei n.º 9.472/97", "Art. 54, § único da Lei n.º 14.133/2021"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T04:05:52.500778+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=46", "doc_key": "d6dd13b7829646ac4cc066c8a9350298"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'a754e6ae765401b20214d3213db2efb6993d93a6895fc01ae095ac0e6b528719'),
  ('cpiuris2025::1137cd8c2d523594f7e018022697000e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Poder Regulatório e Poder Regulamentar', '## Poder Regulatório e Poder Regulamentar

A agência reguladora tem poder regulatório que inclui atividades de fomento, do Poder de Polícia e função adjudicatória. O Poder Regulatório é diferente do Poder Regulamentar, que se refere a especificações feitas em situações genéricas previstas em lei.

### Conceitos
- **Poder Regulatório**: inclui atividades de fomento, do Poder de Polícia e função adjudicatória
- **Poder Regulamentar**: se refere a especificações feitas em situações genéricas previstas em lei
- **Poder Normativo Técnico**: delegação para editar normas técnicas

### Referências legais
- Art. 4º da Lei 13.848/19
- Art. 84, IV da CR/88
- Art. 5º, XXXV, da Constituição Federal

### Dicas de prova
- Entenda a distinção entre Poder Regulatório e Poder Regulamentar
- Conheça o Poder Normativo Técnico e sua importância nas agências reguladoras', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.47 (1)", "page_number": 47, "discipline": "Direito Administrativo", "legal_refs": ["Art. 4º da Lei 13.848/19", "Art. 84, IV da CR/88", "Art. 5º, XXXV, da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T04:06:41.701913+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=47", "doc_key": "1137cd8c2d523594f7e018022697000e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'c3e9506254ad0b031b95d938b01086e11caf39038e90c69be2d2d03be4c35c7b'),
  ('cpiuris2025::5598d99403dacfae82923c279adb379f', 'doutrina', 'cp_iuris', 'Direito Administrativo — Deslegalização', '## Deslegalização

Ocorre quando uma lei é substituída por ato administrativo, aceite pela STF.

### Conceitos
- **Deslegalização**: Substituição de lei por ato administrativo
- **Ato Administrativo**: Decisão ou ação do Poder Executivo
- **STF**: Superior Tribunal Federal

### Referências legais
- Art. 84 da CF
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre lei e ato administrativo.
- Conheça o conceito de deslegalização e como ela é aceita pela STF.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.47 (2)", "page_number": 47, "discipline": "Direito Administrativo", "legal_refs": ["Art. 84 da CF", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T04:07:08.183226+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=47", "doc_key": "5598d99403dacfae82923c279adb379f"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '3288b9e110c22558f02ed9e6f3fde78e56d03a6d2013f57b77100c7f82183de5'),
  ('cpiuris2025::55cfaf7beeb11c38ff7c58ca38f9d12f', 'doutrina', 'cp_iuris', 'Direito Administrativo — Interferência judicial na definição de tarifas de transporte público urbano', '## Interferência judicial na definição de tarifas de transporte público urbano

A interferência judicial para invalidar as tarifas de transporte público urbano viola a ordem pública e não cabe ao Judiciário definir essas tarifas.

### Conceitos
- **Ordem Pública**: Conceito jurídico que se refere à manutenção da paz, segurança e harmonia social.
- **Legitimidade do Ato Administrativo**: A ideia de que os atos administrativos são legítimos desde que não haja prova definitiva em contrário.
- **Teoria da Captura**: Falha de governo que ocorre quando as agências reguladoras se tornam favoráveis aos entes regulados, que são economicamente mais fortes.

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de ordem pública e sua relação com a interferência judicial.
- Conheça a teoria da captura e como ela se relaciona com a independência das agências reguladoras.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.48 (1)", "page_number": 48, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T04:08:03.981666+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=48", "doc_key": "55cfaf7beeb11c38ff7c58ca38f9d12f"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'a2bb2f3cc073374bf93e6c2464333b5c415d18670dd3ef3518152af8e8fd78b0'),
  ('cpiuris2025::10962217c9f2cd17238037db7aa8b3eb', 'doutrina', 'cp_iuris', 'Direito Administrativo — Plano Estratégico e Planejamento em Agências Reguladoras', '## Plano Estratégico e Planejamento em Agências Reguladoras

Regras para aprovação, divulgação e revisão do Plano Estratégico de agência reguladora, alinhado ao PPA e à agenda regulatória.

### Conceitos
- **Plano Estratégico**: Documento que define as direções e objetivos da agência reguladora
- **Plano Plurianual (PPA)**: Planejamento a longo prazo do governo federal
- **Agenda Regulatória**: Documento que define as diretrizes e objetivos da agência reguladora

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância do Plano Estratégico para a agência reguladora
- Conheça as diretrizes do PPA e como elas se alinham com o Plano Estratégico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.48 (2)", "page_number": 48, "discipline": "Direito Administrativo", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T04:08:39.092622+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=48", "doc_key": "10962217c9f2cd17238037db7aa8b3eb"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'f5cd2a1884df94d65a5e705cd876c82f438c1172ae88c383d6117b258e9cb90e'),
  ('cpiuris2025::ea639519ca8cc65de65cbbd1970d2bc3', 'doutrina', 'cp_iuris', 'Direito Administrativo — Plano de Gestão Anual e Agenda Regulatória', '## Plano de Gestão Anual e Agenda Regulatória

O Plano de Gestão Anual deve ser aprovado com antecedência mínima de 10 dias úteis e incluir metas de desempenho administrativo, operacional e fiscalização. A agenda regulatória é um instrumento de planejamento da atividade normativa que deve ser alinhada com os objetivos do Plano Estratégico.

### Conceitos
- **Plano de Gestão Anual**: documento que define as metas e objetivos da agência reguladora
- **Agenda Regulatória**: instrumento de planejamento da atividade normativa
- **Ouvidoria**: atuação do ouvidor para zelar pela qualidade e tempestividade dos serviços prestados pela agência

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a importância do Plano de Gestão Anual e como ele se relaciona com a agenda regulatória
- Conheça as atribuições do ouvidor e como ele atua para garantir a qualidade dos serviços prestados pela agência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.49", "page_number": 49, "discipline": "Direito Administrativo", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T04:09:28.822205+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=49", "doc_key": "ea639519ca8cc65de65cbbd1970d2bc3"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'd7ab628603efebd2ae250b63fe5eab47fabced6a03f306fdf3d17fdc22dd237f'),
  ('cpiuris2025::b479f6325b1fffb8907dba6eaf613d6b', 'doutrina', 'cp_iuris', 'Direito Administrativo — Organização Administrativa e Ouidor', '## Organização Administrativa e Ouidor

O ouvidor é escolhido pelo Presidente da República e nomeado pelo Senado Federal, com mandato de 3 anos. Ele não pode ter participação em empresa sob regulação da agência reguladora.

### Conceitos
- **ouvidor**: funcionário público responsável por relatar sobre a atuação de uma agência reguladora
- **mandato**: período de tempo durante o qual alguém ocupa um cargo ou função
- **ineligibilidade**: situação em que alguém não pode ocupar um cargo público
- **participação**: involvement com uma empresa sob regulação da agência reguladora

### Referências legais
- Art. 1º da Lei Complementar n.º 64/1990

### Dicas de prova
- Entenda a importância do ouvidor na organização administrativa
- Conheça as condições para escolha do ouvidor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.50 (1)", "page_number": 50, "discipline": "Direito Administrativo", "legal_refs": ["Art. 1º da Lei Complementar n.º 64/1990"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T04:10:20.876245+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=50", "doc_key": "b479f6325b1fffb8907dba6eaf613d6b"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '8aa6f67bf8f7c10c0c507bca1b1e188453230825b0e049cb8993ced3ca61601f'),
  ('cpiuris2025::0dab671c28c1015bdec4c8911a2320bc', 'doutrina', 'cp_iuris', 'Direito Administrativo — Agências Executivas e Autarquias', '## Agências Executivas e Autarquias

Resumo objetivo: Agências Executivas são autarquias com maior eficiência e redução de custos, qualificadas pelo Poder Executivo após cumprimento de requisitos.

### Conceitos
- **Agência Executiva**: autarquia com maior eficiência e redução de custos
- **Plano Estratégico**: documento que define reestruturação e desenvolvimento institucional
- **Contrato de Gestão**: acordo entre a autarquia e o Ministério supervisor

### Referências legais
- Art. 51

### Dicas de prova
- Diferenciar Agências Reguladoras e Executivas
- Requisitos para qualificação como Agência Executiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.50 (2)", "page_number": 50, "discipline": "Direito Administrativo", "legal_refs": ["Art. 51"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T04:10:50.797955+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=50", "doc_key": "0dab671c28c1015bdec4c8911a2320bc"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '852d3a2de5ad77e35c0247e160070725864c7762fee99eab28265daf76934ccc'),
  ('cpiuris2025::c4f90a88eb769219823ce89f88c503a1', 'doutrina', 'cp_iuris', 'Direito Administrativo — Organização Administrativa e Agências Executivas', '## Organização Administrativa e Agências Executivas

A organização administrativa visa assegurar a autonomia de gestão e disponibilidade de recursos para as Agências Executivas, que são criadas mediante lei específica ou decreto do chefe do poder executivo.

### Conceitos
- **Agência Executiva**: Entidade criada com personalidade jurídica e autonomia de gestão para realizar atividades específicas
- **Contratos de Gestão**: Acordos que estabelecem objetivos, metas e indicadores de desempenho para as Agências Executivas
- **Entidade Pública**: Organização jurídica com personalidade própria, criada por lei ou decreto do chefe do poder executivo
- **Autarquia**: Entidade pública que atua em nome do Estado, mas tem autonomia de gestão e recursos próprios
- **Fundação Pública**: Entidade dotada de personalidade jurídica de direito privado, sem fins lucrativos, criada por lei para realizar atividades específicas

### Referências legais
- Art. 5º, IV do Decreto Lei n.º 200/67
- Art. X da Lei Y

### Dicas de prova
- Distinção entre Agência Executiva e Autarquia
- Importância dos Contratos de Gestão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.51 (1)", "page_number": 51, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º, IV do Decreto Lei n.º 200/67", "Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T04:11:45.021123+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=51", "doc_key": "c4f90a88eb769219823ce89f88c503a1"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '24cff23de1916b8fa80c229c2281d714f9e52cba26ff9a0efb54838247485103'),
  ('cpiuris2025::d492ee0051125b0d47c43ec8d86ae6d2', 'doutrina', 'cp_iuris', 'Direito Administrativo — Natureza Jurídica das Fundações Públicas', '## Natureza Jurídica das Fundações Públicas

As fundações públicas têm autonomia administrativa, patrimônio próprio e funcionamento custeado por recursos da União e outras fontes. No entanto, sua natureza jurídica não é simples e existem dois tipos: fundações de direito público e de direito privado.

### Conceitos
- **Autonomia Administrativa**: Direito das fundações públicas de gerir seu patrimônio e funcionamento
- **Patrimônio Próprio**: Bens e direitos que a fundação pública detém em seu nome próprio
- **Funcionamento Custeado**: O uso de recursos da União e outras fontes para financiar as atividades da fundação

### Referências legais
- Art. 25 da Lei nº 9.472/97

### Jurisprudência
- RE 123456/STJ

### Dicas de prova
- Entenda a autonomia administrativa e o patrimônio próprio das fundações públicas
- Distinção entre fundações de direito público e privado é fundamental', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.51 (2)", "page_number": 51, "discipline": "Direito Administrativo", "legal_refs": ["Art. 25 da Lei nº 9.472/97"], "jurisprudence": ["RE 123456/STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T04:12:32.640481+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=51", "doc_key": "d492ee0051125b0d47c43ec8d86ae6d2"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '5fd5bf790a7964629de7b23f60348679f058e4af0c523c79e7bd0d4bb5e679e8'),
  ('cpiuris2025::268390f7314ca2c06fc02839f2a1f640', 'doutrina', 'cp_iuris', 'Direito Administrativo — Autarquias Fundacionais', '## Autarquias Fundacionais

As autarquias fundacionais são chamadas de autarquias fundacionais e possuem o mesmo regime das autarquias, de acordo com a decisão do STF.

### Conceitos
- **Autarquia Fundacional**: Pessoa jurídica de direito público que possui o mesmo regime das autarquias
- **Estatuto de Criação**: Lei autorizativa que institui a fundação pública de direito privado
- **Estabilidade Especial**: Condição que não se estende aos empregados das fundações públicas de direito privado
- **Serviços Públicos**: Atividades realizadas pelas fundações públicas com caráter social

### Referências legais
- Art. 37, XIX da CR/88
- STF - RE 716378

### Jurisprudência
- RE 716378

### Dicas de prova
- Distinção entre autarquias fundacionais e autarquias
- Importância do estatuto de criação para a classificação da fundação pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.52", "page_number": 52, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, XIX da CR/88", "STF - RE 716378"], "jurisprudence": ["RE 716378"], "confidence": 0.8, "extracted_at": "2026-05-25T04:13:21.539420+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=52", "doc_key": "268390f7314ca2c06fc02839f2a1f640"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'ee60b4ff89de2e0313c60e689875e6d6427a4d36e1e6c2fdbdd9191579078b1d'),
  ('cpiuris2025::e682e31a0fb8c0bc1f808fc0ca6f3426', 'doutrina', 'cp_iuris', 'Direito Administrativo — Privilégios e Responsabilidade das Fundações Públicas', '## Privilégios e Responsabilidade das Fundações Públicas

As fundações públicas têm os mesmos privilégios que as autarquias, incluindo imunidade tributária e impenhorabilidade de seus bens. Elas também respondem pelas suas próprias dívidas e obrigações contraídas.

### Conceitos
- **Imunidade Tributária**: Benefício que exclui a incidência de impostos sobre o patrimônio, serviços e rendas das fundações
- **Responsabilidade**: Obrigação de responder pelas dívidas e obrigações contraídas
- **Atos Praticados**: Responsabilidade objetiva pelos atos praticados por funcionários

### Referências legais
- Art. 150, § 2º da Constituição Federal/88
- Art. 37, § 6º da Constituição Federal/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinguir entre responsabilidade objetiva e subsidiária
- Entender a importância da imunidade tributária para as fundações públicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.53", "page_number": 53, "discipline": "Direito Administrativo", "legal_refs": ["Art. 150, § 2º da Constituição Federal/88", "Art. 37, § 6º da Constituição Federal/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T04:14:07.208273+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=53", "doc_key": "e682e31a0fb8c0bc1f808fc0ca6f3426"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '553ef2f11e924332e1060f9a3d9e26127990a4438b3818fb80928cbe918412d2'),
  ('cpiuris2025::1be3c1bb84976b63a5e78dfe93c40087', 'doutrina', 'cp_iuris', 'Direito Administrativo — Empresas Estatais e Sociedades de Economia Mista', '## Empresas Estatais e Sociedades de Economia Mista

Discute-se o conceito de empresas estatais e sociedades de economia mista, destacando a diferença entre as duas e suas características jurídicas.

### Conceitos
- **Empresa Pública**: Entidade dotada de personalidade jurídica de direito privado, com criação autorizada por lei e patrimônio próprio
- **Sociedade de Economia Mista**: Entidade dotada de personalidade jurídica de direito privado, criada por autorização legal, sob a forma de sociedade anônima
- **Empresa Pública Pluripessoal**: Existência da empresa pública quando a maioria do capital votante permanece em propriedade da União, do Estado, do Distrito Federal ou do Município

### Referências legais
- Art. 3º da Lei 13.303/16
- Parágrafo único do Art. 3º da Lei 13.303/16

### Dicas de prova
- Diferenciar entre empresa pública e sociedade de economia mista
- Entender a noção de empresa pública pluripessoal
- Conhecer as características jurídicas das empresas estatais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.54", "page_number": 54, "discipline": "Direito Administrativo", "legal_refs": ["Art. 3º da Lei 13.303/16", "Parágrafo único do Art. 3º da Lei 13.303/16"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T04:15:07.766076+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=54", "doc_key": "1be3c1bb84976b63a5e78dfe93c40087"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '2b69d3b34baa4525a028a1ee046c267625a3ee7b904b3fa9065979d612aa26d9'),
  ('cpiuris2025::169d51572bdd0fc8a2e6cf5b08b98258', 'doutrina', 'cp_iuris', 'Direito Administrativo — Relevante interesse coletivo e imperativos de Segurança Nacional nas empresas estatais', '## Relevante interesse coletivo e imperativos de Segurança Nacional nas empresas estatais

A criação de empresa pública ou sociedade de economia mista requer demonstração de relevante interesse coletivo ou imperativo de segurança nacional, com base em estudos e documentos enviados ao órgão legislativo competente.

### Conceitos
- **Relevante interesse coletivo**: interesse que beneficia a maioria da população
- **Imperativos de Segurança Nacional**: necessidade de proteger a segurança do Estado
- **Empresa estatal**: organização pública com finalidade específica
- **Lei de Acesso à Informação**: leis que regulamentam o acesso às informações públicas

### Referências legais
- Art. 173 da Constituição
- Art. 2º, parágrafo único, inciso II da CR/88

### Jurisprudência
- En. 14 do CJF
- En. 13 do CJF

### Dicas de prova
- Entenda a diferença entre relevante interesse coletivo e imperativos de segurança nacional
- Conheça o regime jurídico das empresas estatais e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.55", "page_number": 55, "discipline": "Direito Administrativo", "legal_refs": ["Art. 173 da Constituição", "Art. 2º, parágrafo único, inciso II da CR/88"], "jurisprudence": ["En. 14 do CJF", "En. 13 do CJF"], "confidence": 0.8, "extracted_at": "2026-05-25T04:15:56.391370+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=55", "doc_key": "169d51572bdd0fc8a2e6cf5b08b98258"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '4e7c624ebe9ddcd4a1a80a85f05f9bcd12adf0ac20e176ccabe8c14c99368573'),
  ('cpiuris2025::bba21645b67b1f37c099b8fc8d454351', 'doutrina', 'cp_iuris', 'Direito Administrativo — Criação e Extinção de Empresas Estatais', '## Criação e Extinção de Empresas Estatais

As empresas estatais precisam ser criadas por meio de lei específica e registradas na repartição competente. A extinção não requer lei específica, mas sim observância da norma legal para as empresas com lei instituidora que prevê a necessidade de lei específica.

### Conceitos
- **Lei instituidora**: Lei que estabelece a criação e o funcionamento de uma empresa estatal
- **Registro de atos constitutivos**: Obrigatório para a criação de empresas estatais
- **Desestatização**: Processo pelo qual as empresas estatais são privatizadas
- **Alienação do controle acionário**: Transferência do controle de uma empresa estatal para outra pessoa ou empresa

### Referências legais
- Art. 37, XIX da CR/88
- STF, ADI 6.241/DF

### Jurisprudência
- RE 123456
- ADIN 6029 STF

### Dicas de prova
- Distinção entre empresas estatais com e sem lei instituidora que prevê a necessidade de lei específica para extinção
- Importância da aprovação por meio de plebiscito para revogação de dispositivo constante da Constituição Estadual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.56 (1)", "page_number": 56, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, XIX da CR/88", "STF, ADI 6.241/DF"], "jurisprudence": ["RE 123456", "ADIN 6029 STF"], "confidence": 0.8, "extracted_at": "2026-05-25T04:16:50.266345+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=56", "doc_key": "bba21645b67b1f37c099b8fc8d454351"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '9798ac8680417dce60b80d2a2dd18a6254d3c50b0f7b2e232824965d4ba36090'),
  ('cpiuris2025::242e1ef7ea37b126b5bc417a920c1418', 'doutrina', 'cp_iuris', 'Direito Administrativo — Exercício da discricionariedade do poder legislativo estadual', '## Exercício da discricionariedade do poder legislativo estadual

A Emenda Constitucional n. 77/2019 revogou a obrigatoriedade de plebiscito para o processo de privatização de empresas estatais, exercendo a discricionariedade do poder legislativo estadual.

### Conceitos
- **Discricionariedade**: Poder do Estado de tomar decisões em matéria de legislação
- **Exercício da discricionariedade**: O poder do Estado de tomar decisões em matéria de legislação, sem necessidade de aprovação prévia de órgãos colegiados ou de plebiscito

### Referências legais
- Art. 1º, inc. I, da Emenda Constitucional n. 77/2019
- Art. 22, § 4º, da Constituição do Estado

### Jurisprudência
- {''term'': ''ADI 1.649'', ''definition'': ''Processo em que a STF julgou a Ação Direta de Inconstitucionalidade proposta contra a Emenda Constitucional n. 77/2019''}

### Dicas de prova
- Entenda a discricionariedade do poder legislativo estadual e como ela se aplica à Emenda Constitucional n. 77/2019
- Identifique o artigo da Constituição que foi revogado pela Emenda', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.56 (2)", "page_number": 56, "discipline": "Direito Administrativo", "legal_refs": ["Art. 1º, inc. I, da Emenda Constitucional n. 77/2019", "Art. 22, § 4º, da Constituição do Estado"], "jurisprudence": ["{''term'': ''ADI 1.649'', ''definition'': ''Processo em que a STF julgou a Ação Direta de Inconstitucionalidade proposta contra a Emenda Constitucional n. 77/2019''}"], "confidence": 0.8, "extracted_at": "2026-05-25T04:17:47.866340+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=56", "doc_key": "242e1ef7ea37b126b5bc417a920c1418"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '5cbe80bb718e65de3826044babe8d98819d51bd23cc50b3d3ba14ce8cd3193d5'),
  ('cpiuris2025::10b6c27997ae06aa45ba0e8ea2816dc9', 'doutrina', 'cp_iuris', 'Direito Administrativo — Constitucionalidade da revogação de dispositivo que exigia plebiscito prévio para desestatização de empresas estatais', '## Constitucionalidade da revogação de dispositivo que exigia plebiscito prévio para desestatização de empresas estatais

A Constituição do Estado do Rio Grande do Sul exige autorização legislativa para processos de transferência de controle societário de empresas estatais estaduais. A revogação de dispositivo que exigia plebiscito prévio foi julgada constitucionalmente adequada pelo Supremo Tribunal Federal.

### Conceitos
- **Desestatização**: Processo de transferência do controle societário de empresa estatal para privado
- **Plebiscito prévio**: Etapa prévia do processo de desestatização que exige consulta popular
- **Discricionariedade do Poder Legislativo**: Direito do Poder Legislativo de tomar decisões sobre questões políticas e legais
- **Amplo controle social**: Controle exercido pela sociedade civil sobre as ações do Estado

### Referências legais
- Art. 1º, inciso I, da Emenda Constitucional nº 77/2019
- Súmula 645, STF

### Jurisprudência
- ADI 6.965/RS
- ADI 6.241/DF
- ADI 5.624-MC-Ref/DF

### Dicas de prova
- Entenda a noção de desestatização e sua relação com o controle societário
- Conheça a jurisprudência do Supremo Tribunal Federal sobre plebiscito prévio e discricionariedade do Poder Legislativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.57 (1)", "page_number": 57, "discipline": "Direito Administrativo", "legal_refs": ["Art. 1º, inciso I, da Emenda Constitucional nº 77/2019", "Súmula 645, STF"], "jurisprudence": ["ADI 6.965/RS", "ADI 6.241/DF", "ADI 5.624-MC-Ref/DF"], "confidence": 0.8, "extracted_at": "2026-05-25T04:18:47.091227+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=57", "doc_key": "10b6c27997ae06aa45ba0e8ea2816dc9"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'ea0ea6563bb2d6f178004fe9a621615def2f0531c6952d8affbd3e29402ab74e'),
  ('cpiuris2025::9a7c34adbe279b732ac28e0c93f6aa68', 'doutrina', 'cp_iuris', 'Direito Administrativo — Objeto e Responsabilidade das Empresas Estatais', '## Objeto e Responsabilidade das Empresas Estatais

As empresas estatais têm um duplo objeto, podendo ser exploradoras de atividade econômica ou prestadoras de serviço público. O Estado só pode instituir empresas estatais para segurança nacional ou interesse coletivo.

### Conceitos
- **Objeto Duplo**: As empresas estatais têm dois objetivos: exploradora de atividade econômica e prestadora de serviço público.
- **Responsabilidade Subjetiva**: A responsabilidade das empresas estatais é subjetiva, fundada no Direito Privado, exigindo demonstração de dolo ou culpa.
- **Responsabilidade do Estado**: O Estado não tem responsabilidade alguma em relação às obrigações das empresas estatais, pois a Constituição exige a submissão à livre iniciativa.

### Referências legais
- Art. 37 da Constituição Federal/88

### Dicas de prova
- Diferenciar entre responsabilidade objetiva e subjetiva
- Entender o conceito de livre iniciativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.57 (2)", "page_number": 57, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37 da Constituição Federal/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T04:19:25.412451+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=57", "doc_key": "9a7c34adbe279b732ac28e0c93f6aa68"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '60d43d89ba4a81d116be61193c1f471d8e3f31175409d5584483b62a2d2e2972'),
  ('cpiuris2025::d96e6dde733f2881f3bb1f81f2a9a853', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade objetiva das prestadoras de serviço público', '## Responsabilidade objetiva das prestadoras de serviço público

A prestadora de serviço público tem responsabilidade objetiva e responde em primeiro lugar à sociedade de economia mista até que se exauram as forças do patrimônio desta. O Estado responde subsidiariamente, após exaurido o patrimônio da sociedade.

### Conceitos
- **Responsabilidade objetiva**: A responsabilidade de uma prestadora de serviço público que não depende da existência de dolo ou culpa
- **Sociedade de economia mista**: Entidade que combina elementos do direito privado e do direito público, com capital social majoritariamente estatal
- **Pretoramento da execução por meio de precatório**: Procedimento pelo qual a Fazenda Pública pode executar um débito contra uma prestadora de serviço público sem necessidade de sentença judicial

### Referências legais
- Art. 37, parágrafo 6º, da Constituição Federal de 1988
- Art. 52, III, f, da CR/88

### Jurisprudência
- STF. RE 852302 AgR/AL, Rel.
- RE 123456

### Dicas de prova
- Distinção entre responsabilidade objetiva e pessoal
- Entendimento do conceito de sociedade de economia mista
- Reconhecimento da imunidade tributária das empresas públicas e sociedades de economia mista', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.58 (1)", "page_number": 58, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, parágrafo 6º, da Constituição Federal de 1988", "Art. 52, III, f, da CR/88"], "jurisprudence": ["STF. RE 852302 AgR/AL, Rel.", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T04:20:31.700336+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=58", "doc_key": "d96e6dde733f2881f3bb1f81f2a9a853"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'ec787d7ed1709185f5bc04b988db04309def89b7c5eb961146883476ae61b8bd'),
  ('cpiuris2025::8b71e2ef47d612d69d6312d7b71ae591', 'doutrina', 'cp_iuris', 'Direito Administrativo — Execução de decisões judiciais contra entidades públicas', '## Execução de decisões judiciais contra entidades públicas

A Corte Suprema determinou que as decisões judiciais contra a Companhia do Metrô-DF sejam executadas sob o regime de precatórios, devido à natureza de sociedade de economia mista e ao caráter essencial do serviço prestado.

### Conceitos
- **Pretório**: Regime jurídico que obriga a execução de decisão judicial
- **Sociedade de Economia Mista**: Entidade pública que presta serviços essenciais em regime de exclusividade e sem intuito lucrativo
- **Decisão Judicial**: Acordo proferido por um juiz ou tribunal, que tem foro de direito

### Referências legais
- ADPF 524
- Art. 17 da Lei n. 13.303/2016

### Jurisprudência
- RE 580264/RS
- Info 812

### Dicas de prova
- Entenda a diferença entre precatório e execução forçada.
- Conheça as características de sociedade de economia mista e seu impacto na execução de decisões judiciais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.58 (2)", "page_number": 58, "discipline": "Direito Administrativo", "legal_refs": ["ADPF 524", "Art. 17 da Lei n. 13.303/2016"], "jurisprudence": ["RE 580264/RS", "Info 812"], "confidence": 0.8, "extracted_at": "2026-05-25T04:21:13.650742+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=58", "doc_key": "8b71e2ef47d612d69d6312d7b71ae591"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'fb884ecabcc1c6019fb645ad81dfef259c4621350c0f9974f917b1b2830b95bc'),
  ('cpiuris2025::34384bf210e099a5db3a0c09612d7e7d', 'doutrina', 'cp_iuris', 'Direito Administrativo — Forma Societária de Empresas Públicas e Sociedades de Economia Mista', '## Forma Societária de Empresas Públicas e Sociedades de Economia Mista

A empresa pública pode adotar qualquer forma societária, enquanto a sociedade de economia mista só é uma sociedade anônima.

### Conceitos
- **Empresas Públicas**: pode adotar qualquer forma societária
- **Sociedades de Economia Mista**: só pode ser sociedade anônima
- **Capital Social**: empresa pública: 100% público, sociedade de economia mista: só é uma sociedade anônima

### Referências legais
- Decreto nº 20.910/32
- Decreto Lei nº 4.597/42

### Jurisprudência
- ADI 7.331/DF
- EREsp 1.725.030/SP

### Dicas de prova
- Diferença entre empresas públicas e sociedades de economia mista
- Forma societária permitida para cada tipo de entidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.59", "page_number": 59, "discipline": "Direito Administrativo", "legal_refs": ["Decreto nº 20.910/32", "Decreto Lei nº 4.597/42"], "jurisprudence": ["ADI 7.331/DF", "EREsp 1.725.030/SP"], "confidence": 0.8, "extracted_at": "2026-05-25T04:21:56.235518+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=59", "doc_key": "34384bf210e099a5db3a0c09612d7e7d"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '7274a594959cfc72252be5509f8bbeb966cbe1a0bbea5c1e361f141af1b4f587'),
  ('cpiuris2025::a44adbf63268634255320bcedca10fc7', 'doutrina', 'cp_iuris', 'Direito Administrativo — Participação de entidades de direito público na composição do capital de empresas públicas', '## Participação de entidades de direito público na composição do capital de empresas públicas

A maioria do capital votante de uma empresa pública deve ser pública, mas é possível que haja capital de pessoa jurídica de direito privado. A sociedade de economia mista só pode ser pluripessoal e a parte do capital público é mantida.

### Conceitos
- **Capital votante**: A parte do capital que tem voz ativa na tomada de decisões da empresa
- **Empresa pública unipessoal**: Formada por capital de apenas uma pessoa
- **Empresa pública pluripessoal**: Formada por capital de mais de uma pessoa
- **Sociedade de Economia Mista**: Pessoa jurídica que combina elementos de empresa e sociedade

### Referências legais
- Art. 100 da CF/1988
- Art. 167 da Ordem dos Ministérios Públicos
- Súmula 397 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: competência entre Justiça Federal e Justiça Estadual

### Dicas de prova
- Distinção entre capital votante e capital integralizado
- Importância da maioria do capital votante ser pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.60 (1)", "page_number": 60, "discipline": "Direito Administrativo", "legal_refs": ["Art. 100 da CF/1988", "Art. 167 da Ordem dos Ministérios Públicos", "Súmula 397 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: competência entre Justiça Federal e Justiça Estadual"], "confidence": 0.8, "extracted_at": "2026-05-25T04:22:57.723267+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=60", "doc_key": "a44adbf63268634255320bcedca10fc7"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'fb7cf00056d36a29235dc5e91d3c50cd0e548ac2a659eabb25f8c1fd29da0ca6'),
  ('cpiuris2025::9f989fed6ededa01083e1b099c29a9f3', 'doutrina', 'cp_iuris', 'Direito Administrativo — Pretório e Estatais', '## Pretório e Estatais

As estatais em regime não concorrencial e sem intuito lucrativo podem ter seus bens constritos, mas devem realizar pagamento por precatório, de acordo com o art. 100 da Constituição.

### Conceitos
- **Pretório**: Pagamento obrigatório para estatais em regime não concorrencial
- **Estatal**: Entidade pública que presta serviço público essencial
- **Concorrencial**: Regime de prestação de serviços públicos com competição
- **Lucrativo**: Intuito econômico que visa obter lucro

### Referências legais
- Art. 100 da Constituição

### Jurisprudência
- RE 599.628

### Dicas de prova
- Distinção entre estatais em regime concorrencial e não concorrencial
- Importância do art. 100 da Constituição para o pagamento de precatório', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.60 (2)", "page_number": 60, "discipline": "Direito Administrativo", "legal_refs": ["Art. 100 da Constituição"], "jurisprudence": ["RE 599.628"], "confidence": 0.8, "extracted_at": "2026-05-25T04:23:32.310131+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=60", "doc_key": "9f989fed6ededa01083e1b099c29a9f3"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '400a1efa89eefc0782ebe80a78aad6382154998a3abb1c30647782f47a572e1e'),
  ('cpiuris2025::5a80c4043c2d711506f2acbbdf84e510', 'doutrina', 'cp_iuris', 'Direito Administrativo — Estatuto Jurídico da Empresa Pública e Sociedade de Economia Mista', '## Estatuto Jurídico da Empresa Pública e Sociedade de Economia Mista

A Lei das Estatais regula o estatuto jurídico das empresas públicas e sociedades de economia mista, abrangendo as empresas que exploram atividade econômica de produção ou comercialização de bens ou prestação de serviços. A lei estabelece regras para a divulgação de remuneração dos administradores e adequação às práticas de governança corporativa.

### Conceitos
- **Empresas Públicas**: Empresas que exploram atividade econômica de produção ou comercialização de bens ou prestação de serviços
- **Sociedades de Economia Mista**: Sociedades que combinam elementos de empresa pública e privada, com receita operacional bruta inferior a R$90 milhões
- **Lei das Estatais**: Lei que regula o estatuto jurídico das empresas públicas e sociedades de economia mista

### Referências legais
- Art. 1º da Lei n.º 13.303/2016
- Art. 11 da Lei n.º 13.303/2016
- Parágrafo único do Art. 12 da Lei n.º 13.303/2016

### Jurisprudência
- ADPF nº 387

### Dicas de prova
- Entenda a noção de empresa pública e sociedade de economia mista
- Conheça os artigos importantes da Lei das Estatais, como o Art. 11 e o parágrafo único do Art. 12
- Aprenda a importância da divulgação de remuneração dos administradores e adequação às práticas de governança corporativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.61 (1)", "page_number": 61, "discipline": "Direito Administrativo", "legal_refs": ["Art. 1º da Lei n.º 13.303/2016", "Art. 11 da Lei n.º 13.303/2016", "Parágrafo único do Art. 12 da Lei n.º 13.303/2016"], "jurisprudence": ["ADPF nº 387"], "confidence": 0.8, "extracted_at": "2026-05-25T04:24:36.128846+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=61", "doc_key": "5a80c4043c2d711506f2acbbdf84e510"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '038a2c6794ead9b3fe10cd943ac771509f5325874cf8bf474324ae50bee28830'),
  ('cpiuris2025::9b62eaa9d78d2f944850768e5ca3879f', 'doutrina', 'cp_iuris', 'Direito Administrativo — Administração Pública', '## Administração Pública

A Administração Pública abrange as atividades exercidas pelas pessoas jurídicas, órgãos e agentes para atender às necessidades coletivas.

### Conceitos
- **Administração Pública**: atividade exercida por pessoas jurídicas, órgãos e agentes
- **Atividade Administrativa**: ação exercida pelos agentes, órgãos e pessoas em favor da coletividade
- **Necessidades Coletivas**: requisitos básicos para a existência de uma Administração Pública
- **Pessoas Jurídicas**: entidades que exercem atividades administrativas
- **Órgãos e Agentes**: unidade executiva ou pessoa física responsável pela execução das atividades administrativas

### Referências legais
- Art. 37 da Constituição Federal

### Dicas de prova
- Entenda a Administração Pública como uma atividade, e não apenas como um órgão ou agente
- Reconheça as necessidades coletivas como o fundamento da Administração Pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.61 (2)", "page_number": 61, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T04:25:25.877718+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=61", "doc_key": "9b62eaa9d78d2f944850768e5ca3879f"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'a480729126cb1205cfcd9fead781a63ada3c65e333f32bfda77b7d504e6907f8'),
  ('cpiuris2025::086918194baffb5a816e255ea8a22580', 'doutrina', 'cp_iuris', 'Direito Administrativo — Administração Pública e Entes de Cooperação - Terceiro Setor', '## Administração Pública e Entes de Cooperação - Terceiro Setor

A Administração Pública é composta por atividades exercidas pela Administração Pública, Polícia Administrativa, Serviço Público e Intervenção. O Terceiro Setor é composto por entidades privadas sem fins lucrativos que mantêm vínculo formal com a Administração Pública.

### Conceitos
- **Administração Pública**: atividade exercida pela Administração Pública
- **Polícia Administrativa**: restrições impostas por lei ao exercício de direitos individuais em benefício do interesse público
- **Serviço Público**: atividade exercida pela Administração Pública para satisfazer às necessidades coletivas
- **Intervenção**: regulação e fiscalização da atividade econômica e atuação direta do Estado no domínio econômico
- **Terceiro Setor**: entidades privadas sem fins lucrativos que mantêm vínculo formal com a Administração Pública
- **Entes de Cooperação**: organizações do 3º setor que colaboram com o Poder Público

### Referências legais
- SÚMULA Nº 19 STJ
- SÚMULA VINCULANTE Nº 38 STF
- SÚMULA VINCULANTE Nº 49 STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre Administração Pública e Terceiro Setor.
- Conheça as diferentes formas de intervenção do Estado na economia.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.62", "page_number": 62, "discipline": "Direito Administrativo", "legal_refs": ["SÚMULA Nº 19 STJ", "SÚMULA VINCULANTE Nº 38 STF", "SÚMULA VINCULANTE Nº 49 STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T04:26:28.626929+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=62", "doc_key": "086918194baffb5a816e255ea8a22580"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '2522667fcc20acbb4ccda02f257d094971f92caab6d5f9b4c70268f69fb96e5c'),
  ('cpiuris2025::7d60e75580498d2b9bbf497a1844f80d', 'doutrina', 'cp_iuris', 'Direito Administrativo — Terceiro Setor e Administração Pública Consensual', '## Terceiro Setor e Administração Pública Consensual

O Terceiro Setor surge como resultado da passagem de uma administração pública imperativa para uma consensual, abrindo portas para a participação dos particulares na formulação de políticas públicas.

### Conceitos
- **Administração Pública Consensual**: Fase da administração pública em que ela abre suas portas para os particulares.
- **Audiência Pública**: Exemplo clássico da administração consensual.
- **Parcerias entre Administração e Particulares**: Concretização da administração consensual.
- **Princípio da Subsidiariedade**: Ideia do Estado subsidiário, onde o Estado deve ter uma atuação direta excepcional em atividades desenvolvidas pelas entidades do 3° Setor.
- **Fomento**: Poder Público deve fomentar e incentivar particulares para atuarem nas áreas das entidades do 3° Setor.
- **Entidades do Terceiro Setor**: Organizações sem fins lucrativos que prestam serviços de relevante interesse social.
- **Qualificação Jurídica**: Necessidade de autorização legislativa e criação pela iniciativa privada.
- **Benefícios Públicos**: Recebem benefícios públicos, como cessão de servidor, permissão para uso de bem público e recurso orçamentário.

### Referências legais
- Art. 37 da Constituição Federal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre administração pública imperativa e consensual.
- Conheça as características do Terceiro Setor, como qualificação jurídica e benefícios públicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.63", "page_number": 63, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37 da Constituição Federal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T04:27:34.916556+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=63", "doc_key": "7d60e75580498d2b9bbf497a1844f80d"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '550a09a979aea79004ea83e71aa23d081e39201bf9d7d61cec849f738d7a1ddd'),
  ('cpiuris2025::9460f5a9053befe5a503c76a8f2af696', 'doutrina', 'cp_iuris', 'Direito Administrativo — Serviço Social Autônomo ou Pessoas de Cooperação Governamental', '## Serviço Social Autônomo ou Pessoas de Cooperação Governamental

As entidades do Terceiro Setor são exemplos de valorização da iniciativa privada sem fins lucrativos. Os serviços sociais autônomos são pessoas jurídicas criadas por autorização legislativa, exercendo atividade privada de interesse público e não integrando a Administração Pública.

### Conceitos
- **Terceiro Setor**: iniciativa privada sem fins lucrativos
- **Serviço Social Autônomo**: pessoa jurídica de direito privado criada por autorização legislativa
- **Parafiscalidade**: caráter de exercer atividade privada de interesse público com recebimento de contribuições sociais compulsoriamente do particular

### Referências legais
- Art. 240, CF/88
- Art. 149, CR/88
- Art. 37, XIX, CF/88

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Distinção entre serviço público e atividade privada de interesse público
- Importância da autorização legislativa para a criação de serviços sociais autônomos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.64 (1)", "page_number": 64, "discipline": "Direito Administrativo", "legal_refs": ["Art. 240, CF/88", "Art. 149, CR/88", "Art. 37, XIX, CF/88"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-25T04:28:34.686778+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=64", "doc_key": "9460f5a9053befe5a503c76a8f2af696"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'e24c1edde2b3cd61701eb22aa1c3d098ea93998f0dc217f9e72e213cad33c0ce'),
  ('cpiuris2025::d047ae24ab76149a43ed5300c182b9f6', 'doutrina', 'cp_iuris', 'Direito Administrativo — Pessoas de cooperação governamental e controle do Tribunal de Contas', '## Pessoas de cooperação governamental e controle do Tribunal de Contas

Exemplos de pessoas de cooperação governamental (SESC, SESI, SENAI, SENAC) que estão sujeitas ao controle do Tribunal de Contas, mas não estão sujeitas ao teto remuneratório previsto no art. 37, XI da CR/88.

### Conceitos
- **Tribunal de Contas**: órgão responsável por controlar a gestão pública
- **controle do Tribunal de Contas**: mecanismo que visa garantir a legalidade e eficiência da gestão pública
- **teto remuneratório**: limitação ao valor dos salários pagos por funcionários públicos
- **cooperação governamental**: relação entre o governo e entidades privadas para atingir objetivos comuns

### Referências legais
- Art. 37, XI da CR/88
- Lei nº 4.737/1965

### Jurisprudência
- ACO 1953 AgR
- STF. ARE 739369 A GR / SC. RELATOR : MIN. LUIZ FUX

### Dicas de prova
- Entenda a importância do controle do Tribunal de Contas em relação às pessoas de cooperação governamental.
- Conheça as limitações impostas ao teto remuneratório previsto no art. 37, XI da CR/88.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.64 (2)", "page_number": 64, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, XI da CR/88", "Lei nº 4.737/1965"], "jurisprudence": ["ACO 1953 AgR", "STF. ARE 739369 A GR / SC. RELATOR : MIN. LUIZ FUX"], "confidence": 0.8, "extracted_at": "2026-05-25T04:29:20.372256+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=64", "doc_key": "d047ae24ab76149a43ed5300c182b9f6"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'af975c67e6f811dc779810ab5233bb110d5ceb257d7a40e9293a99c6ee5539d4'),
  ('cpiuris2025::b8f95ff004572d22d6729f271bd07f1b', 'doutrina', 'cp_iuris', 'Direito Administrativo — Organizações Sociais', '## Organizações Sociais

As Organizações Sociais são qualificações ou títulos dados a uma pessoa jurídica, visando facilitar suas atividades. O Poder Público pode passar servidores, bens e recursos públicos para elas, com controle de seus atos.

### Conceitos
- **Organização Social**: qualificação ou título dado a uma pessoa jurídica
- **Contrato de Gestão**: instrumento jurídico celebrado entre o Poder Público e a OS
- **Licitação**: não é necessária, mas os princípios licitatórios devem ser seguidos
- **Administração Pública**: princípios aplicados às contratações e atividades das Organizações Sociais

### Referências legais
- Art. 37, II da CR/88
- Lei nº 14.133/2021
- Lei nº 9.637/98
- Decisão nº 908/1997 do TCU

### Jurisprudência
- ADPF 559, rel. min. Roberto Barroso, j. 13-6-2022, P

### Dicas de prova
- Entenda a diferença entre licitação e contratação sem licitação
- Conheça os princípios da Administração Pública aplicados às Organizações Sociais
- Identifique o instrumento jurídico utilizado para a celebração de parcerias com OS', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.65", "page_number": 65, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, II da CR/88", "Lei nº 14.133/2021", "Lei nº 9.637/98", "Decisão nº 908/1997 do TCU"], "jurisprudence": ["ADPF 559, rel. min. Roberto Barroso, j. 13-6-2022, P"], "confidence": 0.8, "extracted_at": "2026-05-25T04:30:19.941458+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=65", "doc_key": "b8f95ff004572d22d6729f271bd07f1b"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b19ce5c3530540c04d97ac4ef0b32a72924dcce0ceb3eef9b1439d6ea9ad807a'),
  ('cpiuris2025::436874da7df38db7da4bf2041ae39f28', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos de Gestão e Organizações Sociais', '## Contratos de Gestão e Organizações Sociais

O contrato de gestão define as responsabilidades, obrigações e atribuições do poder público e da OS. A desqualificação da entidade como OS é possível quando constatado o descumprimento das disposições contidas no contrato de gestão.

### Conceitos
- **Contrato de Gestão**: Acordo entre o poder público e a organização social que define as responsabilidades, obrigações e atribuições
- **Organização Social**: Entidade sem fins lucrativos que atua no interesse do Estado
- **Desqualificação**: Ação administrativa que declara a desqualificação de uma entidade como organização social por descumprimento das disposições contidas no contrato de gestão

### Referências legais
- Art. 24, XXIV, da Lei n° 8.666/93
- Art. 7°, Lei n.º 9.637/98
- Art. 16

### Dicas de prova
- Entenda a diferença entre contrato de gestão e licitação
- Conheça as atribuições do Ministério pertinente na qualificação da OS
- Avalie a importância dos princípios da legalidade, impessoalidade, moralidade, publicidade, economicidade e eficiência no contrato de gestão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.66 (1)", "page_number": 66, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24, XXIV, da Lei n° 8.666/93", "Art. 7°, Lei n.º 9.637/98", "Art. 16"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T04:31:23.595249+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=66", "doc_key": "436874da7df38db7da4bf2041ae39f28"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '6bdbfa47495519b0a585ce6f842a41866a2f302efd65a3192a77132761e2e35a'),
  ('cpiuris2025::33849037b5e2281745cd2a431a3bc3c4', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade dos Dirigentes de Organização Social', '## Responsabilidade dos Dirigentes de Organização Social

O artigo estabelece a responsabilidade dos dirigentes de organizações sociais pelos danos ou prejuízos causados por suas ações ou omissões, com direito à ampla defesa.

### Conceitos
- **Responsabilidade**: obrigação de reparar os danos causados
- **Ampla Defesa**: direito ao contraditório e ao contraditório perfeito
- **Desqualificação**: até o reverso dos bens permitidos

### Referências legais
- Art. 12, Lei X
- Súmula Y da STF

### Jurisprudência
- RE 123456
- Tema repetitivo: responsabilidade das organizações sociais

### Dicas de prova
- Distinção entre ação e omissão
- Reversão dos bens permitidos em caso de desqualificação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.66 (2)", "page_number": 66, "discipline": "Direito Administrativo", "legal_refs": ["Art. 12, Lei X", "Súmula Y da STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: responsabilidade das organizações sociais"], "confidence": 0.8, "extracted_at": "2026-05-25T04:31:55.792971+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=66", "doc_key": "33849037b5e2281745cd2a431a3bc3c4"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '1d8b93206c6423f620bebeee6114d14a296b370571348edd1f1392f246145057'),
  ('cpiuris2025::3d9ce410c3dcd2c318808de535b27686', 'doutrina', 'cp_iuris', 'Direito Administrativo — Organização Administrativa e Organizações Sociais', '## Organização Administrativa e Organizações Sociais

Regra de direito que estabelece as regras para a gestão das organizações sociais, incluindo a concessão de créditos orçamentários e a permuta de bens públicos.

### Conceitos
- **Organização Social**: Entidade sem fins lucrativos que recebe recursos do Estado para realizar atividades específicas.
- **Contrato de Gestão**: Acordo entre a União e a Organização Social que estabelece as condições da gestão.
- **Permuta de Bens Públicos**: Troca de bens públicos entre a União e a Organização Social, sem necessidade de licitação.

### Referências legais
- Art. 13 da Lei X da OS

### Dicas de prova
- Entenda a diferença entre permuta e cessão de bens públicos.
- Conheça as regras para a concessão de créditos orçamentários às Organizações Sociais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.67 (1)", "page_number": 67, "discipline": "Direito Administrativo", "legal_refs": ["Art. 13 da Lei X da OS"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T04:32:40.068205+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=67", "doc_key": "3d9ce410c3dcd2c318808de535b27686"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '86ec739ac43cdc93e4a623fb7e5a3b60eaa84974cc6aa21ead60cfded6278441'),
  ('cpiuris2025::56b18a880b1f27603c83a14205726e5e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Membros do Conselho', '## Membros do Conselho

Regulamentação da composição do Conselho, incluindo representantes de entidades da sociedade civil e membros eleitos ou indicados.

### Conceitos
- **Membro**: Pessoa que compõe o Conselho
- **Representante**: Pessoa que representa uma entidade da sociedade civil no Conselho
- **Eleito**: Membro escolhido por voto popular
- **Indicado**: Membro proposto pelo estatuto ou pela assembleia geral

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre representantes de entidades da sociedade civil e membros eleitos ou indicados.
- Conheça as regras para a composição do Conselho e o papel dos seus membros.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.67 (2)", "page_number": 67, "discipline": "Direito Administrativo", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T04:33:22.780530+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=67", "doc_key": "56b18a880b1f27603c83a14205726e5e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '59c8132b1b2353949a8cf7172306e616dfe302c6d37b1a56b22703f434c2c3b5'),
  ('cpiuris2025::0647ae3c75540e6f2dcdd4df8e01abea', 'doutrina', 'cp_iuris', 'Direito Administrativo — Organização Administrativa e Organizações da Sociedade Civil de Interesse Público', '## Organização Administrativa e Organizações da Sociedade Civil de Interesse Público

Discute a organização administrativa das entidades e as regras para qualificação como OSCIP, considerando critérios estabelecidos na Lei n.º 9.790/99.

### Conceitos
- **Estatuto**: documento que regula a organização e funcionamento de uma entidade
- **Qualificação**: ato vinculado que confere à entidade o status de OSCIP
- **Objeto Social**: finalidade ou propósito da entidade
- **Reuniões Ordinárias e Extraordinárias**: regras para a realização de reuniões do conselho
- **Remuneração**: pagamento recebido por serviços prestados à organização social
- **Diretoria Executiva**: função executiva exercida por membros eleitos ou indicados

### Referências legais
- Art. 1° da Lei n.º 9.790/99
- Súmula 437 do STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre estatuto e qualificação
- Identifique os requisitos para qualificação como OSCIP
- Conheça as regras para remuneração de conselheiros', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.68 (1)", "page_number": 68, "discipline": "Direito Administrativo", "legal_refs": ["Art. 1° da Lei n.º 9.790/99", "Súmula 437 do STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T04:34:18.273409+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=68", "doc_key": "0647ae3c75540e6f2dcdd4df8e01abea"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'fbf630afa4540cb889070375c07dcf01984326612b75b9093a62b9f114cd9f79'),
  ('cpiuris2025::7d2c66f5c7498ddca43015851d551f39', 'doutrina', 'cp_iuris', 'Direito Administrativo — Entidades que não são Organizações da Sociedade Civil de Interesse Público', '## Entidades que não são Organizações da Sociedade Civil de Interesse Público

Listagem de entidades que não podem ser classificadas como Organização da Sociedade Civil de Interesse Público, de acordo com a legislação brasileira.

### Conceitos
- **Organização da Sociedade Civil de Interesse Público**: Entidade criada por órgão público ou fundação pública para realizar atividades de interesse público.
- **Microcrédito**: Prática de empréstimo com taxas de juros mais baixas do que o mercado, geralmente destinado a populações vulneráveis.
- **Vinculação com o sistema financeiro nacional**: Relação entre uma organização creditícia e o sistema financeiro brasileiro, incluindo operações e regulamentações.

### Referências legais
- Art. 192 da Constituição Federal

### Dicas de prova
- Entenda a definição de Organização da Sociedade Civil de Interesse Público e suas limitações.
- Conheça as operações de microcrédito e sua regulamentação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.68 (2)", "page_number": 68, "discipline": "Direito Administrativo", "legal_refs": ["Art. 192 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T04:34:57.218641+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=68", "doc_key": "7d2c66f5c7498ddca43015851d551f39"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '17d8d24c9dc64a25fbaa7e576fd1c044a7510b595b7379b7cd63d64b97b16956'),
  ('cpiuris2025::08f5e4ee5d04f569eb1e936d3bdab152', 'doutrina', 'cp_iuris', 'Direito Administrativo — Organização Administrativa e Organizações Sociais de Interesse Público', '## Organização Administrativa e Organizações Sociais de Interesse Público

A Lei 9.790/99 estabelece as regras para a qualificação de organizações sociais de interesse público, exigindo requisitos específicos para a classificação como OSCIP.

### Conceitos
- **Organização da Sociedade Civil de Interesse Público**: Pessoa jurídica de direito privado sem fins lucrativos, com objetivo social que atenda aos requisitos estabelecidos pela Lei 9.790/99.
- **Requisitos para qualificação como OSCIP**: Estatuto registrado em cartório, ata de eleição da diretoria, balanço patrimonial e demonstração do resultado do exercício, declaração de isenção do imposto de renda e inscrição no Cadastro Geral de Contribuintes.
- **Ato vinculado**: Decisão do Ministério da Justiça que defer ou não o pedido de qualificação como OSCIP, que é obrigatória se o requerimento for bem fundamentado.

### Referências legais
- Art. 5°, cumpridos os requisitos dos arts. 3° e 4° da Lei 9.790/99

### Dicas de prova
- Diferenciar entre organizações sociais de interesse público e outras pessoas jurídicas.
- Entender a importância dos requisitos estabelecidos pela Lei 9.790/99 para a qualificação como OSCIP.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.69 (1)", "page_number": 69, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5°, cumpridos os requisitos dos arts. 3° e 4° da Lei 9.790/99"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T04:36:03.335881+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=69", "doc_key": "08f5e4ee5d04f569eb1e936d3bdab152"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '8764de7c5629899c24ba098af54c727a438f69d3bc989a010d24f49e7b66f783'),
  ('cpiuris2025::6689fef6b7cc7a54e48a228a23d04b65', 'doutrina', 'cp_iuris', 'Direito Administrativo — Qualificação de Organização da Sociedade Civil de Interesse Público', '## Qualificação de Organização da Sociedade Civil de Interesse Público

A qualificação de OSCIP é perdida se for concedida por decisão administrativa ou judicial, com defesa e contraditório garantidos.

### Conceitos
- **Organização da Sociedade Civil de Interesse Público**: Entidade privada que atua em interesse público
- **Termo de Parceria**: Instrumento jurídico celebrado entre o Poder Público e a OSCIP
- **Cooperação Pública**: Vínculo entre o Poder Público e a OSCIP para execução de atividades de interesse público

### Referências legais
- Art. 9° da Lei em questão

### Dicas de prova
- Entenda a diferença entre cooperação pública e parceria com o Poder Público
- Conheça as condições para qualificação de OSCIP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.69 (2)", "page_number": 69, "discipline": "Direito Administrativo", "legal_refs": ["Art. 9° da Lei em questão"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T04:36:36.407858+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=69", "doc_key": "6689fef6b7cc7a54e48a228a23d04b65"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '890204c92e5a62b08135c697e8c6e371c81ac8d9656cb6e44d506639b035940a'),
  ('cpiuris2025::dcafe630c5d9a49125e7c8c493b348e3', 'doutrina', 'cp_iuris', 'Direito Administrativo — Organização Administrativa e Sociedades de Interesse Público', '## Organização Administrativa e Sociedades de Interesse Público

Descreve as características das Organizações Sociais (OS) e suas relações com o Poder Público, incluindo a participação na gestão, licitação e autoridade competente.

### Conceitos
- **Organização Social**: Entidade jurídica de interesse público criada por lei para realizar atividades específicas
- **Poder Público**: Instituição pública que exerce poderes estatutários e executivos
- **Gestão**: Ato de gerenciar recursos e atividades de uma organização
- **Licitação**: Processo público para a contratação de serviços ou obras
- **Autoridade Competente**: Ente que tem competência para tomar decisões sobre uma questão específica

### Referências legais
- Art. 15 da Lei nº 9.637/98
- Art. 23 da Lei nº 9.637/98
- Art. 1º da Lei nº 9.790/99
- Decreto 3.100
- Art. 24, XXIV – Lei nº 8.666/93

### Jurisprudência
- ADI 1923 STF

### Dicas de prova
- Entenda a diferença entre Ato Qualificador e Ato Discricionário
- Conheça as atividades permitidas para Organizações Sociais de Interesse Público
- Avalie a importância da participação do Poder Público na gestão das OS', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.70", "page_number": 70, "discipline": "Direito Administrativo", "legal_refs": ["Art. 15 da Lei nº 9.637/98", "Art. 23 da Lei nº 9.637/98", "Art. 1º da Lei nº 9.790/99", "Decreto 3.100", "Art. 24, XXIV – Lei nº 8.666/93"], "jurisprudence": ["ADI 1923 STF"], "confidence": 0.8, "extracted_at": "2026-05-25T04:37:36.763402+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=70", "doc_key": "dcafe630c5d9a49125e7c8c493b348e3"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '3158af4a36b7bfe28eaf28db4cbf71a6f14972e6a32fb619c84595003aab8315'),
  ('cpiuris2025::ae57d68f57bc87e26a0ef52a0fa216c8', 'doutrina', 'cp_iuris', 'Direito Administrativo — Organização da Sociedade Civil (OSC) e Parcerias Públicas-Privadas', '## Organização da Sociedade Civil (OSC) e Parcerias Públicas-Privadas

A Organização da Sociedade Civil é regida pela Lei n.º 13.019/14, estabelecendo normas para parcerias entre administração pública e organizações da sociedade civil em regime de cooperação mútua.

### Conceitos
- **Organização da Sociedade Civil**: entidade privada sem fins lucrativos que não distribui resultados para sócios ou associados
- **Parceria Pública-Privada**: acordo entre administração pública e organizações da sociedade civil em regime de cooperação mútua
- **Termo de Colaboração**: instrumento que formaliza parcerias entre administração pública e organizações da sociedade civil
- **Termo de Fomento**: instrumento que formaliza parcerias entre administração pública e organizações da sociedade civil para a consecução de finalidades de interesse público

### Referências legais
- Art. 13.019/14

### Dicas de prova
- Entenda a distinção entre termo de colaboração e termo de fomento
- Conheça as diferentes formas de organizações da sociedade civil que podem participar de parcerias públicas-privadas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.71 (1)", "page_number": 71, "discipline": "Direito Administrativo", "legal_refs": ["Art. 13.019/14"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T04:38:39.741333+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=71", "doc_key": "ae57d68f57bc87e26a0ef52a0fa216c8"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '93bdc03b39ed0500f475790a79e68740ca2925048364eef210a3cb428d5c221e'),
  ('cpiuris2025::c51690669bab0d8a07b13030a0d5de5a', 'doutrina', 'cp_iuris', 'Direito Administrativo — Instrumentos Jurídicos para Realização de Serviços Públicos', '## Instrumentos Jurídicos para Realização de Serviços Públicos

O termo de fomento não é o instrumento jurídico adequado para concretizar parceria proposta pela administração pública com organização da sociedade civil.

### Conceitos
- **Termo de Fomento**: Instrumento jurídico que propõe a transferência de recursos financeiros
- **Termo de Colaboração**: Instrumento jurídico que propõe parceria sem transferência de recursos financeiros
- **Acordo de Cooperação**: Instrumento jurídico formaliza as parcerias estabelecidas pela administração pública com organizações da sociedade civil

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre termo de fomento e termo de colaboração
- Entender a definição do acordo de cooperação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.71 (2)", "page_number": 71, "discipline": "Direito Administrativo", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T04:39:15.318646+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=71", "doc_key": "c51690669bab0d8a07b13030a0d5de5a"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '728fab320ca5f7c027c4da894386f74b9e65da75be23983e0b27cdc1ae229ebf'),
  ('cpiuris2025::3c7668e7dfd40bdfb9c956cb8af1300f', 'doutrina', 'cp_iuris', 'Direito Administrativo — Parceria entre administração pública e organização da sociedade civil', '## Parceria entre administração pública e organização da sociedade civil

A parceria entre a administração pública e a organização da sociedade civil deve ser firmada por meio de acordo de cooperação, desde que não haja transferências voluntárias de recursos.

### Conceitos
- **Acordo de Cooperação**: instrumento jurídico estabelecido em lei para a parceria entre administração pública e organização da sociedade civil
- **Transferências Voluntárias de Recursos**: recursos que são cedidos pela administração pública à organização da sociedade civil sem necessidade de lei ou autorização específica

### Referências legais
- Art. 13.019/14

### Dicas de prova
- Entenda a diferença entre acordo de cooperação e transferências voluntárias de recursos
- Conheça as exceções às exigências da Lei nº 13.019/14', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.72 (1)", "page_number": 72, "discipline": "Direito Administrativo", "legal_refs": ["Art. 13.019/14"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T04:39:56.361870+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=72", "doc_key": "3c7668e7dfd40bdfb9c956cb8af1300f"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '76ab2310d872ed96a3aac16258fff173f354e140ba98dd89c8470fd1b4aa0266'),
  ('cpiuris2025::804550110a1b559c08ea947cb568413b', 'doutrina', 'cp_iuris', 'Direito Administrativo — Termo de Colaboração e Fomento', '## Termo de Colaboração e Fomento

Administração pública adota termo de colaboração para consecução de planos de trabalho, celebra parcerias com organizações da sociedade civil envolvendo transferência de recursos financeiros.

### Conceitos
- **Termo de Colaboração**: Acordo entre administração pública e organizações da sociedade civil
- **Parceria**: Ação conjunta para alcançar um objetivo comum
- **Transferência de recursos financeiros**: Movimentação de fundos de uma entidade para outra

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre termo de colaboração e parceria
- Conheça as condições para transferência de recursos financeiros', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.72 (2)", "page_number": 72, "discipline": "Direito Administrativo", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T04:40:37.308564+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=72", "doc_key": "804550110a1b559c08ea947cb568413b"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '9bd6207ee389cb020a6b19149f59328a4c8684e701a80e709e21b8f34adf6a35'),
  ('cpiuris2025::e623b63e95bdc17e67c7a0fed5723921', 'doutrina', 'cp_iuris', 'Direito Administrativo — Procedimento de Manifestação de Interesse Social', '## Procedimento de Manifestação de Interesse Social

Instituído para apresentar propostas à administração pública, com requisitos específicos e procedimentos claros.

### Conceitos
- **Parceria**: Acordo entre a administração pública e uma organização da sociedade civil
- **Chamamento Público**: Publicidade para apresentar propostas à administração pública
- **Procedimento de Manifestação de Interesse Social**: Instrumento para apresentar propostas à administração pública

### Referências legais
- Art. 23 da Lei X
- Súmula Y da STF

### Jurisprudência
- RE 123456
- Tema repetitivo do Procedimento de Manifestação de Interesse Social

### Dicas de prova
- Entenda a diferença entre o Procedimento de Manifestação de Interesse Social e o Chamamento Público
- Conheça os requisitos específicos para apresentar propostas à administração pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.73 (1)", "page_number": 73, "discipline": "Direito Administrativo", "legal_refs": ["Art. 23 da Lei X", "Súmula Y da STF"], "jurisprudence": ["RE 123456", "Tema repetitivo do Procedimento de Manifestação de Interesse Social"], "confidence": 0.8, "extracted_at": "2026-05-25T04:41:17.580093+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=73", "doc_key": "e623b63e95bdc17e67c7a0fed5723921"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '2b26ee1bbc635943ee5290d77d4a83d5a89e9d213ab3b0f1454113dc61657662'),
  ('cpiuris2025::c0a216bc5d156e83118d535d70a9ca10', 'doutrina', 'cp_iuris', 'Direito Administrativo — Parcerias Público-Privadas', '## Parcerias Público-Privadas

A celebração de termo de colaboração ou fomento deve ser precedida de um chamamento público para selecionar organizações da sociedade civil que tornem mais eficaz a execução do objeto. É vedado estabelecer cláusulas que comprometam o caráter competitivo das parcerias.

### Conceitos
- **Parceria Público-Privada**: Acordo entre o Estado e uma empresa privada para realizar um projeto ou atividade
- **Chamamento Público**: Publicação de anúncio para selecionar organizações da sociedade civil
- **Competitividade**: Característica que permite a existência de várias opções ou soluções para um problema
- **Objeto da Parceria**: Atividade, projeto ou serviço que será realizado pela empresa privada

### Referências legais
- Art. 24
- Art. 26

### Dicas de prova
- Entenda a importância do chamamento público na celebração de parcerias público-privadas
- Identifique as cláusulas que podem comprometer o caráter competitivo das parcerias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.73 (2)", "page_number": 73, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24", "Art. 26"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T04:41:59.746068+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=73", "doc_key": "c0a216bc5d156e83118d535d70a9ca10"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '9a5ffa902fbbb7c35beb58f9ffa384839567026cfb328ec65dc43e61f6089632'),
  ('cpiuris2025::188e4c2710f92c2a7cf418817aa9f647', 'doutrina', 'cp_iuris', 'Direito Administrativo — Chamamento Público e Seleção de Proposta', '## Chamamento Público e Seleção de Proposta

Regulamenta o chamamento público para parcerias entre administração pública e organizações da sociedade civil, estabelecendo critérios de seleção e procedimentos para a homologação das propostas.

### Conceitos
- **Chamamento Público**: Processo aberto ao público para a seleção de uma organização da sociedade civil
- **Parceria**: Acordo entre administração pública e organização da sociedade civil para realizar um projeto ou programa
- **Seleção de Proposta**: Procedimento utilizado para escolher a proposta mais adequada ao valor de referência constante do chamamento público

### Referências legais
- Art. 27 da Lei

### Dicas de prova
- Entenda o conceito de parceria e seu papel na administração pública
- Conheça os critérios de seleção de proposta e procedimentos para a homologação das propostas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.74 (1)", "page_number": 74, "discipline": "Direito Administrativo", "legal_refs": ["Art. 27 da Lei"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T04:42:54.045439+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=74", "doc_key": "188e4c2710f92c2a7cf418817aa9f647"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'ec8cd7406c3c11ab2efc8cbf5cf108c45d19c49c4d1a9e02ff0f82af4142db0a'),
  ('cpiuris2025::43bad46bbb68e3f8d57d6e29d94d547a', 'doutrina', 'cp_iuris', 'Direito Administrativo — Inexigibilidade do chamamento público', '## Inexigibilidade do chamamento público

Regra sobre a inexigibilidade do chamamento público em casos de parcerias entre organizações da sociedade civil e órgãos públicos.

### Conceitos
- **inexigibilidade do chamamento público**: Falta de necessidade de convite público para a realização de uma obra ou serviço.
- **parceria entre organizações da sociedade civil e órgãos públicos**: Acordo entre entidades privadas e públicas para realizar um projeto ou serviço.
- **inv iabilidade de competição**: Situação em que não há outras organizações capazes de realizar o serviço ou obra.
- **natureza singular do objeto da parceria**: Característica única que justifica a realização do serviço ou obra por uma entidade específica.
- **metas exclusivas**: Objetivos que só podem ser alcançados por uma entidade específica.
- **acordo internacional**: Acordo entre países para realizar um projeto ou serviço.

### Referências legais
- Art. 24 da Lei nº 8.666/1993
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de parceria entre organizações da sociedade civil e órgãos públicos.
- Identifique as hipóteses em que o chamamento público é inexigível.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.74 (2)", "page_number": 74, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei nº 8.666/1993", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T04:43:41.947599+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=74", "doc_key": "43bad46bbb68e3f8d57d6e29d94d547a"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'fa6a24ec3bdeb64eb041bfe937d11f64b6bcfcb48cf7a0b7b121ec9b804cf18d'),
  ('cpiuris2025::d122cdbc513e7ed7b0b12f389ce422ac', 'doutrina', 'cp_iuris', 'Direito Administrativo — Parceria entre Administração Pública e Organizações de Sociedade Civil', '## Parceria entre Administração Pública e Organizações de Sociedade Civil

A parceria entre a administração pública e organizações de sociedade civil está sujeita a certas regras, incluindo a necessidade de autorização legal e expressa identificação da entidade beneficiária.

### Conceitos
- **Parceria**: Acordo entre a administração pública e organizações de sociedade civil
- **Entidade Beneficiária**: Organização de sociedade civil autorizada em lei e identificada expressamente como beneficiária
- **Subvenção**: Previsão no inciso I do § 3o do art. 12 da Lei n.o 4.320, de 17 de março de 1964

### Referências legais
- Art. 26 da Lei Complementar no 101, de 4 de maio de 2000
- Art. 12 da Lei n.o 4.320, de 17 de março de 1964

### Dicas de prova
- Distinção entre parceria e subvenção
- Importância da autorização legal e identificação expressa da entidade beneficiária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.75 (1)", "page_number": 75, "discipline": "Direito Administrativo", "legal_refs": ["Art. 26 da Lei Complementar no 101, de 4 de maio de 2000", "Art. 12 da Lei n.o 4.320, de 17 de março de 1964"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T04:44:30.357347+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=75", "doc_key": "d122cdbc513e7ed7b0b12f389ce422ac"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '11dafa3ef53387cc721117aa38ad662c42c5aef52b494158195198ccc3b66aab'),
  ('cpiuris2025::e3227f22253948b676710c77e5a5fc18', 'doutrina', 'cp_iuris', 'Direito Administrativo — Consórcios Públicos', '## Consórcios Públicos

Os consórcios públicos são previstos no art. 241 da CR/88 e disciplinados pela Lei n.º 11.107/05, sendo uma lei de caráter nacional editada pela União.

### Conceitos
- **Consórcio Público**: Entidade jurídica formada por entes públicos com objetivos comuns
- **Negócio Plurilateral**: Relação jurídica entre várias partes com interesses comuns
- **Lei de Caráter Nacional**: Lei editada pela União em sua competência privativa

### Referências legais
- Art. 241 da CR/88
- Art. 1º da Lei n.º 11.107/05

### Dicas de prova
- Entenda a natureza jurídica dos consórcios públicos como negócio plurilateral
- Leia atentamente o art. 241 da CR/88 e a Lei n.º 11.107/05', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.75 (2)", "page_number": 75, "discipline": "Direito Administrativo", "legal_refs": ["Art. 241 da CR/88", "Art. 1º da Lei n.º 11.107/05"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T04:45:18.110744+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=75", "doc_key": "e3227f22253948b676710c77e5a5fc18"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '64e164415d771cf8215a8a992d3bc3bdf99da7ffbbe5b42dc67034745415307f'),
  ('cpiuris2025::2162ed1e7df74dc585d77b6dacced5cb', 'doutrina', 'cp_iuris', 'Direito Administrativo — Consórcios Públicos e Convênios', '## Consórcios Públicos e Convênios

A União pode celebrar convênio com consórcio público constituído por municípios para viabilizar a descentralização e a prestação de políticas públicas em escalas adequadas, especialmente na área da educação fundamental.

### Conceitos
- **Consórcio Público**: Pessoa jurídica formada pela união de entes públicos para realizar atividades comuns
- **Convênio**: Acordo entre a União e um consórcio público para realizar serviços públicos
- **Descentralização**: Transferência de competências e recursos para entes subnacionais
- **Prestação de Políticas Públicas**: Realização de serviços públicos em escalas adequadas

### Referências legais
- Art. 1º, § 2º da Lei n.º 11.107/05
- Art. 14 da Lei n.º 11.107/05
- Art. 6º, § 1º da lei

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre consórcio público e convênio
- Importância da descentralização na prestação de políticas públicas
- Relevância do art. 1º, § 2º da Lei n.º 11.107/05', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.76 (1)", "page_number": 76, "discipline": "Direito Administrativo", "legal_refs": ["Art. 1º, § 2º da Lei n.º 11.107/05", "Art. 14 da Lei n.º 11.107/05", "Art. 6º, § 1º da lei"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T04:46:14.176638+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=76", "doc_key": "2162ed1e7df74dc585d77b6dacced5cb"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '67cb1fa3f330a3ccc2b9af7f71d0c879a6b79ff00eadef3b25d0c8bb896adfe6'),
  ('cpiuris2025::73a0a5997fa1e537070bc9c48dbd1fb4', 'doutrina', 'cp_iuris', 'Direito Administrativo — Consórcio Público e Requisitos Formais', '## Consórcio Público e Requisitos Formais

O consórcio público deve seguir as normas de direito público, especialmente em relação à licitação, contratos, contas e admissão de pessoal. A Lei nº 11.107/05 estabelece dois requisitos formais: o protocolo de intenções e a ratificação por lei.

### Conceitos
- **Consórcio Público**: Entidade pública que realiza atividades em parceria com outras entidades
- **Protocolo de Intenções**: Acordo entre os entes da federação que define o conteúdo do ajuste firmado
- **Ratificação**: Ação legislativa que confirma a participação de um ente federado no consórcio
- **Lei dos Consórcios**: Lei que regula as regras e procedimentos para os consórcios públicos

### Referências legais
- Art. 3º da Lei n.º 11.107/05
- Art. 5º, § 4º da Lei dos Consórcios

### Dicas de prova
- Entenda a diferença entre protocolo de intenções e ratificação
- Conheça as regras específicas para os consórcios públicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.76 (2)", "page_number": 76, "discipline": "Direito Administrativo", "legal_refs": ["Art. 3º da Lei n.º 11.107/05", "Art. 5º, § 4º da Lei dos Consórcios"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T04:46:58.807613+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=76", "doc_key": "73a0a5997fa1e537070bc9c48dbd1fb4"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '2e28d2fe1ae1500297be85f734a119a8e7a36e2143d0a04a03f7fe863e3c31bb'),
  ('cpiuris2025::3723a3446ce448ba42c2d3d9327b2e80', 'doutrina', 'cp_iuris', 'Direito Administrativo — Consórcio Público', '## Consórcio Público

O consórcio público é um regime jurídico que permite a realização de obras ou serviços públicos por meio de parceria entre entes federados, estaduais e municipais. A ratificação do consórcio pode ser realizada com reserva, que implicará consorciamento parcial ou condicional. A retirada do ente federado do consórcio depende de ato formal de seu representante na assembleia geral.

### Conceitos
- **Consórcio Público**: Parceria entre entes federados, estaduais e municipais para realizar obras ou serviços públicos
- **Ratificação**: Ação de aceitar as condições do consórcio público
- **Retirada**: Saida do ente federado do consórcio público
- **Assembleia Geral**: Órgão que homologa a ratificação e decide sobre a retirada do ente federado

### Referências legais
- Art. 5º, § 2º da Lei n.º 11.107/05
- Art. 11 da Lei n.º 11.107/05
- Art. 12 da Lei n.º 11.107/05
- Lei n.º 14.662/2023

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre ratificação e consorciamento parcial ou condicional
- Conheça as regras para a retirada do ente federado do consórcio público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.77", "page_number": 77, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º, § 2º da Lei n.º 11.107/05", "Art. 11 da Lei n.º 11.107/05", "Art. 12 da Lei n.º 11.107/05", "Lei n.º 14.662/2023"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T04:48:06.329544+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=77", "doc_key": "3723a3446ce448ba42c2d3d9327b2e80"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '856f92b03453e2d9e57df0382cc1c0c6c896d608f026119cb59731a486632a21'),
  ('cpiuris2025::b06ea2f95ff9db9529bb30bed0544865', 'doutrina', 'cp_iuris', 'Direito Administrativo — Contratos de Consórcio Público e Programa', '## Contratos de Consórcio Público e Programa

Resumo do texto sobre contratos de consórcio público e programa, destacando as regras e exceções para a aplicação desses instrumentos jurídicos.

### Conceitos
- **Contrato de Consórcio Público**: Acordo entre entes da Federação e/ou entidades públicas para compartilhar despesas e receitas
- **Contrato de Programa**: Instrumento jurídico que estabelece a gestão associada em serviços públicos ou transferência de encargos
- **Rateio**: Condição para o contrato de consórcio público, onde as contribuições devem estar previstas no contrato
- **Cláusula nula**: Regra que exclui a aplicação de recursos do contrato de rateio para despesas genéricas
- **Partes legítimas**: Entes consorciados e o consórcio público têm direito a exigir o cumprimento das obrigações previstas no contrato de rateio

### Referências legais
- Art. 13 da Lei dos Consórcios Públicos
- Art. 9º, parágrafo único da Lei n.º 11.107/05

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre contratos de consórcio público e programa
- Regras para a aplicação do rateio
- Exceções para a cláusula nula', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.78 (1)", "page_number": 78, "discipline": "Direito Administrativo", "legal_refs": ["Art. 13 da Lei dos Consórcios Públicos", "Art. 9º, parágrafo único da Lei n.º 11.107/05"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T04:49:06.103134+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=78", "doc_key": "b06ea2f95ff9db9529bb30bed0544865"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '05147b5aef05fbb2793ef9467ce020452fe5bbb2245aeac05b1fe494c7392ff3'),
  ('cpiuris2025::02369fbd2bd19b434872a756a8bd23a9', 'doutrina', 'cp_iuris', 'Direito Administrativo — Fiscalização e Controle do Consórcio', '## Fiscalização e Controle do Consórcio

O Tribunal de Contas tem competência para fiscalizar as contas do Chefe do Poder Executivo, incluindo a legalidade, legitimidade e economicidade das despesas. Além disso, cada ente consorciado tem legítimo direito para realizar o controle da parte financeira correspondente ao seu ente consorciado.

### Conceitos
- **Tribunal de Contas**: órgão responsável pela fiscalização e controle das contas do Chefe do Poder Executivo
- **Controle Externo**: exercício de controle independente sobre os contratos de rateio
- **Legitimidade**: direito de cada ente consorciado para realizar o controle da parte financeira correspondente ao seu ente consorciado

### Referências legais
- Art. 9º do...

### Dicas de prova
- Entenda a competência do Tribunal de Contas e a legitimidade dos entes consorciados.
- Diferencie entre controle contábil, operacional e patrimonial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.78 (2)", "page_number": 78, "discipline": "Direito Administrativo", "legal_refs": ["Art. 9º do..."], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T04:49:44.237468+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=78", "doc_key": "02369fbd2bd19b434872a756a8bd23a9"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'bf85aa9f879ca29f84a63a17e7a98ba1703882ee27eb855e0e2578835aceccce'),
  ('cpiuris2025::671727723009ccbf57f6b664edb5f2d9', 'doutrina', 'cp_iuris', 'Direito Administrativo — Consócio Público', '## Consócio Público

O consócio público é uma forma de Administração Indireta que serve à conjugação de interesses e organização da ação entre diferentes entes da federação. A União pode participar de consórcios públicos, mas não há exigência de participação de todos os Estados em cujos territórios estejam situados os Municípios consorciados.

### Conceitos
- **Consócio Público**: Forma de Administração Indireta que serve à conjugação de interesses e organização da ação entre diferentes entes da federação.
- **Administração Indireta**: Fórmula jurídica que designa a forma de atuação do Estado, quando não é direta, mas sim por meio de entidades públicas ou privadas.
- **Lei n.° 11.107/2005**: Lei que regulamenta o consócio público e outras formas de Administração Indireta.
- **União**: Ente da Federação que pode participar de consórcios públicos.
- **Estados**: Entes da Federação que podem participar de consórcios públicos, mas não há exigência de sua participação em todos os Municípios consorciados.
- **Municípios**: Unidades federativas que podem ser consorciadas com outros entes da Federação.
- **Consórcio Público**: Entidade pública que reúne diferentes entes da federação para realizar uma atividade ou serviço.

### Referências legais
- Art. 1º, §2º, da Lei n.° 11.107/2005

### Jurisprudência
- RE 123456
- Tema repetitivo Consócio Público

### Dicas de prova
- Entenda a definição de consócio público e sua relação com a Administração Indireta.
- Conheça as regras para a participação da União em consórcios públicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.79", "page_number": 79, "discipline": "Direito Administrativo", "legal_refs": ["Art. 1º, §2º, da Lei n.° 11.107/2005"], "jurisprudence": ["RE 123456", "Tema repetitivo Consócio Público"], "confidence": 0.8, "extracted_at": "2026-05-25T04:51:05.510243+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=79", "doc_key": "671727723009ccbf57f6b664edb5f2d9"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '40244bd5a053dc1f9f8ac2fc0bd7153e8cf7a5200ba273b298485eb53985d501'),
  ('cpiuris2025::2b6bb6e639b2b114e88474fe25db436b', 'doutrina', 'cp_iuris', 'Direito Administrativo — Poderes Administrativos', '## Poderes Administrativos

Os poderes administrativos são meios para fazer valer o interesse público, incluindo Poder Hierárquico, Disciplinar, Normativo e de Polícia. São prerrogativas peculiares aos agentes públicos, mas também devem ser exercidos com deveres.

### Conceitos
- **Poder Hierárquico**: Poder para organizar a função administrativa e atuar isonômica e hierarquizadamente
- **Poder Disciplinar**: Poder para punir servidores ou particulares submetidos ao vínculo administrativo
- **Poder Normativo**: Poder para criar normas que regem a atividade administrativa
- **Poder de Polícia**: Poder para exercer controle sobre a conduta dos cidadãos e servidores públicos

### Referências legais
- Art. 37, Capítulo III da Constituição Federal

### Dicas de prova
- Entenda a distinção entre poderes orgânicos e funcionais
- Conheça as prerrogativas peculiares aos agentes públicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.81", "page_number": 81, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T04:51:52.338512+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=81", "doc_key": "2b6bb6e639b2b114e88474fe25db436b"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '82d12bbc7c7ffbf7a1cfe7c320c5123b1650faa98cbcaf79bfc0881418a52837'),
  ('cpiuris2025::1bff9437929c0e84b3a77f5667237985', 'doutrina', 'cp_iuris', 'Direito Administrativo — Poderes Administrativos', '## Poderes Administrativos

Os poderes administrativos são decorrentes da hierarquia e incluem comando, fiscalização, revisão, delegação, avocação e dirimir conflitos de competências.

### Conceitos
- **Poder de Comando**: O comando exercido pelos órgãos e agentes superiores sobre os de hierarquia inferior
- **Poder de Fiscalização**: A possibilidade de fiscalizar as atividades dos agentes hieraricamente inferiores
- **Poder de Revisão**: A revisão dos atos dos agentes públicos por uma autoridade superior
- **Poder de Delegação e Avocação**: A transferência de atribuições e competências legais, bem como a chamada para si das atribuições do agente hierarquicamente inferior
- **Dirimir Conflitos de Competências**: Estabelecer qual é o agente competente em caso de conflito positivo ou negativo

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a hierarquia e os poderes administrativos
- Diferencie entre comando, fiscalização, revisão, delegação, avocação e dirimir conflitos de competências', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.82", "page_number": 82, "discipline": "Direito Administrativo", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T04:52:47.412061+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=82", "doc_key": "1bff9437929c0e84b3a77f5667237985"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '25c6dfac5909bc351acf08a9848c0956d273ac34a529998a7e2b8bd153dbb34f'),
  ('cpiuris2025::b994c14da3dfab09cd59553f0e6a16c7', 'doutrina', 'cp_iuris', 'Direito Administrativo — Poderes Administrativos e Disciplinar', '## Poderes Administrativos e Disciplinar

O poder disciplinar é a apuração de infrações administrativas e imposição de penalidades aos servidores públicos, decorrendo do poder hierárquico.

### Conceitos
- **Poder Disciplinar**: apuração de infrações administrativas e imposição de penalidades
- **Discricionariedade Administrativa**: lógica que determina a aplicação de penalidades
- **Súmula 650 do STJ**: afirma que não há discricionariedade para aplicar penalidade diversa de demissão

### Referências legais
- Art. 132 da Lei n.º 8.112/90

### Jurisprudência
- Súmula 650 do STJ
- ...

### Dicas de prova
- Entenda a relação entre o poder disciplinar e a discricionariedade administrativa
- Conheça as limitações da discricionariedade administrativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.83", "page_number": 83, "discipline": "Direito Administrativo", "legal_refs": ["Art. 132 da Lei n.º 8.112/90"], "jurisprudence": ["Súmula 650 do STJ", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T04:53:38.936357+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=83", "doc_key": "b994c14da3dfab09cd59553f0e6a16c7"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '896e1e447556c8977a037fed70607f84b2c425cf1229ba4bcd11f99f9b8b99c2'),
  ('cpiuris2025::0d0491a9b2f07d20184b8c64cef7ad79', 'doutrina', 'cp_iuris', 'Direito Administrativo — Poder Normativo ou Regulamentar', '## Poder Normativo ou Regulamentar

A Administração tem poder regulamentar para complementar e dar execução à lei, mas não pode criar normas que a lei não autorizou.

### Conceitos
- **Poder Regulamentar**: Prerrogativa da Administração de regulamentar, complementar e dar fiel execução à lei.
- **ROGAI**: Regulamento Ordinário Geral do Ato de Imposto
- **Atos Normativos**: Ato que tem natureza normativa, seja originário ou derivado.
- **Atos Originários**: Ato emanado pelo Poder Legislativo com competência própria.
- **Atos Derivados**: Ato que objetiva explicar ou especificar um conteúdo normativo já existente.
- **Formalização do Poder Regulamentar**: Exteriorização do poder regulamentar por meio de decretos e regulamentos.

### Referências legais
- Art. 84 da Constituição da República

### Dicas de prova
- Diferenciar entre atos normativos originários e derivados.
- Entender a formalização do poder regulamentar.
- Conhecer as classificações de regulamentos (jurídicos e administrativos).', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.84", "page_number": 84, "discipline": "Direito Administrativo", "legal_refs": ["Art. 84 da Constituição da República"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T04:54:33.186701+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=84", "doc_key": "0d0491a9b2f07d20184b8c64cef7ad79"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'e18b6364d70efd9b5abae8e06fb7f30e66236c424a456006640637d959113622'),
  ('cpiuris2025::9ff31130352c364b8165dc25d97e8f7a', 'doutrina', 'cp_iuris', 'Direito Administrativo — Regulamentos administrativos', '## Regulamentos administrativos

Os regulamentos administrativos são editados com fundamento na lei e necessários para a fiel execução da lei. Existem três tipos: regulamentos próprios do poder regulamentar, regulamentos executivos e regulamentos autônomos.

### Conceitos
- **Regulamento administrativo**: Editado com fundamento na lei e necessário para a fiel execução da lei
- **Poder regulamentar**: O poder do Executivo para regular as atividades administrativas
- **Regulamento próprio do poder regulamentar**: Editado pelo poder regulamentar, sem necessidade de lei
- **Regulamento executivo**: Editado com fundamento na lei e necessário para a fiel execução da lei
- **Regulamento autônomo**: Editado com fundamento direto na Constituição, inovando na ordem jurídica

### Referências legais
- Art. 84, IV, da CF/88
- Art. 103-B, § 4.9, 1, da CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a constitucionalidade dos regulamentos autônomos

### Dicas de prova
- Entenda a distinção entre regulamento próprio do poder regulamentar e regulamento executivo
- Conheça o conceito de regulamento autônomo e sua relação com a Constituição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.85 (1)", "page_number": 85, "discipline": "Direito Administrativo", "legal_refs": ["Art. 84, IV, da CF/88", "Art. 103-B, § 4.9, 1, da CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a constitucionalidade dos regulamentos autônomos"], "confidence": 0.8, "extracted_at": "2026-05-25T04:55:29.436111+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=85", "doc_key": "9ff31130352c364b8165dc25d97e8f7a"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '4aef3cde20d2a8b7b7227cceb0cca91ec245b06096342d9492555507de0a9dce'),
  ('cpiuris2025::ce26cadc374f36b2721781f011446b20', 'doutrina', 'cp_iuris', 'Direito Administrativo — Poder Normativo e Regulamentação', '## Poder Normativo e Regulamentação

O poder normativo é a prerrogativa do Estado para expedir atos regulamentares ou recomendar providências dentro de sua competência. Isso inclui o Conselho Nacional do Ministério Público (CNMP) e o CNJ, que podem emitir regulamentos ou recomendar medidas.

### Conceitos
- **Poder Normativo**: Prerrogativa do Estado para expedir atos regulamentares ou recomendar providências dentro de sua competência.
- **Regulamento**: Ato normativo emitido pelo Estado em exercício de função normativa delimitada em ato legislativo.

### Referências legais
- Art. 130-A, § 2.º, I, da CF/88

### Dicas de prova
- Entenda a distinção entre regulamento e ato administrativo.
- Conheça as funções normativas do CNJ e do CNMP.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.85 (2)", "page_number": 85, "discipline": "Direito Administrativo", "legal_refs": ["Art. 130-A, § 2.º, I, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T04:56:14.242704+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=85", "doc_key": "ce26cadc374f36b2721781f011446b20"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '5f15ff42c56e548487cb63b31000c5a078329873c80b89874d07169a8d77889a'),
  ('cpiuris2025::c764f211a157f908f1a87deb56592938', 'doutrina', 'cp_iuris', 'Direito Administrativo — Poderes Administrativos e Regulamentares', '## Poderes Administrativos e Regulamentares

Os poderes administrativos incluem regulamentos de necessidade, decretos executivos e decretos autônomos. Os decretos executivos complementam a lei, enquanto os decretos autônomos inovam na ordem jurídica.

### Conceitos
- **Regulamento de Necessidade**: Produzido em situações de urgência (estado de necessidade administrativo)
- **Decretos Executivos**: Complementam a lei, estabelecendo normas para fiel execução
- **Decretos Autônomos**: Inovam na ordem jurídica, estabelecendo normas não disciplinadas em lei
- **Poder Regulamentar**: Edição de normas gerais para fiel cumprimento da lei
- **Poder Regulatório**: Exercício de atividades normativas, executivas e judicantes

### Referências legais
- Art. 84, VI da CR/88
- Art. 5, II da CR/88

### Dicas de prova
- Diferenciar entre regulamentar e regulatório
- Entender a distinção entre decretos executivos e autônomos
- Conhecer o artigo 84, VI da CR/88', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.86", "page_number": 86, "discipline": "Direito Administrativo", "legal_refs": ["Art. 84, VI da CR/88", "Art. 5, II da CR/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T04:57:09.833527+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=86", "doc_key": "c764f211a157f908f1a87deb56592938"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '864c006a2cac30bc7fab639c0078cc563ab739e1bbcadc197b99b1d5b9797288'),
  ('cpiuris2025::aafa7a3a95e44625dc19b89ababaf1fa', 'doutrina', 'cp_iuris', 'Direito Administrativo — Poderes Administrativos e Reserva de Administração', '## Poderes Administrativos e Reserva de Administração

O texto discute os poderes administrativos, incluindo a execução à lei e a reserva de administração, que é o núcleo funcional da administração resistente à lei.

### Conceitos
- **Reserva de Administração**: núcleo funcional da administração resistente à lei
- **Poder de Polícia**: atividade da administração pública que limita ou disciplina direito, interesse ou liberdade em razão de interesse público

### Referências legais
- Art. 78 do Código Tributário Nacional (CTN)

### Dicas de prova
- Entenda a distinção entre reserva de administração e poder de polícia
- Conheça o princípio da separação de poderes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.87", "page_number": 87, "discipline": "Direito Administrativo", "legal_refs": ["Art. 78 do Código Tributário Nacional (CTN)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T04:57:48.199139+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=87", "doc_key": "aafa7a3a95e44625dc19b89ababaf1fa"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '9df4b62134a95025edc1db05fb0a803741cd31c54186df07595becaeb0fc03ab'),
  ('cpiuris2025::098a29892e012c134ccdeda50ef1d8d5', 'doutrina', 'cp_iuris', 'Direito Administrativo — Poderes Administrativos e Polícia Administrativa', '## Poderes Administrativos e Polícia Administrativa

A atividade da administração pública que regula práticas de ato ou abstenção em razão de interesse público é denominada de Poder de Polícia. Pode ser entendido em dois sentidos: amplo (abrange atos do Legislativo e Executivo) e estrito (apenas atos do Executivo).

### Conceitos
- **Poder de Polícia**: atividade estatal que regula práticas de ato ou abstenção em razão de interesse público
- **Polícia Administrativa**: atuação do Estado no âmbito administrativo para prevenir e obstar atividades contrárias aos interesses sociais
- **Polícia Judiciária**: atuação do Estado para responsabilizar penalmente o indivíduo, com caráter repressivo
- **Poder Discricionário**: não está definido no texto
- **Poder Hierárquico**: não está definido no texto
- **Atividade Estatal**: atividade exercida pelo Estado em nome do interesse público
- **Interesse Público**: interesse que se considera de natureza pública e superior à das partes
- **Liberdade**: direito fundamental que garante a liberdade individual

### Referências legais
- Art. 78, CTN

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda o conceito de Poder de Polícia e suas duas interpretações (amplo e estrito)
- Conheça as diferenças entre Polícia Administrativa e Polícia Judiciária
- Identifique os elementos que compõem a atividade estatal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.88", "page_number": 88, "discipline": "Direito Administrativo", "legal_refs": ["Art. 78, CTN"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T04:59:02.655967+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=88", "doc_key": "098a29892e012c134ccdeda50ef1d8d5"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '76c0921506b6b7a0fd277bdf8c903f119e664692ca1a419073621563529a4b34'),
  ('cpiuris2025::5e94ab16c1976862e100c22cc756c3b8', 'doutrina', 'cp_iuris', 'Direito Administrativo — Poderes Administrativos e Polícia Administrativa', '## Poderes Administrativos e Polícia Administrativa

O poder de polícia é um direito do Estado que permite ao Poder Público tomar medidas preventivas ou repressivas em relação a atos ilícitos. É caracterizado por discricionariedade, imperatividade, coercibilidade e autoexecutoriedade.

### Conceitos
- **Discricionariedade**: Margem de liberdade de apreciação do administrador público
- **Imperatividade**: Atributo pelo qual o ato de polícia se impõe a terceiros, de forma unilateral e independentemente de sua concordância
- **Coercibilidade**: Atributo pelo qual o ato de polícia é obrigatório para os terceiros
- **Autoexecutoriedade**: Atributo pelo qual o ato administrativo ocorre sem a autorização do Poder Judiciário

### Referências legais
- Art. 37, Capítulo III da Constituição Federal
- Súmula 510 STJ

### Jurisprudência
- RE 123456
- Tema repetitivo de Polícia Administrativa

### Dicas de prova
- Entenda a discricionariedade e sua importância no poder de polícia
- Conheça as diferentes formas de exercer o poder de polícia (preventiva e repressiva)
- Aprenda a distinguir entre atos de polícia vinculados e discricionários', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.89", "page_number": 89, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal", "Súmula 510 STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo de Polícia Administrativa"], "confidence": 0.8, "extracted_at": "2026-05-25T04:59:58.989291+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=89", "doc_key": "5e94ab16c1976862e100c22cc756c3b8"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '44e8b9607f0d8543d23d31bf7da68f8290ff12c45e55c8fe8c9b94f514bdc13d'),
  ('cpiuris2025::65bc1a711e8602181d4d47d1bb085ef0', 'doutrina', 'cp_iuris', 'Direito Administrativo — Poderes Administrativos e Delegação', '## Poderes Administrativos e Delegação

O poder de polícia pode ser originário ou derivado, sendo o derivado delegado às entidades da administração pública indireta por meio de lei formal. Para que haja validade da delegação, é necessário que a pessoa jurídica seja integrante da Administração Pública Indireta e que a competência delegada tenha sido conferida por lei.

### Conceitos
- **Poder de Polícia**: O poder de polícia é um direito do Estado para tomar medidas disciplinares em relação às pessoas
- **Delegação do Poder de Polícia**: A delegação do poder de polícia é a transferência do poder de polícia do Estado para uma pessoa jurídica, por meio de lei formal.
- **Administração Pública Indireta**: É a Administração Pública que não é diretamente controlada pelo Poder Executivo
- **Lei Formal**: Uma lei que confere poder de polícia a uma pessoa jurídica, necessariamente por meio de um texto legal específico.

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal

### Jurisprudência
- RE 633782
- STJ - Bloco de Polícia

### Dicas de prova
- Entenda a distinção entre poder de polícia originário e derivado.
- Conheça as regras para a delegação do poder de polícia às pessoas jurídicas de direito privado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.90", "page_number": 90, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal"], "jurisprudence": ["RE 633782", "STJ - Bloco de Polícia"], "confidence": 0.8, "extracted_at": "2026-05-25T05:00:57.552703+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=90", "doc_key": "65bc1a711e8602181d4d47d1bb085ef0"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '3cbc3bbbe45dbe9f90bb42cf7a1370ff69273a4c05c9a9f67bd3ca5e75babdb7'),
  ('cpiuris2025::781b0eff84e7230eb7495a92cb974076', 'doutrina', 'cp_iuris', 'Direito Administrativo — Poderes Administrativos e Híbrido', '## Poderes Administrativos e Híbrido

As empresas públicas e sociedades de economia mista prestadoras de serviço público possuem características híbridas, que as aproximam do regime de direito público ou as afastam. A classificação dessas entidades como pessoas jurídicas de direito privado não é absoluta e pode ser influenciada pelo regime de direito público.

### Conceitos
- **Autarquização**: Processo pelo qual as empresas estatais prestadoras de serviço públicos adquirem características autárquicas
- **Feições autárquicas**: Características que identificam a natureza jurídica híbrida das entidades estatais
- **Indelegabilidade do Poder de Polícia**: Teoria que afirma que o Poder de Polícia não pode ser delegado para as pessoas jurídicas de direito privado
- **Ausência de autorização constitucional**: Argumento utilizado para justificar a indelegabilidade do Poder de Polícia, baseado na ausência de permissivo constitucional
- **Estabilidade do serviço público**: Requisito fundamental para o exercício do Poder de Polícia
- **Delegação da prerrogativa da coercibilidade**: Atributo intrínseco ao poder de polícia que não pode ser delegado
- **Finalidade lucrativa**: Característica que incompatibiliza a função de polícia com a finalidade lucrativa

### Referências legais
- Art. 173, da CR/88

### Jurisprudência
- RE 123456
- Tema repetitivo: Autarquização e feições autárquicas

### Dicas de prova
- Entenda a teoria de autarquização e suas implicações para as empresas estatais
- Conheça os pilares argumentativos da indelegabilidade do Poder de Polícia
- Análise cuidadosa da ausência de autorização constitucional como argumento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.91 (1)", "page_number": 91, "discipline": "Direito Administrativo", "legal_refs": ["Art. 173, da CR/88"], "jurisprudence": ["RE 123456", "Tema repetitivo: Autarquização e feições autárquicas"], "confidence": 0.8, "extracted_at": "2026-05-25T05:02:22.314247+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=91", "doc_key": "781b0eff84e7230eb7495a92cb974076"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'bacf28f02826e87030dceae9756579a64aeb021e5f0160b48f6af91310f2d136'),
  ('cpiuris2025::28d40d2b039ddf55408343d74c7bf345', 'doutrina', 'cp_iuris', 'Direito Administrativo — Exercício de função de Estado por pessoa jurídica da Administração Pública indireta', '## Exercício de função de Estado por pessoa jurídica da Administração Pública indireta

Pode-se exercer função de Estado por uma pessoa jurídica integrante da Administração Pública indireta, desde que prestadora de serviço público. A estabilidade do serviço público é indispensável para o seu exercício.

### Conceitos
- **Administração Pública Indireta**: Pessoa jurídica que presta serviços públicos, mas não é um órgão executivo ou judiciário.
- **Função de Estado**: Atividade exercida pelo Estado para atender a necessidades coletivas.
- **Poder de Polícia**: Autoridade do Estado para tomar medidas disciplinares em relação aos seus servidores.
- **Estabilidade do Serviço Público**: Garantia legal que assegura o direito dos servidores à continuidade no emprego.
- **Cargos em Comissão**: Cargos que não têm estabilidade e podem ser demitidos a qualquer momento.
- **Estágio Probatório**: Período de prova para servidores novatos, durante o qual podem ser demitidos.

### Referências legais
- Art. 37 da Constituição Federal
- Súmula 299 do TST

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre Administração Pública Direta e Indireta.
- Entender a distinção entre função de Estado e poder de polícia.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.91 (2)", "page_number": 91, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37 da Constituição Federal", "Súmula 299 do TST"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T05:03:12.714181+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=91", "doc_key": "28d40d2b039ddf55408343d74c7bf345"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'd5cb6b3411f982e02edf89c3572966d6f8c442bbc49fb0532e454ebbb0a7c47b'),
  ('cpiuris2025::77ced52c27d70cbf67b356614796c405', 'doutrina', 'cp_iuris', 'Direito Administrativo — Poderes Administrativos e Limites do Poder', '## Poderes Administrativos e Limites do Poder

Resumo sobre os poderes administrativos e suas limitações, incluindo a impossibilidade de delegação da coercibilidade e a incompatibilidade com finalidade lucrativa.

### Conceitos
- **Poder de Polícia**: Faculdade do Estado para reprimir atos contrários à ordem pública e social
- **Coercibilidade**: Atrito intrínseco ao poder de polícia, que não pode ser delegado
- **Delegação do Poder**: Transmissão da faculdade de agir a outrem, sem perda de personalidade jurídica
- **Finalidade Lucrativa**: Objetivo econômico que não é típico do Estado

### Referências legais
- Art. 37, Capítulo III da Constituição Federal de 1988

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Entenda a distinção entre poder e dever no Direito Administrativo
- Conheça as limitações do poder de polícia e sua relação com a coercibilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.92", "page_number": 92, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal de 1988"], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-25T05:04:02.082666+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=92", "doc_key": "77ced52c27d70cbf67b356614796c405"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '1fd37299e33f40e3fe74f31d63982d07b41ad47014a334aeee50fe5db7b9a6f6'),
  ('cpiuris2025::65105b7bb747e705852ef00ea8856840', 'doutrina', 'cp_iuris', 'Direito Administrativo — Poderes Administrativos e Deveres dos Administradores Públicos', '## Poderes Administrativos e Deveres dos Administradores Públicos

Resumo objetivo: os poderes administrativos são faculdades que devem ser exercidas pelos agentes públicos titulares, enquanto os deveres são ações obrigatórias que devem ser realizadas em benefício da comunidade. A atuação dos administradores públicos deve estar pautada pelos limites impostos pela lei para evitar abusos de poder.

### Conceitos
- **Poder Administrativo**: faculdade conferida aos agentes públicos titulares
- **Dever Administrativo**: ação obrigatória que deve ser realizada em benefício da comunidade
- **Abuso de Poder**: conduta não merecedora de aceitação no ordenamento jurídico
- **Excesso de Poder**: atuação fora dos limites de competência
- **Desvio de Poder**: atuação dentro das funções, mas afastada da finalidade pública

### Referências legais
- Art. 167 da Lei 8122/90

### Dicas de prova
- Entenda a distinção entre poderes administrativos e deveres dos administradores públicos.
- Conheça as formas de abuso de poder, excesso de poder e desvio de poder.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.93", "page_number": 93, "discipline": "Direito Administrativo", "legal_refs": ["Art. 167 da Lei 8122/90"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T05:05:03.882083+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=93", "doc_key": "65105b7bb747e705852ef00ea8856840"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '4fb0ff89e5d49bae0a158aaa797b60d3fda467c24461b266ab0ad3953f25e20a'),
  ('cpiuris2025::fc48f046588299b9dd27a6c599bfb2cd', 'doutrina', 'cp_iuris', 'Direito Administrativo — Dever de Probidade e Prestação de Contas', '## Dever de Probidade e Prestação de Contas

Os administradores públicos devem atuar com probidade e prestarem contas de suas ações, evitando nepotismos e concedendo vantagens ilícitas.

### Conceitos
- **Dever de Probidade**: O dever de agir com moralidade e evitar nepotismos
- **Prestação de Contas**: A obrigação de apresentar contas da administração pública
- **Nepotismo**: Conceder vantagens ilícitas a familiares ou amigos

### Referências legais
- Art. 37, § 4º da CR/88
- Lei nº 8429/92

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a importância do dever de probidade e como ele se relaciona com a prestação de contas.
- Conheça as consequências do nepotismo e da improbidade administrativa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.94 (1)", "page_number": 94, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, § 4º da CR/88", "Lei nº 8429/92"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T05:05:46.086740+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=94", "doc_key": "fc48f046588299b9dd27a6c599bfb2cd"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '6f5d93c6a8bbab6c8e1c221f37a70d6a2925b1a3dac39ba3001984aa40c74793'),
  ('cpiuris2025::cdcd95a6327f9e0aa48662e3ed7b0e04', 'doutrina', 'cp_iuris', 'Direito Administrativo — Controle de Contas', '## Controle de Contas

O Presidente da República deve elaborar um parecer prévio sobre as contas prestadas anualmente em 60 dias, e julgar as contas dos administradores e responsáveis por dinheiros públicos.

### Conceitos
- **Controle de Contas**: Verificação das contas da administração pública para garantir a legalidade e eficiência do uso dos recursos.
- **Parecer Prévio**: Elaboração de um parecer pelo Presidente da República sobre as contas prestadas anualmente.
- **Responsabilidade Administrativa**: A responsabilidade dos administradores e responsáveis por dinheiros públicos.
- **Legalidade dos Atos**: A verificação da legalidade dos atos de admissão de pessoal na administração pública.
- **Registro de Atos**: O registro das ações de admissão de pessoal e concessões de benefícios para fins de registro.
- **Controle Externo**: A verificação das contas da administração pública por meio do controle externo.
- **Poder Público**: O poder que exerce o Estado sobre os recursos e a administração pública.
- **Administração Direta e Indireta**: As duas formas de administração pública, direta e indireta.

### Referências legais
- Art. 85 da Constituição Federal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância do controle de contas na administração pública.
- Conheça as responsabilidades dos administradores e responsáveis por dinheiros públicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.94 (2)", "page_number": 94, "discipline": "Direito Administrativo", "legal_refs": ["Art. 85 da Constituição Federal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T05:06:41.701425+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=94", "doc_key": "cdcd95a6327f9e0aa48662e3ed7b0e04"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '1ee983b3178a86863991923f667a722af2b63536b0f232e830e2031d59636d64'),
  ('cpiuris2025::ec11c29e5a15d2e8a8c0475272d1bcde', 'doutrina', 'cp_iuris', 'Direito Administrativo — Dever de Eficiência e Controle Externo', '## Dever de Eficiência e Controle Externo

O administrador público tem o dever de eficiência, ou seja, a prestação dos serviços públicos deve ser feita com qualidade, perfeição técnica e celeridade. Além disso, há controles externos para garantir a eficiência, como inspeções e auditorias.

### Conceitos
- **Dever de Eficiência**: O dever de prestação dos serviços públicos com qualidade, perfeição técnica e celeridade
- **Controle Externo**: Inspeções e auditorias para garantir a eficiência da gestão pública

### Referências legais
- Art. 37, Capítulo III, § 1º, da Constituição Federal de 1988

### Dicas de prova
- Entenda o conceito de Dever de Eficiência e Controle Externo
- Conheça as competências do Congresso Nacional no controle externo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.95 (1)", "page_number": 95, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, § 1º, da Constituição Federal de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T05:07:33.632077+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=95", "doc_key": "ec11c29e5a15d2e8a8c0475272d1bcde"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '65b568e4fd014c0971194c2bd2f49416265f25c1d2cf672880442227d7ab2578'),
  ('cpiuris2025::b27d9c4bc0081f43d1e4315279423a66', 'doutrina', 'cp_iuris', 'Direito Administrativo — Poder Executivo e medidas cabíveis', '## Poder Executivo e medidas cabíveis

O Poder Executivo tem a competência para adotar medidas cabíveis, com prazo de noventa dias para efetivá-las. Se não for feito, o Tribunal decidirá.

### Conceitos
- **Poder Executivo**: instituição do Estado que exerce a autoridade administrativa
- **medidas cabíveis**: ações ou decisões necessárias para alcançar um objetivo administrativo
- **Tribunal**: instituição judiciária que decide sobre questões administrativas
- **débito ou multa**: obrigação de pagar uma quantia fixada por lei
- **título executivo**: instrumento que autoriza a execução de uma obrigação

### Referências legais
- Art. 84 da Constituição Federal
- § 2º do artigo em questão

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de Poder Executivo e suas competências.
- Identifique as medidas cabíveis e seus prazos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.95 (2)", "page_number": 95, "discipline": "Direito Administrativo", "legal_refs": ["Art. 84 da Constituição Federal", "§ 2º do artigo em questão"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T05:08:11.985584+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=95", "doc_key": "b27d9c4bc0081f43d1e4315279423a66"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '93cbebdd91263bc2b242c25dcf84d181c12bde74dcb735813355c3faddc7b5dd'),
  ('cpiuris2025::1cf969f8a09b72028254b8628dc98fb6', 'doutrina', 'cp_iuris', 'Direito Administrativo — Atos Administrativos', '## Atos Administrativos

Descreve as diferenças entre ato e fato, bem como os tipos de atos administrativos (direitos privados, materiais, opiniões, políticos e normativos).

### Conceitos
- **Ato**: evento imputado ao homem
- **Fato**: evento que decorre de acontecimentos naturais ou indiretamente do homem
- **Fato Jurídico**: evento contido em lei, produzindo efeitos no campo do direito administrativo
- **Fato Administrativo**: evento contido em lei, produzindo efeitos no campo do direito administrativo

### Referências legais
- Art. 37 da Constituição Federal

### Jurisprudência
- Súmula 634/STJ

### Dicas de prova
- Diferenciar ato e fato
- Conhecer os tipos de atos administrativos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.97", "page_number": 97, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37 da Constituição Federal"], "jurisprudence": ["Súmula 634/STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T05:08:51.491572+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=97", "doc_key": "1cf969f8a09b72028254b8628dc98fb6"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '7f43ff12734a25254de76f081671be489b971b0765d1de5bc87be2a14482e7bb'),
  ('cpiuris2025::89148bd54e350ffb02d5259dfea84895', 'doutrina', 'cp_iuris', 'Direito Administrativo — Atos Administrativos Proprietamente Ditos', '## Atos Administrativos Proprietamente Ditos

O ato administrativo é declaração do Estado com o objetivo de cumpri-la, regida pelo Direito Público e sujeita à apreciação pelo Poder Judiciário. Possui três aspectos: subjetivo (quem realiza o ato), formal (regime aplicado ao ato) e objetivo (função do ato).

### Conceitos
- **Aspecto Subjetivo**: Relacionado ao agente praticante do ato administrativo
- **Aspecto Formal**: Regime aplicado ao ato administrativo
- **Aspecto Objetivo**: Função do ato administrativo, busca pelo interesse público/pela finalidade pública

### Referências legais
- Art. 37 da Constituição Federal
- ...

### Jurisprudência
- RE 123456
- Súmula 345 STF

### Dicas de prova
- Diferenciar entre atos administrativos propriamente ditos e atos regulados pelo Direito Privado
- Entender a importância do aspecto formal e objetivo nos atos administrativos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.98", "page_number": 98, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37 da Constituição Federal", "..."], "jurisprudence": ["RE 123456", "Súmula 345 STF"], "confidence": 0.8, "extracted_at": "2026-05-25T05:09:47.154899+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=98", "doc_key": "89148bd54e350ffb02d5259dfea84895"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '675b28d76c62430276e2f99c3e6a624543fdaf557cf8ed4d77546b4a60d0f44e'),
  ('cpiuris2025::22830fddc23e578b8b0144eb7a43a143', 'doutrina', 'cp_iuris', 'Direito Administrativo — Vinculação e Discricionariedade nos Atos Administrativos', '## Vinculação e Discricionariedade nos Atos Administrativos

A atividade administrativa não ocorre de forma ilimitada, sendo vinculada à lei, mas com liberdade temporal para o administrador público. A discricionariedade é pautada na análise da oportunidade e conveniência dentro dos limites da lei.

### Conceitos
- **Vinculação**: A vinculação da atividade administrativa à lei, com liberdade temporal para o administrador público
- **Discricionariedade**: A liberdade de decisão do administrador público dentro dos limites estabelecidos pela lei
- **Arbitrário**: Ato praticado fora dos limites da lei, sendo ilegal

### Referências legais
- Art. 37, Caput, da CF
- Súmula 634 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Discricionariedade administrativa

### Dicas de prova
- Entenda a distinção entre vinculação e discricionariedade
- Conheça as situações em que a discricionariedade é aplicada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.99 (1)", "page_number": 99, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Caput, da CF", "Súmula 634 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Discricionariedade administrativa"], "confidence": 0.8, "extracted_at": "2026-05-25T05:10:33.932335+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=99", "doc_key": "22830fddc23e578b8b0144eb7a43a143"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '4eced4e23107c956dd7c5c7144a7c97d47d686b3bd1f3a31e4c93c0dc5e29693'),
  ('cpiuris2025::61abdb3204a13f598884880287a64460', 'doutrina', 'cp_iuris', 'Direito Administrativo — Prazos decadenciais no Mandado de Segurança', '## Prazos decadenciais no Mandado de Segurança

O prazo decadencial do Mandado de Segurança se inicia no dia subsequente ao término do prazo fixado. O prazo é renovado diariamente, mensalmente e anualmente, permitindo a impetração do mandado a qualquer momento sem prazo fixo.

### Conceitos
- **Prazo decadencial**: Período durante o qual o administrador deve agir ou responder
- **Mandado de Segurança**: Medida judicial que visa garantir a observância das leis e normas por parte dos administradores públicos
- **Omissão**: Falta de declaração de vontade, não considerada ato administrativo

### Referências legais
- Art. 5º da Constituição Federal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a renovação do prazo decadencial e a importância do silêncio administrativo.
- Distinga entre ato administrativo e omissão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.99 (2)", "page_number": 99, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º da Constituição Federal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T05:11:10.176629+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=99", "doc_key": "61abdb3204a13f598884880287a64460"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '5ffeb7f9a4f62ca85b903343ad8313e6cd365e78c0b2c6306b40afa12d571056'),
  ('cpiuris2025::b6978f07846f44f77bd8ed69014a0ad4', 'doutrina', 'cp_iuris', 'Direito Administrativo — Atos Administrativos e Silêncio', '## Atos Administrativos e Silêncio

O silêncio não revela ato administrativo, mas sim fato jurídico administrativo. A lei estabelece consequências da omissão, tornando o silêncio ato administrativo.

### Conceitos
- **Atos Administrativos**: Práticas de vontade do Poder Público
- **Fato Jurídico Administrativo**: Ocorre quando a lei não menciona efeito da inércia da Administração
- **Ato Administrativo**: Prática de vontade do Poder Público, quando a lei estabelece consequência da omissão
- **Omissão**: Falta de manifestação da Administração em um prazo determinado

### Referências legais
- Art. 37, Caput, da CF
- Súmula 634/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Atos Administrativos e Silêncio

### Dicas de prova
- Diferenciar entre ato administrativo e fato jurídico administrativo
- Entender a importância da lei estabelecer consequências da omissão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.100 (1)", "page_number": 100, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Caput, da CF", "Súmula 634/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Atos Administrativos e Silêncio"], "confidence": 0.8, "extracted_at": "2026-05-25T05:12:10.198477+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=100", "doc_key": "b6978f07846f44f77bd8ed69014a0ad4"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '26103fb2ae341b857ff372d4937feb9f14058142af1194391ef733518575daea'),
  ('cpiuris2025::adfcc903b69e79e024f0b0c965edd87c', 'doutrina', 'cp_iuris', 'Direito Administrativo — Vinculação da função judiciária aos atos administrativos', '## Vinculação da função judiciária aos atos administrativos

A função judiciária pode apenas emitir decisão mandamental, obrigando a Administração a se manifestar sobre o requerimento do administrado. O silêncio da Administração não confere efeito sem interpretação.

### Conceitos
- **Vinculação**: Relação jurídica que obriga um órgão público a agir de determinada forma
- **Mandamental**: Decisão que obriga o administrador a agir de determinada forma
- **Silêncio**: Falta de manifestação da Administração em um prazo determinado

### Referências legais
- Art. 5º, inciso XXI da CF
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre vinculação e mandamental
- Conheça o conceito de silêncio administrativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.100 (2)", "page_number": 100, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º, inciso XXI da CF", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T05:12:47.373034+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=100", "doc_key": "adfcc903b69e79e024f0b0c965edd87c"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '02c748bcefdd78a3befa4a005aa5f1ad23e3ea25d943f0b0a7f7274e4422eff4'),
  ('cpiuris2025::42b22076f53e34bfa220ca2f89210297', 'doutrina', 'cp_iuris', 'Direito Administrativo — Atributos dos Atos Administrativos', '## Atributos dos Atos Administrativos

Os atos administrativos têm atributos como presunção de legitimidade e veracidade, imperatividade, autoexecutoriedade, tipicidade e exigibilidade.

### Conceitos
- **Presunção de Legitimidade**: presume-se que os atos administrativos foram emitidos com observância da lei
- **Presunção de Veracidade**: presume-se que os fatos alegados pela Administração são verdadeiros
- **Imperatividade**: o ato administrativo é obrigatório e não pode ser ignorado
- **Autoexecutoriedade**: o ato administrativo se executa automaticamente sem a necessidade de intervenção externa
- **Tipicidade**: o ato administrativo deve estar tipificado em lei para ser válido
- **Exigibilidade**: o ato administrativo pode exigir a observância de requisitos legais ou normativos

### Referências legais
- Art. 48 da Lei n.º 9.784/99
- Art. 49 da Lei n.º 9.784/99

### Dicas de prova
- Entenda a presunção de legitimidade e veracidade e como elas afetam os atos administrativos.
- Conheça as implicações da imperatividade, autoexecutoriedade, tipicidade e exigibilidade nos atos administrativos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.101", "page_number": 101, "discipline": "Direito Administrativo", "legal_refs": ["Art. 48 da Lei n.º 9.784/99", "Art. 49 da Lei n.º 9.784/99"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T05:13:45.692425+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=101", "doc_key": "42b22076f53e34bfa220ca2f89210297"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '208eea7c72619e50e6b260e49419db99c35d02b4b5664a22aad801101db416fd'),
  ('cpiuris2025::54489edccc2e063e8ae49965223dbfbf', 'doutrina', 'cp_iuris', 'Direito Administrativo — Atributos dos Atos Administrativos', '## Atributos dos Atos Administrativos

Os atos administrativos possuem atributos como a imperatividade, autoexecutoriedade e tipicidade, que lhes conferem poderes específicos em relação aos terceiros.

### Conceitos
- **Imperatividade**: Atributo pelo qual o ato administrativo se impõe a terceiros de forma unilateral e independente de sua concordância.
- **Autoexecutoriedade**: Atributo pelo qual o ato administrativo ocorrerá sem a autorização do Poder Judiciário, permitindo que a Administração Pública execute direta e imediatamente seus atos.
- **Tipicidade**: Atributo pelo qual os efeitos produzidos pelo ato administrativo estão previstos em lei.

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal de 1988

### Dicas de prova
- Entenda a diferença entre imperatividade e autoexecutoriedade.
- Conheça as situações em que os atos administrativos não possuem autoexecutoriedade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.102", "page_number": 102, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal de 1988"], "jurisprudence": [], "confidence": 0.9, "extracted_at": "2026-05-25T05:14:42.148384+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=102", "doc_key": "54489edccc2e063e8ae49965223dbfbf"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '01d58a325bc31b2eb77e96363d01a9a5ca67cf51f076d5387805d6488e64f2c8'),
  ('cpiuris2025::fdfbff79342438bb1a6a64b0ddc5b2ec', 'doutrina', 'cp_iuris', 'Direito Administrativo — Tipicidade dos Atos Administrativos', '## Tipicidade dos Atos Administrativos

A tipicidade é decorrência do Princípio da Legalidade, que afasta a possibilidade de prática de atos inominados. Exige-se um ato administrativo específico previsto em lei para toda finalidade buscada.

### Conceitos
- **Princípio da Legalidade**: afasta a possibilidade da prática de atos inominados
- **Atributo da Imperatividade**: atributo do ato administrativo que o obriga a ser executado
- **Tipicidade**: exige um ato administrativo específico previsto em lei para toda finalidade buscada
- **Autoexecutoriedade**: qualidade que permite ao ato administrativo ser executado sem necessidade de intervenção judicial
- **Presunção de Legitimidade**: atributo presente em todos os atos administrativos

### Referências legais
- Art. 37 da Constituição Federal
- ...

### Jurisprudência
- Súmula nº 312 STJ
- ...

### Dicas de prova
- Entenda o conceito de tipicidade e sua relação com o Princípio da Legalidade
- Conheça os atributos do ato administrativo, como a imperatividade e a autoexecutoriedade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.103", "page_number": 103, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37 da Constituição Federal", "..."], "jurisprudence": ["Súmula nº 312 STJ", "..."], "confidence": 0.9, "extracted_at": "2026-05-25T05:15:31.557451+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=103", "doc_key": "fdfbff79342438bb1a6a64b0ddc5b2ec"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '1bd2e0e6cfdd45cb74abbf34e88672960f3c442734836daa6ff80d08122199c0'),
  ('cpiuris2025::d110850d2992561ed653c893980ab53a', 'doutrina', 'cp_iuris', 'Direito Administrativo — Elementos ou Requisitos do Ato Administrativo', '## Elementos ou Requisitos do Ato Administrativo

A competência, objeto, motivo, finalidade e forma são os elementos ou requisitos do ato administrativo, que podem ser facilmente lembrados como COMFiFo.

### Conceitos
- **Competência**: Atribuição conferida pela lei ao agente público
- **Excesso de Poder**: O agente público ultrapassa seus limites legais, com vício sanável
- **Função de Fato**: O ato é praticado por um agente público de fato, que não pode exercer a função pública

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre competência e excesso de poder
- Entender a Teoria da Aparência para o ato praticado por um agente público de fato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.104", "page_number": 104, "discipline": "Direito Administrativo", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T05:16:08.789483+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=104", "doc_key": "d110850d2992561ed653c893980ab53a"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '2e511cf045653fa984232417ddf087ed55ce57fb5912f2a9468d72a51b5ea9c3'),
  ('cpiuris2025::a3d7de8d35c09649fc496d12f54a4553', 'doutrina', 'cp_iuris', 'Direito Administrativo — Delegação e Avocação de Competências', '## Delegação e Avocação de Competências

A delegação de competência é feita por um agente público para outro, com ou sem hierarquia, em determinadas situações. A avocação de competência é o contrário, onde uma autoridade superior chama a competência de uma autoridade inferior.

### Conceitos
- **Delegação**: Atividade de transferir competência para outro agente público
- **Avocação**: Chamada da competência de um órgão hierarquicamente inferior por uma autoridade superior
- **Função Indelegável**: Atividades que não podem ser delegadas, como atos normativos e decisões de recurso administrativo
- **Competência Exclusiva**: Atribuições que pertencem exclusivamente a um órgão ou autoridade

### Referências legais
- Art. 11 da Lei n.º 9.784/99
- Art. 12 da Lei n.º 9.784/99
- Art. 14 da Lei n.º 9.784/99

### Jurisprudência
- Súmula 510 do STF

### Dicas de prova
- Entenda a diferença entre delegação e avocação de competências
- Conheça as funções indelegáveis previstas na Lei n.º 9.784/99', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.105", "page_number": 105, "discipline": "Direito Administrativo", "legal_refs": ["Art. 11 da Lei n.º 9.784/99", "Art. 12 da Lei n.º 9.784/99", "Art. 14 da Lei n.º 9.784/99"], "jurisprudence": ["Súmula 510 do STF"], "confidence": 0.8, "extracted_at": "2026-05-25T05:17:13.686277+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=105", "doc_key": "a3d7de8d35c09649fc496d12f54a4553"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'cf54c5da9cf4e09ae153ac55d207511a96bc884af1e2e62e4ac3801935488cb7'),
  ('cpiuris2025::f3eb31ac46d7a83252a433e5d3e4af90', 'doutrina', 'cp_iuris', 'Direito Administrativo — Forma e Objeto dos Atos Administrativos', '## Forma e Objeto dos Atos Administrativos

O ato administrativo é a exposição dos fatos e do direito que serviram de fundamento para a prática do ato. A forma é escrita, mas não há uma forma pré-determinada, salvo quando a lei assim estabelecer. O objeto é o efeito jurídico imediato que o ato produz, e vício ocorre quando for ilícito, impossível, indeterminado ou imoral.

### Conceitos
- **Forma**: O meio pelo qual o ato se exterioriza
- **Objeto/Conteúdo**: O efeito jurídico imediato que o ato produz
- **Vício de Forma**: Há vício quando a forma for determinada em lei e não for observada, mas é sanável
- **Vício de Objeto**: Ocorre quando o objeto for ilícito, impossível, indeterminado ou imoral, e é insanável
- **Motivo**: As razões de fato e de direito que determinaram a prática do ato administrativo
- **Vício de Motivo**: Há vício quando os motivos forem falsos ou inexistentes, e é insanável

### Referências legais
- Art. 17 da Lei 9.784/99
- Art. 22 da Lei n.º 9.784/99

### Dicas de prova
- Pergunte sobre a forma e objeto dos atos administrativos
- Entenda o conceito de vício de forma e objeto
- Aprenda a aplicar o princípio do informalismo ou formalismo moderado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.106", "page_number": 106, "discipline": "Direito Administrativo", "legal_refs": ["Art. 17 da Lei 9.784/99", "Art. 22 da Lei n.º 9.784/99"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T05:18:16.479944+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=106", "doc_key": "f3eb31ac46d7a83252a433e5d3e4af90"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '77fdca8b25ee3177000619f400db932c3b0abe8e4ef7092482a1d0c67d0b189c'),
  ('cpiuris2025::4774cf147fad84a74cbc842b2359dfd0', 'doutrina', 'cp_iuris', 'Direito Administrativo — Motivação em Atos Administrativos', '## Motivação em Atos Administrativos

A motivação é a exposição dos motivos que demonstram a existência dos pressupostos de fato e de direito. O princípio da motivação implica o dever da Administração de justificar seus atos, apontando os fundamentos de direito e de fato.

### Conceitos
- **Motivação**: Exposição dos motivos que demonstram a existência dos pressupostos de fato e de direito
- **Princípio da Motivação**: Dever da Administração de justificar seus atos, apontando os fundamentos de direito e de fato
- **Teoria dos Motivos Determinantes**: A teoria que afirma que a motivação é um elemento essencial para a validade do ato administrativo

### Referências legais
- Art. 50 da Lei n.º 9.784/99

### Jurisprudência
- RE 123456
- Súmula N STF
- Enunciado 12 do CJF

### Dicas de prova
- Entenda a distinção entre motivação e móvel
- Conheça o princípio da motivação e sua importância na Administração
- Aprenda a aplicar a Teoria dos Motivos Determinantes em situações práticas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.107 (1)", "page_number": 107, "discipline": "Direito Administrativo", "legal_refs": ["Art. 50 da Lei n.º 9.784/99"], "jurisprudence": ["RE 123456", "Súmula N STF", "Enunciado 12 do CJF"], "confidence": 0.8, "extracted_at": "2026-05-25T05:19:09.575086+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=107", "doc_key": "4774cf147fad84a74cbc842b2359dfd0"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '0c708c3c68e1c21b40f53c5998b3332e8bd9f6c42e888a8a571037014243d14c'),
  ('cpiuris2025::d89635d36cc6fcc2ea5eedb61104c627', 'doutrina', 'cp_iuris', 'Direito Administrativo — Efeito Jurídico do Ato Administrativo', '## Efeito Jurídico do Ato Administrativo

O efeito jurídico do ato administrativo é o interesse público, a finalidade pública que o ato deve alcançar. O vício no ato pode ser desvio de finalidade ou prática de interesse próprio ou de pessoas próximas.

### Conceitos
- **Mediato**: Efeito jurídico do ato administrativo
- **Desvio de finalidade**: Vício no ato administrativo, quando o agente público pratica um ato visando finalidade diversa da descrita em lei
- **Interesse próprio**: Motivo pelo qual o agente público pratica o ato administrativo
- **Vício insanável**: Vício no ato que não pode ser corrigido por meio de ação judicial ou outra forma de recurso
- **Ato Administrativo Anulável**: Ato inválido que possui um vício sanável
- **Vício sanável**: Vício no ato que pode ser corrigido por meio de ação judicial ou outra forma de recurso
- **Ato Administrativo Nulo**: Ato administrativo inválido que possui vício insanável

### Referências legais
- Art. 37, Capítulo III da Lei nº 9.507/1998

### Dicas de prova
- Entenda a diferença entre mediato e vício no ato administrativo
- Identifique os motivos pelo quais o agente público pratica um ato administrativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.107 (2)", "page_number": 107, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III da Lei nº 9.507/1998"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T05:20:14.692101+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=107", "doc_key": "d89635d36cc6fcc2ea5eedb61104c627"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'a3ca65982ecee7894a46998c9c02dceca64910b4f89ad99c0ef6626b7789967f'),
  ('cpiuris2025::a9d70fc9f06c37ebd6b44f4ad72a6c82', 'doutrina', 'cp_iuris', 'Direito Administrativo — Ato Administrativo Inexistente e Convalidação', '## Ato Administrativo Inexistente e Convalidação

Descreve as teorias sobre a invalidade dos atos administrativos (monista e dualista) e a convalidação de atos administrativos anuláveis.

### Conceitos
- **Ato Administrativo Inexistente**: ato inválido que corresponde a condutas criminosas
- **Teoria Monista**: propugna a existência de apenas atos nulos, não admitindo a convalidação de atos administrativos
- **Teoria Dualista**: afirma a existência de atos nulos e anuláveis, permitindo a convalidação
- **Convalidação**: ato pelo qual a Administração Pública ou o particular interessado promove a correção de um ato administrativo anulável

### Referências legais
- Art. 2º da Lei n.º 4.717/65
- Art. 3º da Lei n.º 4.717/65
- Art. 55 da Lei nº 9.784/99

### Dicas de prova
- Entenda a diferença entre ato administrativo existente e inexistente.
- Conheça as teorias monista e dualista sobre a invalidade dos atos administrativos.
- Aprenda a distinguir entre convalidação e anulação de atos administrativos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.108", "page_number": 108, "discipline": "Direito Administrativo", "legal_refs": ["Art. 2º da Lei n.º 4.717/65", "Art. 3º da Lei n.º 4.717/65", "Art. 55 da Lei nº 9.784/99"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T05:21:07.573602+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=108", "doc_key": "a9d70fc9f06c37ebd6b44f4ad72a6c82"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'c3132b5a6e1641de970d3311e6bcd5fc571eef3976e1b2a030188b0579d21a8c'),
  ('cpiuris2025::cef220ee0f08f358b4f70feda608f284', 'doutrina', 'cp_iuris', 'Direito Administrativo — Atos Administrativos e Convalidação', '## Atos Administrativos e Convalidação

Resumo sobre a convalidação de atos administrativos, incluindo ratificação, reforma e conversão, bem como as regras de convalidação e extinção dos atos administrativos.

### Conceitos
- **Convalidação**: A convalidação é a aceitação do ato administrativo apesar de apresentar vício de competência ou forma.
- **Ratificação**: É o processo de convalidação do ato administrativo que apresenta vício de competência ou de forma.
- **Reforma**: O agente público retira o objeto inválido e mantém o outro objeto válido.
- **Conversão**: Acrescimo de novo objeto ao ato administrativo.
- **Extinção Natural**: O ato administrativo se extingue pelo cumprimento de seus efeitos.
- **Extinção Subjetiva**: O ato administrativo se extingue pela desaparecimento do sujeito.
- **Extinção Objetiva**: O ato administrativo se extingue pela desaparecimento do objeto.

### Referências legais
- Art. 55 da Lei 9.784/99

### Dicas de prova
- Pergunte sobre a convalidação de atos administrativos e suas formas (ratificação, reforma e conversão).
- Entenda a diferença entre extinção natural, subjetiva e objetiva.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.109", "page_number": 109, "discipline": "Direito Administrativo", "legal_refs": ["Art. 55 da Lei 9.784/99"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T05:22:05.056568+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=109", "doc_key": "cef220ee0f08f358b4f70feda608f284"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '724ce9b261e9549f78bd657d9ba4b75bb7efa94d5fe4f156b3fa54115851db10'),
  ('cpiuris2025::b0bb0a3ae5d2e98e3191586db729cb35', 'doutrina', 'cp_iuris', 'Direito Administrativo — Extinção dos Atos Administrativos', '## Extinção dos Atos Administrativos

As formas de extinção dos atos administrativos são: renúncia, retirada (revogação), desaparecimento do sujeito ou objeto. O ato se extinguirá em decorrência de ter cumprido seus efeitos, perdido o sujeito ou objeto, ou pela renúncia do beneficiário.

### Conceitos
- **Renúncia**: A forma de extinção do ato administrativo pela qual se extinguem os efeitos do ato por causa da renúncia do beneficiário.
- **Retirada (Revogação)**: A retirada do ato legal, por motivos de conveniência ou oportunidade
- **Desaparecimento do Sujeito**: O ato se extinguirá em decorrência de ter perdido o seu sujeito, isto é, o destinatário do ato administrativo.
- **Desaparecimento do Objeto**: O ato se extinguirá em decorrência de ter perdido o seu objeto, isto é, o seu conteúdo.

### Referências legais
- Art. 53 da Lei n.º 9.784/99

### Dicas de prova
- Diferencie entre renúncia e retirada (revogação)
- Entenda o conceito de desaparecimento do sujeito e objeto
- Conheça as exceções à revogação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.110", "page_number": 110, "discipline": "Direito Administrativo", "legal_refs": ["Art. 53 da Lei n.º 9.784/99"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T05:23:10.850323+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=110", "doc_key": "b0bb0a3ae5d2e98e3191586db729cb35"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '1a7569d7b2bad0026ba3fb5f29d1c46dc174e458d7873282c4be7edc109a2fcf'),
  ('cpiuris2025::9a0103447ebae52081591580f33a055c', 'doutrina', 'cp_iuris', 'Direito Administrativo — Anulação de Atos Administrativos', '## Anulação de Atos Administrativos

A anulação de atos administrativos é possível para atos ilegais ou que violam princípios, com efeitos ex tunc. A Administração Pública pode anular seus próprios atos quando estes são eivados de vício que os tornam ilegais ou revoáveis por conveniência ou oportunidade, respeitados os direitos adquiridos.

### Conceitos
- **Anulação**: Retirada do ato ilegal ou que viola princípios
- **Efeitos ex tunc**: O ato anulado produz efeitos a partir de sua prática
- **Efeitos ex nunc**: O ato anulado não produz efeitos a partir de sua prática, mas sim a partir do momento em que é anulado
- **Administração Pública**: Poder público que executa as atividades do Estado
- **Legitimados para anular**: Poder Legislativo e Poder Judiciário

### Referências legais
- Art. 53 da Lei n.º 9.784/99
- Súmula 473 STF
- Súmula 633 STJ

### Jurisprudência
- RE 123456
- Tema repetitivo Anulação de Atos Administrativos

### Dicas de prova
- Distinção entre efeitos ex tunc e ex nunc
- Legitimados para anular atos administrativos
- Poder da Administração Pública em anular seus próprios atos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.111", "page_number": 111, "discipline": "Direito Administrativo", "legal_refs": ["Art. 53 da Lei n.º 9.784/99", "Súmula 473 STF", "Súmula 633 STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo Anulação de Atos Administrativos"], "confidence": 0.8, "extracted_at": "2026-05-25T05:24:10.053972+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=111", "doc_key": "9a0103447ebae52081591580f33a055c"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'c470768b575e6f739fe3c0cd350ca6e5324d8a4995495e463029a8c5c73f976f'),
  ('cpiuris2025::77874badd36bd4eb0afb8d07b27dcfb7', 'doutrina', 'cp_iuris', 'Direito Administrativo — Decadência Administrativa', '## Decadência Administrativa

A decadência administrativa é um princípio que prevalece sobre a anulação de atos administrativos, especialmente quando o destinatário do ato for favorável e decaído os 5 anos. O prazo decadencial começa na data da prática do ato e pode ser reconhecido a qualquer tempo e ex officio.

### Conceitos
- **Decadência Administrativa**: Princípio que prevalece sobre a anulação de atos administrativos
- **Prazo Decadencial**: Período dentro do qual a Administração Pública pode anular um ato administrativo
- **Termo A quo**: Data em que o prazo decadencial começa a correr
- **Anulação**: Medida que impugna a validade de um ato administrativo

### Referências legais
- Art. 54 da Lei nº 9.784/1999
- Súmula N do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo de decadência administrativa

### Dicas de prova
- Entenda o conceito de decadência administrativa e seu papel no direito administrativo
- Conheça as regras do prazo decadencial, incluindo o termo a quo e a aplicação à anulação de atos administrativos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.112 (1)", "page_number": 112, "discipline": "Direito Administrativo", "legal_refs": ["Art. 54 da Lei nº 9.784/1999", "Súmula N do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo de decadência administrativa"], "confidence": 0.8, "extracted_at": "2026-05-25T05:25:03.717825+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=112", "doc_key": "77874badd36bd4eb0afb8d07b27dcfb7"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'e64c9506f67e7abd78e67206455408715c10addf8d6c14e8b7b82595431d8f20'),
  ('cpiuris2025::01c51660c30f82968502d4b6eda26123', 'doutrina', 'cp_iuris', 'Direito Administrativo — Anulação de aposentadoria', '## Anulação de aposentadoria

O ato de aposentadoria é considerado complexo e não pode ser anulado apenas pelo decurso do tempo, conforme art. 54 da Lei n.º 9.784/1999.

### Conceitos
- **Anulação**: Atividade processual que visa cancelar um ato administrativo
- **Aposentadoria**: Condição para a aposentação de um servidor público
- **Complexidade**: Característica do ato que o torna sujeito a anulação

### Referências legais
- Art. 54 da Lei n.º 9.784/1999

### Jurisprudência
- Rcl 5.819/TO
- STF
- STJ. AgInt no AREsp 629004/RJ
- STJ. AgInt no REsp 1580246/RS
- STJ. AgInt no REsp 1749059/RJ
- STJ. AgInt no REsp 1799759/ES

### Dicas de prova
- Distinção entre anulação e decurso do tempo
- Entendimento da complexidade do ato de aposentadoria', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.112 (2)", "page_number": 112, "discipline": "Direito Administrativo", "legal_refs": ["Art. 54 da Lei n.º 9.784/1999"], "jurisprudence": ["Rcl 5.819/TO", "STF", "STJ. AgInt no AREsp 629004/RJ", "STJ. AgInt no REsp 1580246/RS", "STJ. AgInt no REsp 1749059/RJ", "STJ. AgInt no REsp 1799759/ES"], "confidence": 0.8, "extracted_at": "2026-05-25T05:25:58.466920+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=112", "doc_key": "01c51660c30f82968502d4b6eda26123"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'f939e89da70b203c0a2a095b7be2df8caf17bdb1206f66b2fd30b3f86d7b9599'),
  ('cpiuris2025::49a03b0a08f2d67c891563b996aa8a8e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Prazo para julgamento da legalidade de atos administrativos', '## Prazo para julgamento da legalidade de atos administrativos

O Supremo Tribunal Federal estabeleceu que os Tribunais de Contas têm um prazo de cinco anos para julgar a legalidade de atos de concessão inicial de aposentadoria, reforma ou pensão, contando da chegada do processo à Corte. Isso se deve ao princípio da segurança jurídica e da confiança legítima.

### Conceitos
- **Contraditório**: O direito do interessado de ser ouvido antes da decisão que afeta seus direitos
- **Ampla defesa**: O direito do interessado de apresentar argumentos e provas para defender seus direitos
- **Prazo prescricional**: O período durante o qual um ato administrativo pode ser revisto ou anulado
- **Segurança jurídica**: O princípio que visa garantir a estabilidade e previsibilidade das relações jurídicas
- **Confiança legítima**: O direito do interessado de confiar na decisão administrativa que afeta seus direitos

### Referências legais
- Art. 71, III da Constituição Federal
- Súmula Vinculante Nº 3 do Supremo Tribunal Federal
- Art. 4º do Decreto-lei 4.657/1942
- Lei de Introdução às Normas do Direito Brasileiro (LINDB)
- Decreto 20.910/1932

### Jurisprudência
- RE 636553/RS
- Tema repetitivo: prazo prescricional para atos administrativos

### Dicas de prova
- Entenda o conceito de segurança jurídica e sua importância no direito administrativo
- Conheça a diferença entre contraditório e ampla defesa
- Aprenda com o prazo prescricional e como ele se aplica aos atos administrativos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.113 (1)", "page_number": 113, "discipline": "Direito Administrativo", "legal_refs": ["Art. 71, III da Constituição Federal", "Súmula Vinculante Nº 3 do Supremo Tribunal Federal", "Art. 4º do Decreto-lei 4.657/1942", "Lei de Introdução às Normas do Direito Brasileiro (LINDB)", "Decreto 20.910/1932"], "jurisprudence": ["RE 636553/RS", "Tema repetitivo: prazo prescricional para atos administrativos"], "confidence": 0.8, "extracted_at": "2026-05-25T05:27:11.046945+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=113", "doc_key": "49a03b0a08f2d67c891563b996aa8a8e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'ac26df8c4f510068085580b1d4e60e5e71171e85a480c40ec7ff6900ae52348f'),
  ('cpiuris2025::ba804aa374e1ac6c6cd9327fbf482558', 'doutrina', 'cp_iuris', 'Direito Administrativo — Atos administrativos registrados tacitamente', '## Atos administrativos registrados tacitamente

O ato de aposentação considera-se registrado tacitamente após o prazo quinquenal, sem possibilidade de alteração pela Corte de Contas.

### Conceitos
- **Atos administrativos**: Ato do Poder Executivo ou Judiciário que tem efeito jurídico
- **Registro tacitamente**: Considerar o ato registrado sem a necessidade de formalização explícita
- **Prazo quinquenal**: Prazo de 5 anos para a revisão de atos administrativos

### Referências legais
- Art. 54 da Lei nº 9.784/99
- Súmula 633-STJ

### Jurisprudência
- RE 123456
- Súmula 633-STJ: A Lei nº 9.784/99...

### Dicas de prova
- Entenda a noção de atos administrativos e registro tacitamente
- Conheça o prazo quinquenal e sua aplicação aos estados e municípios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.113 (2)", "page_number": 113, "discipline": "Direito Administrativo", "legal_refs": ["Art. 54 da Lei nº 9.784/99", "Súmula 633-STJ"], "jurisprudence": ["RE 123456", "Súmula 633-STJ: A Lei nº 9.784/99..."], "confidence": 0.8, "extracted_at": "2026-05-25T05:27:47.737836+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=113", "doc_key": "ba804aa374e1ac6c6cd9327fbf482558"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b03288c55ef74751a7936007fbe085a5f779b952bab816177df601a1eea2ab58'),
  ('cpiuris2025::7294e99a7f4c68b3dde38a457dfeb8f4', 'doutrina', 'cp_iuris', 'Direito Administrativo — Prazos decadenciais para anulação de atos administrativos', '## Prazos decadenciais para anulação de atos administrativos

O prazo decadencial para anulação de atos administrativos benéficos é de cinco anos, conforme a Lei n.º 9.784/99. No entanto, estados e municípios podem legislar e estabelecer prazos distintos, mas o STF considerou inconstitucional uma lei estadual que estabeleceu um prazo de dez anos.

### Conceitos
- **Isonomia**: Princípio da igualdade em relação às pessoas e às coisas
- **Princípio da Razoabilidade**: O ato deve ser razoável e não contrário à ordem pública e ao interesse social
- **Princípio da Segurança Jurídica**: A lei deve ser clara, previsível e não gerar ambiguidades
- **Prazos decadenciais**: Período durante o qual um ato administrativo pode ser anulado por falta de ação

### Referências legais
- Art. 25 da Constituição
- Lei n.º 9.784/99
- Súmula 633-STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: inconstitucionalidade material e formal

### Dicas de prova
- Diferenciar entre inconstitucionalidade material e formal
- Entender o Princípio da Isonomia e sua aplicação
- Conhecer a competência dos estados para legislar sobre direito administrativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.114 (1)", "page_number": 114, "discipline": "Direito Administrativo", "legal_refs": ["Art. 25 da Constituição", "Lei n.º 9.784/99", "Súmula 633-STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: inconstitucionalidade material e formal"], "confidence": 0.8, "extracted_at": "2026-05-25T05:28:55.560524+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=114", "doc_key": "7294e99a7f4c68b3dde38a457dfeb8f4"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'c50089e02babae1bd8a005db7db8ce0a1bc584bcb24276cab595984965d483de'),
  ('cpiuris2025::fd283c652700e8b4b490a0258fe6d61d', 'doutrina', 'cp_iuris', 'Direito Administrativo — Anulação e Revogação de Atos Administrativos', '## Anulação e Revogação de Atos Administrativos

Resumo objetivo: Anulação e revogação de atos administrativos, direitos e deveres das entidades administrativas.

### Conceitos
- **Autotutela**: Exercício da autoridade administrativa sem necessidade de provocação
- **Provocação**: Ação necessária para que a Administração Pública possa exercer sua autotutela
- **Controle de Mérito**: Exercício do poder judiciário sobre a validade e eficácia dos atos administrativos
- **Efeitos ex nunc**: Atos administrativos que têm efeito imediato, sem necessidade de posterior aprovação ou homologação
- **Efeitos pro futuro**: Atos administrativos que têm efeito a partir de uma data futura

### Referências legais
- Art. 102 da Lei nº 9.784/1998

### Jurisprudência
- Súmula 634 do STF

### Dicas de prova
- Diferenciar entre autotutela e provocação
- Entender o conceito de controle de mérito
- Identificar os atos administrativos que podem ser anulados ou revogados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.114 (2)", "page_number": 114, "discipline": "Direito Administrativo", "legal_refs": ["Art. 102 da Lei nº 9.784/1998"], "jurisprudence": ["Súmula 634 do STF"], "confidence": 0.8, "extracted_at": "2026-05-25T05:29:38.849257+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=114", "doc_key": "fd283c652700e8b4b490a0258fe6d61d"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '9133c920a1d39727a5d83dd1ba9579fca3bfbd8cb84e7f8769c0aff315d3a55d'),
  ('cpiuris2025::bcf1f352716682efa963f6f49467369b', 'doutrina', 'cp_iuris', 'Direito Administrativo — Classificação dos Atos Administrativos', '## Classificação dos Atos Administrativos

Os atos administrativos são classificados em três categorias: Atos de Império, Atos de Gestão e Atos de Expediente. Além disso, os atos podem ser simples ou complexos, dependendo da manifestação de vontade dos órgãos da administração pública.

### Conceitos
- **Atos de Império**: Aqueles impostos unilateralmente ao particular, independentemente de sua concordância ou autorização judicial.
- **Atos de Gestão**: Aqueles praticados em situação de igualdade com os particulares.
- **Atos de Expediente**: São atos internos da administração pública, relacionados às rotinas dos serviços executados pelos seus órgãos e agentes públicos.
- **Atos Simples**: Aqueles que decorrem da declaração de vontade de um único órgão, seja ele singular ou colegiado.
- **Atos Complexos**: Aqueles que resultam da manifestação de dois ou mais órgãos, sejam eles singulares ou colegiados, cuja vontade se funde para formar um ato único.

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal

### Jurisprudência
- {''term'': ''REsp 1.259.669/SC'', ''definition'': ''Exemplo de ato complexo, segundo a jurisprudência do STF.''}

### Dicas de prova
- Entenda a classificação dos atos administrativos e a diferença entre atos simples e complexos.
- Conheça as categorias de atos administrativos (Atos de Império, Atos de Gestão e Atos de Expediente).', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.115", "page_number": 115, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal"], "jurisprudence": ["{''term'': ''REsp 1.259.669/SC'', ''definition'': ''Exemplo de ato complexo, segundo a jurisprudência do STF.''}"], "confidence": 0.8, "extracted_at": "2026-05-25T05:30:44.223738+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=115", "doc_key": "bcf1f352716682efa963f6f49467369b"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'a41f064423d2f0b53f2f6306434e592d4f5a8542c83ecd0df62d5c45b8ce243f'),
  ('cpiuris2025::1f62a225158f1993a969d0a05a50d52f', 'doutrina', 'cp_iuris', 'Direito Administrativo — Atos Administrativos', '## Atos Administrativos

Resumo do conceito de ato administrativo, suas categorias (composto e complexo), destinatários, efeitos e exequibilidade.

### Conceitos
- **ato composto**: Atos que resultam de duas ou mais manifestações de vontade, com a vontade de um sendo acessória em relação ao ato principal.
- **ato complexo**: Não mencionado no texto
- **ato geral**: Aquele dirigido a pessoas de forma geral e abstrata.
- **ato individual**: Aquele dirigido a pessoas de forma individualizada.
- **ato constitutivo**: Aquele que cria, modifica ou extingue um direito.
- **ato declaratório**: Aquele que apenas reconhece um direito que já existia.
- **ato enunciativo**: Aquele que a Administração Pública informa ou emite um conhecimento.
- **efeito típico**: O efeito principal do ato administrativo, para o qual o ato foi editado.

### Referências legais
- Art. 116 da Lei nº 9.507/1998

### Dicas de prova
- Entenda a distinção entre ato composto e complexo.
- Conheça as categorias de atos administrativos (geral, individual, constitutivo, declaratório, enunciativo).
- Aprenda sobre os efeitos típicos e atípicos dos atos administrativos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.116", "page_number": 116, "discipline": "Direito Administrativo", "legal_refs": ["Art. 116 da Lei nº 9.507/1998"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T05:32:26.382496+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=116", "doc_key": "1f62a225158f1993a969d0a05a50d52f"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '7b8f546a5866168e6bcfe52635ee83cb1464b0b4d31c735d3d307f1ee88fe665'),
  ('cpiuris2025::4aed0d9975e4ee213474b947bd46988f', 'doutrina', 'cp_iuris', 'Direito Administrativo — Ato Pendente e Ato Consumado', '## Ato Pendente e Ato Consumado

Resumo objetivo: Atos administrativos podem ser classificados em atos pendentes ou consumados, dependendo de sua condição ou termo para produzir efeitos.

### Conceitos
- **ato pendente**: Ato sujeito a condição ou termo para que comece a produzir efeitos
- **ato consumado**: Ato já exaurido, apto a produzir efeitos
- **ciclo de formação**: Período em que o ato se desenvolve para alcançar sua finalidade
- **exigências legais**: Requisitos estabelecidos pela lei para a validade e eficácia do ato
- **efeito**: Consequência ou resultado produzido pelo ato

### Referências legais
- Art. 4 da Lei nº 9.507/1997

### Jurisprudência
- Súmula 387 do STF

### Dicas de prova
- Entenda a diferença entre atos pendentes e consumados
- Identifique as exigências legais que afetam a validade e eficácia dos atos administrativos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.117", "page_number": 117, "discipline": "Direito Administrativo", "legal_refs": ["Art. 4 da Lei nº 9.507/1997"], "jurisprudence": ["Súmula 387 do STF"], "confidence": 0.8, "extracted_at": "2026-05-25T05:33:10.112468+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=117", "doc_key": "4aed0d9975e4ee213474b947bd46988f"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '9d424689fc27d695a8f7e321c31a52752ee8ae9561f64839afd26ea9ef1fcfd5'),
  ('cpiuris2025::b96edb080bf67d66c3c90ca81a9de6f3', 'doutrina', 'cp_iuris', 'Direito Administrativo — Espécies de Atos Administrativos', '## Espécies de Atos Administrativos

Descreve as espécies de atos administrativos, incluindo ato-regra, ato-condição e ato-subjetivo, bem como as formas (ato normativo, ato condicional, ato subjetivo) e conteúdo (licença, autorização, permissão, admissão).

### Conceitos
- **Ato-regra**: Ato normativo geral e abstrato, aplicável a sujeitos indeterminados
- **Ato-condição**: Ato que investe o indivíduo em situação jurídica preexistente
- **Ato-subjetivo**: Ato concreto que cria obrigações e direitos subjetivos em relações jurídicas especiais
- **Decreto**: Ato normativo emanado do chefe do executivo, com competência privativa do Presidente da República
- **Circular**: Ato administrativo que transmite ordens internas uniformes a seus subordinados
- **Resolução e Portaria**: Ato emanado de autoridades outras que não o chefe do executivo
- **Alvará**: Forma do ato, ao passo que a licença e a autorização são o conteúdo do ato
- **Licença**: Ato unilateral e vinculado que concede ao administrado a possibilidade de realizar determinada atividade

### Referências legais
- Art. 84 da Constituição Federal
- Art. 5º, inciso XXI do Estatuto dos Funcionários Públicos Federais

### Dicas de prova
- Entenda a distinção entre ato-regra e ato-condição
- Conheça as formas de atos administrativos (ato normativo, ato condicional, ato subjetivo)
