  ('cpiuris2025::952eca4bfa930f4dc23e2c3df0be21b2', 'doutrina', 'cp_iuris', 'Direito Administrativo — Atos Administrativos', '## Atos Administrativos

Descreve os diferentes tipos de atos administrativos, incluindo aprovação, homologação, visto, parecer, atos normativos e atos negociais.

### Conceitos
- **Aprovação**: Ato unilateral e discricionário pelo qual a Administração exerce o controle do ato administrativo.
- **Homologação**: Ato unilateral e vinculado pelo qual a Administração faz a análise da legalidade de ato praticado pelos seus órgãos.
- **Visto**: Ato administrativo unilateral pelo qual determinada autoridade atesta a legitimidade formal de outro ato administrativo.
- **Parecer**: Ato pelo qual os órgãos consultivos da Administração emitem opinião sobre determinados assuntos, sejam jurídicos, sejam técnicos.
- **Ato Normativo**: Atos que contêm comandos gerais e abstratos aplicáveis a todos os administrados que se enquadrem nas situações nele previstas.
- **Ato Negocial**: Relação entre o interesse da Administração e o interesse do Particular, não possuindo o atributo da imperatividade.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre aprovação e homologação.
- Conheça os tipos de atos normativos e negociais.
- Aprenda a importância do parecer na Administração Pública.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.119 (1)", "page_number": 119, "discipline": "Direito Administrativo", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T05:35:49.796342+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=119", "doc_key": "952eca4bfa930f4dc23e2c3df0be21b2"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '0faaf9fa62a400e7efb3dd7c7ce3367ab2928e4bc39dd38974b33fd9f6597400'),
  ('cpiuris2025::ed837969a03d29c2e470a11823931406', 'doutrina', 'cp_iuris', 'Direito Administrativo — Autorização', '## Autorização

Ato unilateral e discricionário que autoriza o uso de bem público ou a prática de atividade privada, não dependendo de licitação.

