  ('cpiuris2025::a3d2cc16377de60996bab027b93adb15', 'doutrina', 'cp_iuris', 'Direito Administrativo — Atos Administrativos', '## Atos Administrativos

O artigo 22 estabelece que, na interpretação de normas sobre gestão pública, devem ser considerados os obstáculos e as dificuldades reais do gestor e as exigências das políticas públicas. Além disso, o artigo 23 determina que a decisão administrativa deve prever regime de transição quando indispensável para cumprir novo dever ou condicionamento de direito.

### Conceitos
- **Atos Administrativos**: atos emitidos por órgãos públicos
- **Interpretação de normas**: processo de compreensão e aplicação das regras e diretrizes
- **Gestão Pública**: gestão eficiente e eficaz dos recursos públicos
- **Sanções**: medidas legais tomadas contra um indivíduo por infração de regra ou lei
- **Revisão**: processo de reavaliação e reexame de uma decisão ou ato

### Referências legais
- Art. 22 da Lei X
- Art. 23 da Lei Y
- Súmula Z da STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Atos Administrativos

### Dicas de prova
- Entenda a noção de ato administrativo e sua importância na gestão pública
- Conheça as regras para a interpretação de normas e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.121 (1)", "page_number": 121, "discipline": "Direito Administrativo", "legal_refs": ["Art. 22 da Lei X", "Art. 23 da Lei Y", "Súmula Z da STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Atos Administrativos"], "confidence": 0.8, "extracted_at": "2026-05-25T05:38:00.608154+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=121", "doc_key": "a3d2cc16377de60996bab027b93adb15"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '8166721c79b3eb5285de3b3fbba61a3452e6cd4b97c8c9ba98fdd362e35d1a3c'),
  ('cpiuris2025::17f0f8cd4c8b7615a45898d3a36f1de4', 'doutrina', 'cp_iuris', 'Direito Administrativo — Compromisso Processual e Responsabilidade Administrativa', '## Compromisso Processual e Responsabilidade Administrativa

O artigo 26 estabelece o compromisso processual como meio para resolver irregularidades e incertezas na aplicação do direito público, com a publicação oficial sendo condição para sua eficácia. O artigo 27 discute a compensação por benefícios indevidos ou prejuízos anormais resultantes de processos administrativos, enquanto o artigo 28 estabelece a responsabilidade pessoal do agente público em caso de dolo ou erro grosseiro.

### Conceitos
- **Compromisso Processual**: Acordo entre as partes para resolver irregularidades e incertezas na aplicação do direito público
- **Responsabilidade Administrativa**: O dever de agir com cuidado e competência em relação às decisões e opiniões técnicas
- **Dolo**: Ação intencional para prejudicar alguém ou causar dano
- **Erro Grosseiro**: Decisão ou ação que resulta em prejuízo injusto ou anormal, podendo ser responsabilizado pelo TCU
- **Compensação**: Ação para compensar benefícios indevidos ou prejuízos anormais resultantes de processos administrativos

### Referências legais
- Art. 26
- Art. 27
- Art. 28

### Dicas de prova
- Entenda a diferença entre dolo e erro grosseiro
- Conheça o conceito de compensação e como ela se relaciona com os compromissos processuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.121 (2)", "page_number": 121, "discipline": "Direito Administrativo", "legal_refs": ["Art. 26", "Art. 27", "Art. 28"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T05:38:58.900677+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=121", "doc_key": "17f0f8cd4c8b7615a45898d3a36f1de4"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '340d34b9580a144f68ca06403db06f5e8d34c552efb7ff674fcf7f275e4820b6'),
  ('cpiuris2025::c78168bc16384d64425f1ab93fd4ae3b', 'doutrina', 'cp_iuris', 'Direito Administrativo — Atos Administrativos', '## Atos Administrativos

A devida motivação em atos administrativos é necessária, e a falta dela pode configurar culpa grave. Além disso, a edição de atos normativos deve ser precedida de consulta pública para manifestação de interessados.

### Conceitos
- **Culpa Grave**: Falta de motivação adequada em atos administrativos
- **Consulta Pública**: Obrigatório para edição de atos normativos
- **Atos Normativos**: Decisões tomadas por autoridade administrativa

### Referências legais
- Art. 28 do Decreto-lei 4.657/1942
- Art. 29 do Decreto-lei 4.657/1942

### Jurisprudência
- TCU - Acórdão 1264/2019 Plenário

### Dicas de prova
- Diferenciar entre culpa grave e erro grosseiro
- Entender a importância da consulta pública em atos normativos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.122", "page_number": 122, "discipline": "Direito Administrativo", "legal_refs": ["Art. 28 do Decreto-lei 4.657/1942", "Art. 29 do Decreto-lei 4.657/1942"], "jurisprudence": ["TCU - Acórdão 1264/2019 Plenário"], "confidence": 0.8, "extracted_at": "2026-05-25T05:39:36.571722+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=122", "doc_key": "c78168bc16384d64425f1ab93fd4ae3b"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'a3d6e1005f2c3adbaff902eaef7f8acbdcf957c106e5f1d3dd355521efa578da'),
  ('cpiuris2025::54e08df6ec92b938425cf01b980fd205', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade Civil do Estado', '## Responsabilidade Civil do Estado

O Estado responde civilmente por atos ilícitos ou lícitos, independentemente da antijuridicidade. Para responsabilização por atos lícitos, o dano deve ser anormal, extraordinário e específico.

### Conceitos
- **Responsabilidade Civil do Estado**: O direito pelo qual o Estado se obriga a reparar os danos causados por seus atos ou omissões.
- **Antijuridicidade**: A ausência de ilegalidade em um ato ou ação do Estado.
- **Teoria da Repartição dos Encargos Sociais**: A teoria que afirma que os encargos sociais devem ser repartidos entre o Estado e a coletividade.
- **Princípio da Isonomia**: O princípio que estabelece a igualdade de tratamento para todos os cidadãos diante do Estado.
- **Dano Anormal**: Um dano que é inesperado e não parte do curso normal das coisas.
- **Dano Extraordinário**: Um dano que é excepcional e não comum.
- **Dano Específico**: Um dano que é direcionado a uma pessoa ou grupo específico.
- **Responsabilidade Civil**: O direito pelo qual uma pessoa se obriga a reparar os danos causados por suas ações ou omissões.

### Referências legais
- Art. 37, Capítulo III da Constituição Federal

### Jurisprudência
- Súmula 343 do STF
- RE 123456

### Dicas de prova
- Entenda a distinção entre atos ilícitos e lícitos do Estado.
- Conheça as teorias sobre responsabilidade civil, como a Teoria da Repartição dos Encargos Sociais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.125", "page_number": 125, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal"], "jurisprudence": ["Súmula 343 do STF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T05:40:53.702847+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=125", "doc_key": "54e08df6ec92b938425cf01b980fd205"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'ed10ded7859baa8efe1082a658e172d901c0dbbe90a5c392b04e65a39829b436'),
  ('cpiuris2025::e95088e5595ca68d298e105f87580b9e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade Civil do Estado', '## Responsabilidade Civil do Estado

A responsabilidade civil do Estado é abordada por três teorias: da irresponsabilidade, dos atos de império e gestão, e da culpa civil. A teoria da irresponsabilidade afirma que o Estado não responde civilmente pelos danos causados por seus agentes, pois ele não erra. As outras duas teorias propõem responsabilidades diferentes.

### Conceitos
- **Teoria da Irresponsabilidade**: O Estado não responde civilmente pelos danos causados por seus agentes
- **Teoria dos Atos de Império e de Gestão**: O Estado pode ser responsabilizado pelos danos causados por meio dos atos de gestão, mas não nos atos de império
- **Teoria da Culpa Civil**: O Estado responderá subjetivamente, caso gere danos a terceiros, identificando o agente causador do dano e comprovando sua conduta dolosa ou culposa
- **Teoria da Culpa Anônima ou Culpa do Serviço**: O Estado responderá civilmente independente da identificação do agente causador do dano, se o serviço não funcionou, funcionou mal ou funcionou tardiamente
- **Revolução Francesa de 1789**: Surgeu o Estado de Direito, limitando a ordem jurídica pelo princípio da legalidade e com a separação dos poderes
- **Direito brasileiro**: Essa teoria nunca foi aplicada

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda as três teorias de responsabilidade civil do Estado e suas diferenças
- Identifique a teoria que foi aplicada ao Direito brasileiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.126", "page_number": 126, "discipline": "Direito Administrativo", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T05:41:57.623242+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=126", "doc_key": "e95088e5595ca68d298e105f87580b9e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '3b99ec9e119efa779fda5c10c4b6b30512b91d06d879ca6628a57859be65d089'),
  ('cpiuris2025::f12564d3d3426caa066ff42f96e39a33', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade Civil do Estado', '## Responsabilidade Civil do Estado

A responsabilidade civil do Estado é subjetiva e resulta de uma premissa inicial de negligência na prestação do serviço. O Estado deve provar que o serviço funcionou, enquanto a vítima deve provar a culpa do serviço.

### Conceitos
- **Responsabilidade Civil**: Subjetiva, resultante de negligência na prestação do serviço
- **Omissão**: Poder público que não exerce seu dever
- **Culpa do Serviço**: Teoria aplicada à responsabilidade por omissão do Estado
- **Subjetividade**: Responsabilidade do Estado que depende da prova de culpa
- **Objetividade**: Responsabilidade do Estado que não depende da prova de culpa, em casos específicos
- **Teoria do Risco Integral**: O Estado é um segurador universal e sempre é responsável por um dano ocorrido
- **Nexo Causal**: Relação entre o fato e o dano

### Referências legais
- Art. 21, XXIII, d, CR/88

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Distinção entre subjetividade e objetividade na responsabilidade civil do Estado
- Comprovação da culpa do serviço em casos de omissão
- Teoria do Risco Integral: responsabilidade do Estado como segurador universal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.127 (1)", "page_number": 127, "discipline": "Direito Administrativo", "legal_refs": ["Art. 21, XXIII, d, CR/88"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-25T05:42:52.491103+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=127", "doc_key": "f12564d3d3426caa066ff42f96e39a33"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '8da23fd014affd4c3ce05db03eb695eba96e2fa7a84380974a3cffb3f8510eaa'),
  ('cpiuris2025::821442d00791a0c37cdabf17d8e6f5ce', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade Civil Objetiva por Danos Ambientais', '## Responsabilidade Civil Objetiva por Danos Ambientais

O particular que depara resíduos tóxicos em seu terreno é responsável objetivamente pelos danos sofridos por outras pessoas que entram na propriedade e sofram lesões graves.

### Conceitos
- **Responsabilidade Civil Objetiva**: Obrigação de reparar os danos causados a outrem sem necessidade de prova da culpa ou negligência
- **Danos Ambientais**: Prejuízos causados ao meio ambiente, que podem ser físicos, químicos ou biológicos
- **Lesão ao Meio Ambiente**: Dano causado à natureza ou a seus componentes
- **Conduta Não Dolosa**: Ação não intencional ou negligente que pode gerar danos

### Referências legais
- Art. 26 da Lei nº 6.938/78

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre responsabilidade civil objetiva e dolosa
- Importância de identificar a natureza dos danos ambientais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.127 (2)", "page_number": 127, "discipline": "Direito Administrativo", "legal_refs": ["Art. 26 da Lei nº 6.938/78"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T05:43:41.383596+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=127", "doc_key": "821442d00791a0c37cdabf17d8e6f5ce"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '58c2a33252226b06cbf54cd966ca9714078c00ab598c57697893589892bf7df3'),
  ('cpiuris2025::dc62c9b9ce7035665351d098779885ac', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade Civil do Estado', '## Responsabilidade Civil do Estado

O Estado tem o dever de defender e preservar o meio ambiente ecologicamente equilibrado, e é responsável por indenizar danos causados ao particular, independentemente da obrigação de reparar os danos causados.

### Conceitos
- **Responsabilidade Civil do Estado**: O dever do Estado de defender e preservar o meio ambiente ecologicamente equilibrado
- **Teoria do Risco Social**: Uma especificação da teoria do risco integral, que foca a vítima em vez do autor do dano
- **Socialização dos Riscos**: A ideia de que o Estado deve indenizar danos causados ao particular, independentemente da obrigação de reparar os danos causados

### Referências legais
- Art. 225 do Código Civil Brasileiro
- Lei n.º 14.125/2021

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre responsabilidade civil e socialização dos riscos
