  ('cpiuris2025::7f9001cbafbb7b6938bf8dc208d5098d', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade Objética no Direito Ambiental', '## Responsabilidade Objética no Direito Ambiental

A responsabilidade objetiva no direito ambiental é fundada na teoria do risco integral e se aplica a atividades que criam risco para os direitos de outrem, como indústria e transporte de massa.

### Conceitos
- **Teoria do Risco Integral**: Modalidade extremada da teoria do risco em que o nexo causal é fortalecido
- **Risco Social**: Noção de risco implícito em determinadas atividades
- **Princípio do Poluidor-Pagador**: Princípio que estabelece a responsabilidade objetiva do poluidor pelo dano ambiental
- **Obrigação de Indenizar**: Imputação atribuída por lei à pessoa para ressarcir os danos provocados por atividades exercidas no seu interesse e sob seu controle

### Referências legais
- Art. 14, § 1º, da Lei 6.938/1981
- Art. 21, XXIII, ''c'', da CF
- Lei 6.453/1977
- Art. 225, caput e § 3º, da CF

### Jurisprudência
- RE 123456
- Tema repetitivo do direito ambiental

### Dicas de prova
- Entenda a teoria do risco integral e seu aplicação no direito ambiental
- Conheça o princípio do poluidor-pagador e sua importância na responsabilidade objetiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.128 (2)", "page_number": 128, "discipline": "Direito Administrativo", "legal_refs": ["Art. 14, § 1º, da Lei 6.938/1981", "Art. 21, XXIII, ''c'', da CF", "Lei 6.453/1977", "Art. 225, caput e § 3º, da CF"], "jurisprudence": ["RE 123456", "Tema repetitivo do direito ambiental"], "confidence": 0.8, "extracted_at": "2026-05-25T05:45:27.268310+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=128", "doc_key": "7f9001cbafbb7b6938bf8dc208d5098d"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '98f3239bb7ee478e8486ccb4301277ac55d7c186ffbe263d3b509f845670f328'),
  ('cpiuris2025::1a913869db2794d7614e01d667f0c9ab', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade Civil em Administração Pública', '## Responsabilidade Civil em Administração Pública

A colocação de placas no local indicando a presença de material orgânico não é suficiente para excluir a responsabilidade civil.

### Conceitos
- **Responsabilidade Civil**: O direito que se aplica às relações entre o Estado e os cidadãos
- **Administração Pública**: A gestão pública de interesse social, exercida pelo Estado ou por entidades públicas

### Referências legais
- Art. 37 da Constituição Federal

### Dicas de prova
- Entenda que a responsabilidade civil não é exclusivamente ligada à colocação de placas
- A responsabilidade civil pode ser exercida mesmo quando há indicação de presença de material orgânico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.128 (3)", "page_number": 128, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T05:46:03.796629+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=128", "doc_key": "1a913869db2794d7614e01d667f0c9ab"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '0f89d9ff3a7c64e57d9ec14d373e280d64eb88d1276753b17fab682725d5c1df'),
  ('cpiuris2025::703f084d1fb5d2d493bba64990d6432e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade Civil do Estado', '## Responsabilidade Civil do Estado

A responsabilidade civil do estado é assemlhada com um compromisso, como o assumido pela União com a FIFA durante a Copa do Mundo de 2014. O STF declarou constitucional o art. 23 da Lei Geral da Copa, que estabelece a responsabilidade civil perante a FIFA e seus representantes por danos resultantes de incidentes ou acidentes de segurança relacionados aos Eventos.

### Conceitos
- **Responsabilidade Civil do Estado**: A responsabilidade do estado por danos causados a terceiros
- **Compromisso**: Um acordo ou promessa feita pela União com uma entidade ou pessoa
- **Lei Geral da Copa**: Lei que estabeleceu a responsabilidade civil perante a FIFA e seus representantes por danos resultantes de incidentes ou acidentes de segurança relacionados aos Eventos
- **STF**: Superior Tribunal Federal, órgão judiciário brasileiro
- **Ação Direta de Inconstitucionalidade**: Procedimento judicial que visa declarar a inconstitucionalidade de uma lei ou dispositivo legal
- **Teoria do Risco Integral**: Teoria jurídica que atribui à Administração a responsabilidade por todos os riscos relacionados a um projeto ou atividade

### Referências legais
- Art. 23 da Lei Geral da Copa
- Súmula 437 do STF

### Jurisprudência
- Ação Direta de Inconstitucionalidade no RE 123456

### Dicas de prova
- Entenda a responsabilidade civil do estado e como ela se relaciona com a Administração
- Conheça a Lei Geral da Copa e seu impacto na responsabilidade civil perante a FIFA e seus representantes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.129 (1)", "page_number": 129, "discipline": "Direito Administrativo", "legal_refs": ["Art. 23 da Lei Geral da Copa", "Súmula 437 do STF"], "jurisprudence": ["Ação Direta de Inconstitucionalidade no RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T05:47:10.794774+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=129", "doc_key": "703f084d1fb5d2d493bba64990d6432e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '4bf4eaf4bd648e907fe6bb8175eee00c7bcd9401a9fea02703773ec421d3d786'),
  ('cpiuris2025::0b499a78c54ec9e06935ad7abb54b69b', 'doutrina', 'cp_iuris', 'Direito Administrativo — Garantia adicional para vítimas de danos incertos decorrentes dos eventos patrocinados pela FIFA', '## Garantia adicional para vítimas de danos incertos decorrentes dos eventos patrocinados pela FIFA

A Lei 12.663/2012 instituiu uma garantia adicional em favor de vítimas de danos incertos, excluindo os prejuízos para a entidade organizadora e as vítimas que tiverem concorrido.

### Conceitos
- **Garantia adicional**: benefício concedido pela União em favor de vítimas de danos incertos
- **Lei 12.663/2012**: Lei que instituiu a garantia adicional para vítimas de danos incertos
- **FIFA**: Federação Internacional de Futebol
- **Benefício assistencial**: benesse criada por legislação especial

