  ('cpiuris2025::16cf333f481be78eb1caeb77a907f110', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade Civil do Estado e Teoria do Risco Administrativo', '## Responsabilidade Civil do Estado e Teoria do Risco Administrativo

A responsabilidade civil do Estado não é esgotada pelo artigo 37, §6º, e pode ser ampliada por lei ordinária. A teoria do risco administrativo confere fundamento doutrinário à responsabilização objetiva do Estado, que responde pelos danos causados ao terceiro independente de dolo ou culpa.

### Conceitos
- **Responsabilidade Civil do Estado**: O direito pelo qual o Estado se obriga a reparar os danos causados a terceiros
- **Teoria do Risco Administrativo**: A teoria que confere fundamento doutrinário à responsabilização objetiva do Estado
- **Art. 37, §6º**: O artigo que estabelece a responsabilidade civil do Estado por danos causados a terceiros
- **Excludentes de Responsabilidade**: Caso fortuito e força maior; Culpa Exclusiva de terceiros; Culpa exclusiva da vítima

### Referências legais
- Art. 37, §6º, CR/88
- Art. 43, CC/02

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Ponderação de interesses entre a imunidade da população e os riscos associados às vacinas
- Diferença entre a teoria do risco administrativo e a teoria do risco integral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.130", "page_number": 130, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, §6º, CR/88", "Art. 43, CC/02"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-25T05:49:04.910592+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=130", "doc_key": "16cf333f481be78eb1caeb77a907f110"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'e87f353b15f4a51d6c00c23fe6fb0c1930ede676031bc9667bb15a6c0fe7ca62'),
  ('cpiuris2025::161412751b937599436c65dc3a7511dc', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade Civil do Estado', '## Responsabilidade Civil do Estado

O estado não é responsável por danos causados a menores se não for culpa concorrente dos pais, especialmente se o município promoveu queima de fogos e deixou restos de explosivos sem proteção.

### Conceitos
- **Culpa concorrente**: Fator que reduz a responsabilidade do estado
- **Responsabilidade civil do estado**: Obrigação do estado de reparar danos causados a terceiros
- **Proteção à área pública**: Dever do município de proteger áreas públicas

### Referências legais
- Art. 37, Capítulo III da Constituição Federal
- ...

### Jurisprudência
- RE 123456
- Súmula 7/STJ

