- Distinção entre culpa concorrente e responsabilidade exclusiva do município
- Análise da proteção à área pública e sua relação com a responsabilidade civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.131 (1)", "page_number": 131, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal", "..."], "jurisprudence": ["RE 123456", "Súmula 7/STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T05:49:47.671783+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=131", "doc_key": "161412751b937599436c65dc3a7511dc"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '07d2932c964a208c22993f48e7f47459e247d007c864e797ad5259130bed0908'),
  ('cpiuris2025::47a3d7e77f46bcabda543379a78e8c4f', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade da Concessionária de Rodovia por Roubo e Sequestro', '## Responsabilidade da Concessionária de Rodovia por Roubo e Sequestro

A concessionária de rodovia não é responsável por roubo e sequestro ocorridos em dependências mantidas para o uso dos usuários, pois tais eventos são considerados fortuitos/força maior que rompem o nexo causal.

### Conceitos
- **Responsabilidade Civil**: A responsabilidade do Estado ou de terceiros por danos causados a indivíduos.
- **Concessionária de Rodovia**: Empresa que tem o direito de explorar e gerir uma rodovia, sob a forma de um contrato com o Estado.
- **Fortuito/Força Maior**: Evento imprevisível e alheio à vontade do concessionário que rompe o nexo causal da responsabilidade.
- **Risco Integral**: Teoria que atribui responsabilidade ao Estado ou terceiros por todo e qualquer dano gerado ao particular.

### Referências legais
- Súmula 7/STJ

### Jurisprudência
- REsp 1837378/RO
- REsp 1837378/RO (Tema repetitivo)

### Dicas de prova
- Distinção entre fortuito e força maior
- Entendimento da teoria do risco integral no Direito brasileiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.131 (2)", "page_number": 131, "discipline": "Direito Administrativo", "legal_refs": ["Súmula 7/STJ"], "jurisprudence": ["REsp 1837378/RO", "REsp 1837378/RO (Tema repetitivo)"], "confidence": 0.9, "extracted_at": "2026-05-25T05:50:39.325628+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=131", "doc_key": "47a3d7e77f46bcabda543379a78e8c4f"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '16c94124dd90573cdb90b92e1a03c318ae4677628eaaf7182de41d7677abe6e7'),
  ('cpiuris2025::966c979ccf2ae987b78ec04792b449b6', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade Civil do Estado', '## Responsabilidade Civil do Estado

O Estado é responsável pelos atos ou omissões de seus agentes, independentemente da competência e do horário de expediente. A responsabilidade civil do Estado se estabelece quando há violação de um dever jurídico específico de agir.

### Conceitos
- **Responsabilidade Civil do Estado**: O Estado é responsável pelos atos ou omissões de seus agentes
- **Nexo Causal**: Conexão entre a atividade do agente público e o dano causado
- **Dever Jurídico Específico**: Débito legal de agir ou não agir, que é violado pela conduta do agente público

### Referências legais
- Art. 37, § 6º da CR/88

### Jurisprudência
- STF RE 135.310
- STF ARE 644.395 AgR
- STF RE 160.401
- RE 591874
- REsp 1749941/PR
- RE 580252

### Dicas de prova
- Distinção entre atos e omissões do agente público
- Importância do nexo causal na responsabilidade civil do Estado
- Conceito de dever jurídico específico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.132 (1)", "page_number": 132, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, § 6º da CR/88"], "jurisprudence": ["STF RE 135.310", "STF ARE 644.395 AgR", "STF RE 160.401", "RE 591874", "REsp 1749941/PR", "RE 580252"], "confidence": 0.8, "extracted_at": "2026-05-25T05:51:41.230127+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=132", "doc_key": "966c979ccf2ae987b78ec04792b449b6"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b92b9c69ec15e1127f8d8e0795c44c41aac326edf152976300aad2451f512275'),
  ('cpiuris2025::bf9fe40138354f02b6617bfa910e4597', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade do Estado', '## Responsabilidade do Estado

O Estado responde pela responsabilidade civil objetiva por atividades de risco ''por sua natureza'', como desenvolvimento em edifícios públicos ou com circulação de pessoas notoriamente investigadas.

### Conceitos
- **Responsabilidade do Estado**: obrigação do Estado de reparar os danos causados a terceiros
- **Atividades de risco**: atividades que apresentam um risco anormal por sua natureza
- **Subsidiariamente**: o Estado responde apenas se houver uma relação de causalidade entre o ato do Estado e o dano
- **Perícia técnica**: especialista em um campo específico que avalia os prejuízos econômicos
- **Art. 37, § 6º, da CRFB/88**: leis que regulamentam o concurso público
- **Prescrição**: princípio jurídico que determina a limitação do tempo para a ação
- **Código Civil**: lei que regula as relações civis

### Referências legais
- Art. 37, § 6º, da CRFB/88
- RE 136861
- ARE 884325
- RE 662405
- Art. 927, parágrafo único, do Código Civil

### Jurisprudência
- RE 136861
- ARE 884325
- RE 662405

### Dicas de prova
- Entenda a noção de atividades de risco ''por sua natureza'' e como elas afetam a responsabilidade do Estado
- Conheça as regras de perícia técnica e sua importância na avaliação dos prejuízos econômicos
- Aprenda a aplicação da prescrição no direito administrativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.132 (2)", "page_number": 132, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, § 6º, da CRFB/88", "RE 136861", "ARE 884325", "RE 662405", "Art. 927, parágrafo único, do Código Civil"], "jurisprudence": ["RE 136861", "ARE 884325", "RE 662405"], "confidence": 0.8, "extracted_at": "2026-05-25T05:52:41.555184+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=132", "doc_key": "bf9fe40138354f02b6617bfa910e4597"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'c03d3e100126a65f0c2bedbea60c1119ead8ca26398f34c3655771c0622d124b'),
  ('cpiuris2025::af620a24e80a25fc3ccf6dba3ee542d0', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade Civil do Estado', '## Responsabilidade Civil do Estado

A responsabilidade civil do estado é objetiva e se aplica a profissionais de imprensa feridos por agentes policiais durante cobertura jornalística, especialmente em situações de tumulto ou conflitos. O estado também responde pela omissão quando há precariedade no serviço público.

### Conceitos
- **Responsabilidade Civil do Estado**: O dever do estado de reparar os danos causados por suas ações ou omissões
- **Objetividade**: A responsabilidade civil do estado é objetiva, não dependendo da culpa exclusiva da vítima
- **Culpa Exclusiva**: A vítima não pode ser considerada culpada se for excluída a responsabilidade do estado
- **Omissão**: O estado responde pela omissão quando há precariedade no serviço público

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal
- RE 1209429/SP
- REsp n. 1.708.325/RS
- Súmula 346 do Superior Tribunal de Justiça

### Jurisprudência
- STF, ARE 1.382.159 AgR/RJ
- Excelso Pretório

### Dicas de prova
- Entenda a noção de responsabilidade civil objetiva e sua aplicação nas situações descritas
- Identifique as hipóteses em que o estado é excludido da responsabilidade pela culpa exclusiva da vítima', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.133 (1)", "page_number": 133, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal", "RE 1209429/SP", "REsp n. 1.708.325/RS", "Súmula 346 do Superior Tribunal de Justiça"], "jurisprudence": ["STF, ARE 1.382.159 AgR/RJ", "Excelso Pretório"], "confidence": 0.9, "extracted_at": "2026-05-25T05:53:39.752054+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=133", "doc_key": "af620a24e80a25fc3ccf6dba3ee542d0"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'f2ba3617001c41a142d7641b1f5506a3112d74fa15eaae675cd7555203996ddf'),
  ('cpiuris2025::d45ce93717dbb637a925a3345826dd12', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade do Estado', '## Responsabilidade do Estado

O Estado pode ser responsabilizado civilmente por suas ações, mas há exceções como a causa excludente de responsabilidade e a teoria da interrupção do nexo causal. A última aceita pelo STF e estabelece que o Estado só responde direta e imediatamente após a ação estatal.

### Conceitos
- **Causa Excludente de Responsabilidade**: Exceção que afasta a responsabilidade do Estado
- **Teoria da Interrupção do Nexo Causal**: Teoria que estabelece que o Estado só responde direta e imediatamente após a ação estatal
- **Nexo Causal**: Conexão lógica entre a ação estatal e o dano causado
- **Responsabilidade Civil do Estado**: Obrigação do Estado de reparar os danos causados por suas ações

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal
- Súmula 326 do Supremo Tribunal Federal

### Jurisprudência
- ARE 1.385.315/RJ
- RE 123456

### Dicas de prova
- Entenda a diferença entre causa excludente de responsabilidade e teoria da interrupção do nexo causal
- Conheça a tese de Repercussão Geral do STF sobre a responsabilidade civil do Estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.133 (2)", "page_number": 133, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal", "Súmula 326 do Supremo Tribunal Federal"], "jurisprudence": ["ARE 1.385.315/RJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T05:54:36.820279+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=133", "doc_key": "d45ce93717dbb637a925a3345826dd12"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '0de8259453d944ee7db59a5a78f99a66049b1fa801b01fd469646c62e12ed7f7'),
  ('cpiuris2025::1d47136f20518f6241de6ba786e91cb1', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade Civil do Estado', '## Responsabilidade Civil do Estado

O Estado não é responsável civilmente por danos decorrentes de crimes praticados por pessoas foragidas do sistema prisional, desde que não seja demonstrado um nexo causal direto entre a fuga e a conduta.

### Conceitos
- **Nexo Causal**: Relação de pertencialidade entre os elementos de fato (conduta do agente e resultado danoso)
- **Teoria do Dano Direto e Imediato**: Teoria que admite o nexo de causalidade apenas quando o dano é efeito necessário de uma causa
- **Responsabilidade Civil Objettiva**: Imputação de responsabilidade civil objetiva, que pressupõe a presença de dois elementos de fato (conduta do agente e resultado danoso) e um elemento lógico-normativo (nexo causal)

### Referências legais
- Art. 37, § 6º, da Constituição Federal
- Art. 1.060 do Código Civil

### Jurisprudência
- RE 130.764
- Súmula N do STJ

### Dicas de prova
- Entenda a teoria do nexo causal e sua aplicação na responsabilidade civil do Estado
- Diferencie entre responsabilidade objetiva e subjetiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.134 (1)", "page_number": 134, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, § 6º, da Constituição Federal", "Art. 1.060 do Código Civil"], "jurisprudence": ["RE 130.764", "Súmula N do STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T05:55:27.829659+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=134", "doc_key": "1d47136f20518f6241de6ba786e91cb1"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '859af0a72731f4026e498d9657fbd94859d7c70c30e3a289518f7f441743aa8f'),
  ('cpiuris2025::e7dd7e27719f8f29a69ee5e9806d07f2', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade do Estado por Mortes de Detentos', '## Responsabilidade do Estado por Mortes de Detentos

O STF decidiu que a responsabilização objetiva do Estado somente ocorre quando houver inobservância do dever específico de proteção previsto no art. 5º, inciso XLIX, da Constituição Federal.

### Conceitos
- **Responsabilidade objetiva**: Obrigação do Estado de responder por danos causados à vítima
- **Dever de proteção**: O dever específico do Poder Público de garantir a segurança e o bem-estar dos detentos
- **Nexo de causalidade**: Conexão lógica entre a ação ou omissão do Estado e o resultado danoso

### Referências legais
- Art. 5º, inciso XLIX, da Constituição Federal
- STF - RE 841526/RS
- STJ - REsp 1305259/SC

### Jurisprudência
- RE 608880 - STF
- REsp 858511/ DF - STJ

### Dicas de prova
- Entenda a noção de responsabilidade objetiva e seu escopo
- Conheça o dever de proteção previsto na Constituição Federal
- Identifique o nexo de causalidade entre a ação ou omissão do Estado e o resultado danoso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.134 (2)", "page_number": 134, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º, inciso XLIX, da Constituição Federal", "STF - RE 841526/RS", "STJ - REsp 1305259/SC"], "jurisprudence": ["RE 608880 - STF", "REsp 858511/ DF - STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T05:56:15.671407+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=134", "doc_key": "e7dd7e27719f8f29a69ee5e9806d07f2"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '98a66e8345173af60d860ef3bdd11217644ed1eec233161572e2064b961183b9'),
  ('cpiuris2025::0fb2bcfe5be1547dee73b7151e9db9ca', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade Civil do Estado', '## Responsabilidade Civil do Estado

O Estado é responsável por danos decorrentes de obras públicas e atos de multidões, exceto em casos onde a omissão estatal não configura culpa exclusiva de terceiros.

### Conceitos
- **Dano pelo Simples Fato da Obra**: O Poder Público é responsável por reparar danos sofridos por particulares em razão de obras públicas.
- **Responsabilidade Subsidiária**: O Estado responde subsidiariamente caso o patrimônio da contratada não seja suficiente para pagar a indenização.
- **Dano Resultante do Comportamento Doloso ou Culposo de um Empregado**: O contratado é responsável pelos danos causados diretamente à Administração ou a terceiros em razão da execução do contrato.
- **Dano Resultante de uma Conduta do Estado e da Contratada**: Cada um responde proporcionalmente a suas participações no evento danoso.
- **Omissão Estatal**: A omissão estatal pode configurar culpa exclusiva de terceiros, exceto em casos onde é notória e configura uma conduta previsível e evitável.

### Referências legais
- Art. 120 da Lei n.º 14.133/2021
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo de responsabilidade civil do Estado

### Dicas de prova
- Diferenciar entre dano pelo simples fato da obra e dano resultante do comportamento doloso ou culposo de um empregado.
- Entender a noção de omissão estatal e sua relação com a responsabilidade civil do Estado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.135", "page_number": 135, "discipline": "Direito Administrativo", "legal_refs": ["Art. 120 da Lei n.º 14.133/2021", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo de responsabilidade civil do Estado"], "confidence": 0.8, "extracted_at": "2026-05-25T05:57:28.805710+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=135", "doc_key": "0fb2bcfe5be1547dee73b7151e9db9ca"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '92a82db55c29db5f8060f007463386e2b0813f54a5dcfba2b58ab5e1bedff3bb'),
  ('cpiuris2025::68d592a65993dc7da6cb5fe1912188a2', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade Civil do Estado e Denunciação à Lide', '## Responsabilidade Civil do Estado e Denunciação à Lide

A responsabilidade civil do Estado é protegida pelo art. 37, § 6º da CR/88, que assegura a dupla garantia: a vítima pode ajuizar ação contra o Estado objetivamente, sem comprovação de dolo ou culpa, enquanto o agente causador do dano só responderá por meio de uma ação de regresso. A denunciação à lide é facultativa e não viola a dupla garantia constitucional.

### Conceitos
- **Dupla Garantia**: Assegura a proteção da vítima objetivamente, sem comprovação de dolo ou culpa, enquanto o agente causador do dano só responderá por meio de uma ação de regresso.
- **Denunciação à Lide**: É facultativa e não viola a dupla garantia constitucional, pois permite que a vítima ajuize ação contra o Estado objetivamente, sem comprovação de dolo ou culpa.
- **Responsabilidade Civil do Estado**: É protegida pelo art. 37, § 6º da CR/88 e assegura a dupla garantia: a vítima pode ajuizar ação contra o Estado objetivamente, sem comprovação de dolo ou culpa.

### Referências legais
- Art. 37, § 6º da CR/88

### Jurisprudência
- RE 1027633
- Súmula N do STJ

### Dicas de prova
- Entenda a dupla garantia e a denunciação à lide como facultativa.
- Conheça o art. 37, § 6º da CR/88 e sua aplicação prática na responsabilidade civil do Estado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.136 (1)", "page_number": 136, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, § 6º da CR/88"], "jurisprudence": ["RE 1027633", "Súmula N do STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T05:58:32.689968+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=136", "doc_key": "68d592a65993dc7da6cb5fe1912188a2"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '0d0adfd65b03d683df5c68314cb3a3c85ee22435d606999d35cfddcb7e9f3bf8'),
  ('cpiuris2025::bf69d1461baac560f792aefd9ca893b7', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade Estatal nas Relações de Custoção', '## Responsabilidade Estatal nas Relações de Custoção

A responsabilidade estatal é garantia aos administrados submetidos ao império estatal, contrapeso da supremacia geral do Estado.

### Conceitos
- **Responsabilidade Estatal**: Garantia aos administrados submetidos ao império estatal
- **Sujeição Geral**: Situção em que os administrados estão sujeitos ao Poder Público
- **Poder de Polícia**: Poder do Estado para regular e disciplinar a conduta dos cidadãos

### Referências legais
- Art. 37, Capítulo III da Constituição Federal

### Jurisprudência
- RE 123456
- Súmula 343/STF

### Dicas de prova
- Entenda a noção de sujeição geral e seu impacto na responsabilidade estatal
- Conheça o conceito de poder de polícia e sua relação com a responsabilidade estatal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.136 (2)", "page_number": 136, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal"], "jurisprudence": ["RE 123456", "Súmula 343/STF"], "confidence": 0.8, "extracted_at": "2026-05-25T05:59:07.364195+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=136", "doc_key": "bf69d1461baac560f792aefd9ca893b7"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '32d5f054575ccc7bf14ca84bcb3b3c592d3feb8461f9b2fa52edb8fb16427724'),
  ('cpiuris2025::bd0eccd061e4dabb45806e84e96bf641', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade Civil do Estado', '## Responsabilidade Civil do Estado

A responsabilidade civil do Estado é mais acentuada em relações de custódia, onde o Estado tem o dever de garantir a integridade das pessoas e bens custodiados. A responsabilidade estatal é objetiva, inclusive quanto a atos de terceiros, e pode ser aplicada mesmo que a conduta lesiva não tenha sido praticada por agente público.

### Conceitos
- **Responsabilidade Civil do Estado**: Dever do Estado de indenizar vítimas de dano causado em relações de custódia
- **Custódia**: Relação especial entre o Estado e certas pessoas, como servidores públicos ou presos, com regime disciplinar mais rigoroso
- **Risco Administrativo**: Modalidade da responsabilidade estatal que se aplica em relações de custódia
- **Vigilância e Proteção**: Dever do Estado de garantir a integridade das pessoas e bens custodiados em relações de custódia

### Referências legais
- Art. 5º, XLIX da CF

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Distinção entre responsabilidade civil objetiva e risco administrativo
- Importância da leitura de recentes julgados do STF sobre o tema', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.137 (1)", "page_number": 137, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º, XLIX da CF"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-25T06:00:11.972464+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=137", "doc_key": "bd0eccd061e4dabb45806e84e96bf641"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '6fe66c8f48d8f46f5b6f6896025f84314e09fb515a7f9536e8531878c98afa93'),
  ('cpiuris2025::4c4f750300f20247e51264d1fe2657f8', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade Civil Estatal', '## Responsabilidade Civil Estatal

A responsabilidade civil estatal é limitada à teoria do risco administrativo, que exige nexo de causalidade entre a omissão estatal e o dano sofrido pela vítima. O Estado não é responsável por mortes causadas por fatores naturais ou acidentes, mesmo com precauções.

### Conceitos
- **Teoria do Risco Administrativo**: Exige nexo de causalidade entre a omissão estatal e o dano sofrido pela vítima.
- **Nexo de Causalidade**: Requer que a omissão estatal seja a causa diretamente relacionada ao dano sofrido pela vítima.
- **Responsabilidade Civil Estatal**: Limitada à teoria do risco administrativo e exige nexo de causalidade.

### Referências legais
- Art. 37, § 6º, CF/1988

### Jurisprudência
- 87 STJ.AgRg no REsp 1.305.259-SC

### Dicas de prova
- Entenda a teoria do risco administrativo e o nexo de causalidade.
- Diferencie entre responsabilidade civil estatal e responsabilidade objetiva.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.137 (2)", "page_number": 137, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, § 6º, CF/1988"], "jurisprudence": ["87 STJ.AgRg no REsp 1.305.259-SC"], "confidence": 0.8, "extracted_at": "2026-05-25T06:00:58.710489+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=137", "doc_key": "4c4f750300f20247e51264d1fe2657f8"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '091144b434fef5a321346d4b4709c76e4184a58c26dc3205bf987642d00d973c'),
  ('cpiuris2025::4667f4e1d74c030c94a654eb0345de68', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade Civil do Estado e Prescrição', '## Responsabilidade Civil do Estado e Prescrição

O Estado é responsável civilmente por danos causados por sua omissão ou atuação, mas a prescrição pode ser um impedimento para a ação. A jurisprudência estabelece que os danos morais e materiais decorrentes de perseguição política durante o regime militar são imprescritíveis.

### Conceitos
- **Responsabilidade Civil do Estado**: O Estado é responsável por danos causados por sua omissão ou atuação
- **Prescrição**: Prazo após o qual não pode ser ajuizada uma ação
- **Ação de Regresso**: Ação que busca reparar danos causados ao erário
- **Ação de Indenização**: Ação que busca indenizar o erário por danos causados
- **Imprescritibilidade**: Dano que não pode ser prescrito

### Referências legais
- Art. 37, § 5º da CR/88
- RE 669069/2016
- Súmula 647 do STJ

### Jurisprudência
- RE 841526
- STJ 1.142.245

### Dicas de prova
- Entenda a noção de responsabilidade civil do Estado e como ela se relaciona com a prescrição
- Conheça as exceções à prescrição, como a imprescritibilidade de danos morais e materiais decorrentes de perseguição política', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.138 (1)", "page_number": 138, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, § 5º da CR/88", "RE 669069/2016", "Súmula 647 do STJ"], "jurisprudence": ["RE 841526", "STJ 1.142.245"], "confidence": 0.8, "extracted_at": "2026-05-25T06:01:54.281440+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=138", "doc_key": "4667f4e1d74c030c94a654eb0345de68"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '454367831f9da20e9d64ae43ca3066f7e6635219c7f09368fa15b69875b29b26'),
  ('cpiuris2025::d812fed528e129e07eff093fd1969a13', 'doutrina', 'cp_iuris', 'Direito Administrativo — Imprescritibilidade da pretensão de indenização por dano moral decorrente de atos de tortura', '## Imprescritibilidade da pretensão de indenização por dano moral decorrente de atos de tortura

A pretensão de recebimento de indenização por dano moral decorrente de atos de tortura ocorridos durante o regime militar de exceção é imprescritível.

### Conceitos
- **Imprescritibilidade**: O direito de não ser limitado pelo prazo para ajuizar uma ação
- **Dano moral**: Prejuízo emocional ou psicológico causado por um ato injusto
- **Tortura**: Atos de violência física ou psicológica cometidos contra uma pessoa

### Referências legais
- Art. 5º, caput, inciso III da CF; Art. 197 do CC/2019

### Jurisprudência
- AgRg no AG 1.428.635-BA
- AgRg no AG 1.392.493-RJ
- REsp 1.374.376-CE

### Dicas de prova
- Distinção entre dano moral e outros tipos de danos; Implicação da Constituição Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.138 (2)", "page_number": 138, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º, caput, inciso III da CF; Art. 197 do CC/2019"], "jurisprudence": ["AgRg no AG 1.428.635-BA", "AgRg no AG 1.392.493-RJ", "REsp 1.374.376-CE"], "confidence": 0.8, "extracted_at": "2026-05-25T06:02:42.749753+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=138", "doc_key": "d812fed528e129e07eff093fd1969a13"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'd8f252843bbc3a4dce22264798292bf3178e8531b8395646f7739c0aef66a7c8'),
  ('cpiuris2025::17f9f459f4de36950ec72e740f845210', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade Civil do Estado', '## Responsabilidade Civil do Estado

O Estado é responsável civilmente por atos que causam danos a particulares, incluindo leis de efeitos concretos, leis inconstitucionais e omissão inconstitucional quanto ao dever de legislar.

### Conceitos
- **Lei de Efeitos Concretos**: Lei que atinge um indivíduo específico ou um grupo determinado de pessoas
- **Lei Inconstitucional**: Lei que é incompatível com a Constituição Federal e pode ensejar responsabilidade do Estado
- **Omissão Inconstitucional Quanto ao Dever de Legislar**: Omissão do legislador que ultrapassa os padrões da razoabilidade

### Referências legais
- Art. 206, § 3º, Código Civil de 2002

### Jurisprudência
- STJ. 1ª Turma. AgInt no Resp 2.100.988/PE
- RE 123456

### Dicas de prova
- Diferenciar entre leis de efeitos concretos e leis inconstitucionais
- Comprovar a existência de um dano e o nexo causal para responsabilizar o Estado em casos de lei inconstitucional
- Observar a razoabilidade na omissão do legislador', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.139", "page_number": 139, "discipline": "Direito Administrativo", "legal_refs": ["Art. 206, § 3º, Código Civil de 2002"], "jurisprudence": ["STJ. 1ª Turma. AgInt no Resp 2.100.988/PE", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T06:03:34.383512+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=139", "doc_key": "17f9f459f4de36950ec72e740f845210"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '84c867670bbb1a8bb9e74397c84e1674ef942fa034373498272e485086a8e8a6'),
  ('cpiuris2025::3bf287a6d35cbf71b79bcb3b8c5a1aee', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade Civil do Estado', '## Responsabilidade Civil do Estado

A responsabilidade civil do estado é estabelecida pelo art. 37, § 6º da CR/88 e se aplica a atos administrativos de apoio praticados no Judiciário, bem como a atividade jurisdicional que não seja independente funcional do magistrado.

### Conceitos
- **Responsabilidade Civil do Estado**: A responsabilidade estatal por atos administrativos de apoio e atividade jurisdicional
- **Independência Funcional**: A capacidade do magistrado de julgar uma mesma causa de forma independente
- **Dolo no Exercício da Função**: O ato do magistrado com dolo no exercício da sua função pode ensejar a responsabilidade estatal
- **Conduta Culposa**: A conduta culposa pode ensejar a responsabilidade estatal, especialmente em ações de natureza penal
- **Atos Jurisdicionais e Funcionais**: Os atos do juiz podem ser classificados como jurisdicionais ou funcionais, com diferentes níveis de responsabilidade estatal

### Referências legais
- Art. 37, § 6º da CR/88
- Art. 143 do CPC

### Jurisprudência
- RE 123456
- Tema repetitivo ...
- Súmula N STF

