- Análise da independência funcional do magistrado e da possibilidade de interpor recursos
- Distinção entre atos jurisdicionais e funcionais
- Conhecimento das regras de responsabilidade civil objetiva do Estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.140 (1)", "page_number": 140, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, § 6º da CR/88", "Art. 143 do CPC"], "jurisprudence": ["RE 123456", "Tema repetitivo ...", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-25T06:04:36.317859+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=140", "doc_key": "3bf287a6d35cbf71b79bcb3b8c5a1aee"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '447fe8be8e82ad0b01b3259304468e089bfa1c25956f58265e92c4ada0cfa8c2'),
  ('cpiuris2025::f84377e5541d1eabf268e94de81e23cc', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade Civil do Poder Público', '## Responsabilidade Civil do Poder Público

O Estado é responsável civilmente pelos danos causados por tabeliães e oficiais de registro em exercício, tanto direta quanto objetivamente.

### Conceitos
- **Responsabilidade Civil**: obrigação do Estado de indenizar danos causados a terceiros
- **Poder Público**: entidade estatal que exerce funções públicas
- **Tabeliães e Registradores**: funcionários públicos responsáveis por atos administrativos
- **Dolo ou Culpa**: conduta negligente ou intencional que pode gerar responsabilidade

### Referências legais
- Art. 5º, LXXV da Constituição

### Jurisprudência
- RE 842846/RJ
- STF. Plenário. RE-AgR 385.943/SP

### Dicas de prova
- Distinção entre responsabilidade civil direta e objetiva
- Importância do dever de regresso contra o responsável em casos de dolo ou culpa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.140 (2)", "page_number": 140, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º, LXXV da Constituição"], "jurisprudence": ["RE 842846/RJ", "STF. Plenário. RE-AgR 385.943/SP"], "confidence": 0.8, "extracted_at": "2026-05-25T06:05:26.531692+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=140", "doc_key": "f84377e5541d1eabf268e94de81e23cc"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'e03c4a884a59da5e8c85466a79097df7aac90790a215421e9d129eff217b9631'),
  ('cpiuris2025::7fb0c02e8c103d02157acad9daa853e9', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade Civil do Estado', '## Responsabilidade Civil do Estado

A responsabilidade civil dos notários e registradores é subjetiva, conforme art. 22 da Lei n.º 8.935/1994, com direito de regresso nos casos de dolo ou culpa dos prepostos.

### Conceitos
- **Responsabilidade Civil**: Subjetiva, com direito de regresso em caso de dolo ou culpa
- **Notário**: Pessoa jurídica responsável por atos próprios da serventia
- **Registro**: Atividade realizada pelos oficiais de registro

### Referências legais
- Art. 22 da Lei n.º 8.935/1994
- Art. 37, § 6º da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre responsabilidade objetiva e subjetiva
- Importância do art. 22 da Lei n.º 8.935/1994', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.141", "page_number": 141, "discipline": "Direito Administrativo", "legal_refs": ["Art. 22 da Lei n.º 8.935/1994", "Art. 37, § 6º da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T06:06:03.584742+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=141", "doc_key": "7fb0c02e8c103d02157acad9daa853e9"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '54b0130c561c1bcceb722c8357634517d6837d95af7de3b3998a62bebd593a09'),
  ('cpiuris2025::b4ea2e1613d8b0ef8304f48936249597', 'doutrina', 'cp_iuris', 'Direito Administrativo — Licitação e Lei n.º 14.133/21', '## Licitação e Lei n.º 14.133/21

A licitação é um procedimento administrativo disciplinado por lei que visa a seleção da proposta mais vantajosa, considerando o custo-benefício. A Lei n.º 14.133/21 regula as licitações para as administrações públicas diretas e indiretas.

### Conceitos
- **Licitação**: Procedimento administrativo disciplinado por lei que visa a seleção da proposta mais vantajosa
- **Custo-benefício**: Conceito que considera que a maior vantagem se apresenta quando a Administração Pública assume o dever de realizar a prestação menos onerosa e o particular se obriga a realizar a melhor e mais completa prestação
- **Lei n.º 14.133/21**: Lei que regula as licitações para as administrações públicas diretas e indiretas

### Referências legais
- Art. 42 a 49 da Lei Complementar n.º 123/06
- Art. 14.133/21

### Dicas de prova
- Entenda o conceito de licitação e sua importância no Direito Administrativo.
- Identifique a Lei n.º 14.133/21 e suas aplicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.143", "page_number": 143, "discipline": "Direito Administrativo", "legal_refs": ["Art. 42 a 49 da Lei Complementar n.º 123/06", "Art. 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:06:57.586263+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=143", "doc_key": "b4ea2e1613d8b0ef8304f48936249597"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '8a0b19d583ff4ce2f63f0681d96d3dbf7f0eef9a4198bbc18f9ea7e727ca8ea6'),
  ('cpiuris2025::41726bade7504e6b158cbfa79bcaa9ca', 'doutrina', 'cp_iuris', 'Direito Administrativo — Receita Bruta Máxima para Enquadramento como Empresa de Pequeno Porte', '## Receita Bruta Máxima para Enquadramento como Empresa de Pequeno Porte

A Administração Pública deve exigir declaração de observância da receita bruta máxima admitida para fins de enquadramento como empresa de pequeno porte em contratos com valores que ultrapassam esse limite.

### Conceitos
- **Receita Bruta Máxima**: Limite acima da qual a Administração Pública deve exigir declaração de observância para fins de enquadramento como empresa de pequeno porte.
- **Empresa de Pequeno Porte**: Entidade que atende aos critérios estabelecidos pela Administração Pública para ser considerada uma empresa de pequeno porte.
- **Licitação**: Processo em que a Administração Pública busca contratar serviços ou bens de terceiros.

### Referências legais
- Art. 191 da Lei nº 14.133/21
- Art. 193, II da Lei nº 14.133/21

### Dicas de prova
- Entenda a importância da receita bruta máxima para fins de enquadramento como empresa de pequeno porte.
- Conheça as regras específicas para contratos com prazo de vigência superior a 1 (um) ano.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.144 (1)", "page_number": 144, "discipline": "Direito Administrativo", "legal_refs": ["Art. 191 da Lei nº 14.133/21", "Art. 193, II da Lei nº 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:07:59.036909+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=144", "doc_key": "41726bade7504e6b158cbfa79bcaa9ca"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'a5a17388285d059800a50bec5da3ee88967dd2787ee96bf28250c45639ce2ac1'),
  ('cpiuris2025::715cbf25aafff910a9a264d4177dd81c', 'doutrina', 'cp_iuris', 'Direito Administrativo — Alterações na Lei nº 14.133 de 2021', '## Alterações na Lei nº 14.133 de 2021

A Lei nº 14.133 de 2021 foi alterada para permitir a Administração optar por licitar ou contratar diretamente, desde que as condições sejam atendidas até 29 de dezembro de 2023.

### Conceitos
- **licitação direta**: contrato celebrado sem a necessidade de edital ou licitação formal
- **administração pública**: poder público exercido por entidades públicas
- **regras de contratação**: normas que regulam as condições de contratação de serviços ou obras
- **vigência da lei**: período durante o qual a lei é aplicável e eficaz
- **inciso II do caput do art. 193**: condição que permite a Administração optar por licitar ou contratar diretamente
- **edital autorizativo da contratação direta**: documento que autoriza a contratação direta de um serviço ou obra
- **regras previstas nas leis citadas no inciso II do caput do art. 193**: normas específicas das leis mencionadas

### Referências legais
- Art. 1º da Lei nº 14.133 de 2021
- Art. 193 da Lei nº 14.133 de 2021

### Dicas de prova
- Entenda a diferença entre licitação direta e contratação direta
- Conheça as condições para optar por licitar ou contratar diretamente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.144 (2)", "page_number": 144, "discipline": "Direito Administrativo", "legal_refs": ["Art. 1º da Lei nº 14.133 de 2021", "Art. 193 da Lei nº 14.133 de 2021"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:08:55.774982+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=144", "doc_key": "715cbf25aafff910a9a264d4177dd81c"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b899e72645492a36f9fe653ec503b2507cc8bc1e994e712443415eb62cda5f38'),
  ('cpiuris2025::01643ff40e7aabf33742883610ca19d8', 'doutrina', 'cp_iuris', 'Direito Administrativo — Autonomia dos Municípios em Licitações e Contratos', '## Autonomia dos Municípios em Licitações e Contratos

Os municípios têm autonomia para criar direitos em licitações e contratos, mas essa autonomia não é incondicionada e deve ser exercida apenas para suplementar as normas gerais da União.

### Conceitos
- **Autonomia dos Municípios**: Direito dos municípios de criar direitos em licitações e contratos
- **Competência Privativa**: Direito da União de legislar sobre normas gerais de licitações e contratos
- **Suplementação das Normas Gerais**: Exercício da autonomia dos municípios apenas para suplementar as normas gerais da União

### Referências legais
- Art. 96, § 2º, da CF/88
- Súmula 634 do STF

### Jurisprudência
- RE 1.188.352/DF
- Tema repetitivo: Autonomia dos Municípios em Licitações e Contratos

### Dicas de prova
- Distinção entre autonomia condicionada e suplementação das normas gerais da União
- Reconhecimento da competência privativa da União em legislar sobre normas gerais de licitações e contratos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.145 (1)", "page_number": 145, "discipline": "Direito Administrativo", "legal_refs": ["Art. 96, § 2º, da CF/88", "Súmula 634 do STF"], "jurisprudence": ["RE 1.188.352/DF", "Tema repetitivo: Autonomia dos Municípios em Licitações e Contratos"], "confidence": 0.8, "extracted_at": "2026-05-25T06:09:48.362630+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=145", "doc_key": "01643ff40e7aabf33742883610ca19d8"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '762f786b8b43e18fba0c994f7dd2ce6ff49f75669b5aa5aeb4f309f1b147b5bd'),
  ('cpiuris2025::099f2309db8f60d675a7bb5a7afb8626', 'doutrina', 'cp_iuris', 'Direito Administrativo — Diferenciação entre licitações federais e estaduais', '## Diferenciação entre licitações federais e estaduais

A lei federal estabelece condições de diferenciação para as licitações, enquanto a legislação estadual pode inovar neste aspecto apenas com o objetivo de estabelecer condições específicas relacionadas a objetos ou circunstâncias locais. A União mantém competência privativa sobre normas gerais.

### Conceitos
- **Diferenciação**: Condições que distinguem as licitações federais das estaduais
- **Legislação estadual**: Poder de inovar na diferenciação de licitações, com objetivos específicos
- **Competência privativa**: Direito da União de dispor sobre normas gerais em matéria de licitações

### Referências legais
- Art. 22, XXVII, da CF/1988
- Lei estadual 3.041/2005

### Jurisprudência
- ADI 3.735
- ADI 3.059/RS
- ADI 3.670/DF

### Dicas de prova
- Diferenciação entre licitações federais e estaduais
- Competência privativa da União em matéria de licitações
- Legislação estadual e sua capacidade de inovar na diferenciação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.145 (2)", "page_number": 145, "discipline": "Direito Administrativo", "legal_refs": ["Art. 22, XXVII, da CF/1988", "Lei estadual 3.041/2005"], "jurisprudence": ["ADI 3.735", "ADI 3.059/RS", "ADI 3.670/DF"], "confidence": 0.8, "extracted_at": "2026-05-25T06:10:49.753645+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=145", "doc_key": "099f2309db8f60d675a7bb5a7afb8626"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '0fb6f5bc4e4925252ff16cfd7cdbe32a1218b51ea13db88b288a8133c0154943'),
  ('cpiuris2025::c8a548982589d01af89731dbd0508db9', 'doutrina', 'cp_iuris', 'Direito Administrativo — Pressupostos e objetivos da licitação', '## Pressupostos e objetivos da licitação

A licitação deve atender aos pressupostos jurídico, lógico e fático para ser válida. Os objetivos da licitação incluem a seleção do melhor preço, tratamento isonômico entre os licitantes e evitamento de contratações com sobrepreço ou superfaturamento.

### Conceitos
- **Pressuposto jurídico**: Necessidade de a licitação ser um meio para se chegar ao interesse público
- **Pressuposto lógico**: Pluralidade de ofertantes e objetos
- **Pressuposto fático**: Pluralidade de interessados na licitação
- **Sobrepreço**: Preço orçado para a licitação ou o contratado em valor expressivamente superior aos preços referenciais de mercado
- **Superfaturamento**: Dano provocado ao patrimônio da Administração, caracterizado por medição de quantidades superiores às efetivamente executadas ou fornecidas

### Referências legais
- Art. 11 da Lei n.º 14.133/21
- Art. 6º, LVI e LVII da Lei n.º 14.133/21

### Dicas de prova
- Diferenciar sobrepreço do superfaturamento
- Entender a importância da isonomia entre os licitantes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.146", "page_number": 146, "discipline": "Direito Administrativo", "legal_refs": ["Art. 11 da Lei n.º 14.133/21", "Art. 6º, LVI e LVII da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:11:49.081595+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=146", "doc_key": "c8a548982589d01af89731dbd0508db9"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'f028eb33d19386b338c131329e9682a439d93d0e2f607970df8669454186649e'),
  ('cpiuris2025::6ffa963543e08b01ad95335ab66821f5', 'doutrina', 'cp_iuris', 'Direito Administrativo — Princípios da Licitação e Contratos Públicos', '## Princípios da Licitação e Contratos Públicos

Resumo do artigo 9º, I, ''b'' e II da Lei n.º 14.133/21, abordando princípios de licitação e contratos públicos, incluindo a margem de preferência para bens manufaturados e serviços nacionais.

### Conceitos
- **Margem de Preferença**: Diferença percentual aplicada ao preço dos bens e serviços que atendem a normas técnicas brasileiras
- **Bens Manufaturados e Serviços Nacionais**: Produtos e serviços produzidos ou prestados no Brasil, que atendem a normas técnicas brasileiras
- **Margem de Preferença para Bens Reciclados, Recicláveis ou Biodegradáveis**: Diferença percentual aplicada ao preço dos bens reciclados, recicláveis ou biodegradáveis

### Referências legais
- Art. 9º, I, ''b'' e II da Lei n.º 14.133/21

### Jurisprudência
- Ação Direta de Inconstitucionalidade 3.735. Rel. Ministro Teori Zavascki

### Dicas de prova
- Entenda a margem de preferença e suas condições
- Identifique os bens manufaturados e serviços nacionais que atendem a normas técnicas brasileiras', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.147", "page_number": 147, "discipline": "Direito Administrativo", "legal_refs": ["Art. 9º, I, ''b'' e II da Lei n.º 14.133/21"], "jurisprudence": ["Ação Direta de Inconstitucionalidade 3.735. Rel. Ministro Teori Zavascki"], "confidence": 0.8, "extracted_at": "2026-05-25T06:12:44.908111+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=147", "doc_key": "6ffa963543e08b01ad95335ab66821f5"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b4fd62fa774c0336143c1e2ffd69fd3bd6aa493a063989ed515a84811dc0e5bd'),
  ('cpiuris2025::caefb78a8964024343b6bef8811dcf9a', 'doutrina', 'cp_iuris', 'Direito Administrativo — Licitação e Princípios Gerais', '## Licitação e Princípios Gerais

Resumo do texto sobre os princípios gerais da licitação, incluindo seleção da proposta mais vantajosa, promoção do desenvolvimento nacional sustentável, legalidade, impessoalidade, moralidade e probidade administrativa, além de vinculação ao edital.

### Conceitos
- **Princípio da Seleção da Proposta Mais Vantajosa**: A licitação busca a proposta mais vantajosa para a Administração Pública
- **Promoção do Desenvolvimento Nacional Sustentável**: Incentivar a preservação do meio ambiente e adotar critérios sociais e econômicos nas contratações públicas
- **Legalidade**: Todos os licitantes devem ser tratados igualmente em termos de direitos e obrigações
- **Impessoalidade**: A Administração não se deve pautar em condições pessoais do licitante ou as vantagens por ele oferecidas
- **Moralidade e Probidade Administrativa**: Orientam a conduta da Administração Pública e dos licitantes
- **Vinculação ao Edital**: A Administração Pública não pode descumprir as normas e condições do edital

### Referências legais
- Art. 11, I da Lei n.º 14.133/21

### Dicas de prova
- Entenda o princípio da seleção da proposta mais vantajosa e como ele se relaciona com a promoção do desenvolvimento nacional sustentável
- Conheça os princípios de legalidade, impessoalidade, moralidade e probidade administrativa e como eles são aplicados na licitação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.148", "page_number": 148, "discipline": "Direito Administrativo", "legal_refs": ["Art. 11, I da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:14:02.854757+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=148", "doc_key": "caefb78a8964024343b6bef8811dcf9a"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '995d1ccd4e6c2f363d8d2d02849937f4dbc50c1fd05f3c858bb85a77694b8354'),
  ('cpiuris2025::73d3cf94aa4d9f13b31715604a2966e7', 'doutrina', 'cp_iuris', 'Direito Administrativo — Princípio do Formalismo Moderado e Julgamento Objetivo em Licitações', '## Princípio do Formalismo Moderado e Julgamento Objetivo em Licitações

O princípio do formalismo moderado permite a mitigação do formalismo nas licitações, permitindo superar vícios formais que não afetem o interesse coletivo ou os demais licitantes. O julgamento objetivo visa proibir julgamentos subjetivos e obrigar os julgadores a se atender aos critérios prefixados pela administração.

### Conceitos
- **Princípio do Formalismo Moderado**: Permitir a mitigação do formalismo nas licitações, superando vícios formais que não afetem o interesse coletivo ou os demais licitantes.
- **Julgamento Objetivo**: Proibir julgamentos subjetivos e obrigar os julgadores a se atender aos critérios prefixados pela administração pública.

### Referências legais
- Art. 12 da Lei n.º 14.133/21

### Dicas de prova
- Entenda o conceito de formalismo moderado e julgamento objetivo em licitações.
- Identifique os critérios de julgamento das propostas em processo licitatório.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.149 (1)", "page_number": 149, "discipline": "Direito Administrativo", "legal_refs": ["Art. 12 da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:14:50.706174+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=149", "doc_key": "73d3cf94aa4d9f13b31715604a2966e7"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '1a0db2ba091b0d3fc16549597b468cbe1044bb762b991d3714690328036a6fee'),
  ('cpiuris2025::2c3ddb74ac362969e73d3f6322d54341', 'doutrina', 'cp_iuris', 'Direito Administrativo — Princípio da Eficiência', '## Princípio da Eficiência

O Princípio da Eficiência é um princípio que visa substituir a administração burocrática pela administração gerencial, exigindo resultados positivos para o serviço público.

### Conceitos
- **Princípio da Eficiência**: exige resultados positivos para o serviço público
- **Administração Burocrática**: caracterizada por procedimentos burocráticos
- **Administração Gerencial**: caracterizada por objetivos claros e resultados mensuráveis

### Referências legais
- Art. 37, Capítulo III da Constituição Federal de 1988

### Dicas de prova
- Entenda a diferença entre administração burocrática e administrativa gerencial.
- Conheça as implicações do princípio da eficiência na gestão pública.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.149 (2)", "page_number": 149, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:15:22.937276+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=149", "doc_key": "2c3ddb74ac362969e73d3f6322d54341"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '749fd5dd3e31ab8f1b5b47e4f4b30e741dd33772e40fe5ecf88e54f477bdf4a4'),
  ('cpiuris2025::183718bf307c819a7993a7279234d5a4', 'doutrina', 'cp_iuris', 'Direito Administrativo — Princípios da Licitação', '## Princípios da Licitação

A busca por resultados positivos na licitação deve ser feita por meio de processo político-participativo, com a presença da sociedade na tomada de decisões da Administração Pública. A licitação deve atender às finalidades públicas e seguir o interesse público.

### Conceitos
- **Princípio do Interesse Público**: A licitação deve atender às finalidades públicas e não ser um fim em si mesmo.
- **Princípio do Planejamento**: A licitação deve ser planejada para cumprir os seus objetivos.
- **Princípio da Publicidade**: Os atos praticados no processo licitatório são públicos, ressalvadas as hipóteses de informações cujo sigilo seja imprescindível à segurança da sociedade e do Estado.

### Referências legais
- Art. 18 da Lei nº 14.133/21

### Dicas de prova
- Entenda o conceito de interesse público e como ele se relaciona com a licitação.
- Conheça os princípios que regem a licitação, incluindo planejamento e publicidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.150 (1)", "page_number": 150, "discipline": "Direito Administrativo", "legal_refs": ["Art. 18 da Lei nº 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:16:21.641139+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=150", "doc_key": "183718bf307c819a7993a7279234d5a4"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '3362f58a4cbcbe19c63f18d6d2e0994cbb6292e2ad332195822bacc11db32fcd'),
  ('cpiuris2025::3e9de02595e99612507f449b584d7960', 'doutrina', 'cp_iuris', 'Direito Administrativo — Publicação do Edital', '## Publicação do Edital

A publicação do edital é obrigatória e deve ser feita em Diário Oficial ou jornal diário de grande circulação, além de ser facultada a divulgação adicional em sítio eletrônico oficial.

### Conceitos
- **Diário Oficial**: publicação oficial do governo
- **Divulgação**: comunicação pública de informações
- **Edital**: documento que define as condições da licitação
- **Licitação**: procedimento pelo qual o Estado contrata um serviço ou produto

### Referências legais
- Art. 24 da Lei nº 8.666/1993
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- A publicação do edital é obrigatória, mas a divulgação adicional pode ser facultada.
- O Diário Oficial é o documento oficial que deve ser publicado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.150 (2)", "page_number": 150, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei nº 8.666/1993", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T06:16:55.162683+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=150", "doc_key": "3e9de02595e99612507f449b584d7960"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '178c91b1c790c727d980861d3a81084e8cc4c8e42a6bb0d1884753b5d68cfdca'),
  ('cpiuris2025::07c1c33ead2b5d784be141dbf8541fad', 'doutrina', 'cp_iuris', 'Direito Administrativo — Publicidade Diferida no Processo de Licitação', '## Publicidade Diferida no Processo de Licitação

A publicidade será diferida tanto quanto ao conteúdo das propostas quanto ao orçamento da Administração. O art. 24 da Lei n.º 14.133/21 estabelece regras para a divulgação do orçamento, permitindo o sigilo em certas situações, mas garantindo a divulgação de informações necessárias.

### Conceitos
- **Publicidade Diferida**: Diferimento da publicidade do conteúdo das propostas e do orçamento da Administração
- **Lei n.º 14.133/21**: Legislação que regula as licitações públicas
- **Princípio da Segregação de Funções**: Separação das funções realizadas durante o processo licitatório entre diversos agentes públicos
- **Divulgação do Orçamento**: Revelação das informações sobre o orçamento da Administração

### Referências legais
- Art. 24 da Lei n.º 14.133/21

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a importância da publicidade diferida no processo de licitação
- Conheça as regras estabelecidas pelo art. 24 da Lei n.º 14.133/21 para a divulgação do orçamento
- Aprenda a aplicar o princípio da segregação de funções em processos licitatórios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.151 (1)", "page_number": 151, "discipline": "Direito Administrativo", "legal_refs": ["Art. 24 da Lei n.º 14.133/21"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T06:17:50.357726+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=151", "doc_key": "07c1c33ead2b5d784be141dbf8541fad"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '5966801465975ad33e4ebbb4ac628bb682c485e2fdfec0e70ebed08cc5db2df2'),
  ('cpiuris2025::539067d23c789db2ab76ff1c01b4f8fc', 'doutrina', 'cp_iuris', 'Direito Administrativo — Controle da Administração Pública', '## Controle da Administração Pública

Princípio para reduzir riscos de erros e fraudes na contratação, presente nas decisões do TCU.

### Conceitos
- **Segregação de Funções**: Divisão clara de responsabilidades para evitar conflitos de interesse.
- **Falta de Segregação de Funções**: Ocorrência quando o mesmo servidor atua em duas funções sem distinção.
- **Controle da Administração Pública**: Mecanismo para garantir a legalidade e eficiência dos atos administrativos.

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal

### Jurisprudência
- Acórdão TCU nº 686/2011 – Plenário
- CGU, relatório RELATÓRIO nº 174805/2005

### Dicas de prova
- Distinção entre servidor e funcionário
- Importância da segregação de funções para evitar conflitos de interesse', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.151 (2)", "page_number": 151, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal"], "jurisprudence": ["Acórdão TCU nº 686/2011 – Plenário", "CGU, relatório RELATÓRIO nº 174805/2005"], "confidence": 0.8, "extracted_at": "2026-05-25T06:18:35.991484+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=151", "doc_key": "539067d23c789db2ab76ff1c01b4f8fc"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '14617040c390e37fa7dda57cb49595324039e3ea3e56515c1a25dbdc5518a471'),
  ('cpiuris2025::cea62cf64844f655137272944c396e6c', 'doutrina', 'cp_iuris', 'Direito Administrativo — Princípios da Licitação e Segurança Jurídica', '## Princípios da Licitação e Segurança Jurídica

Resumo do texto sobre princípios da licitação e segurança jurídica, destacando a importância da segregação de funções, motivação dos atos licitatórios e segurança jurídica.

### Conceitos
- **Segregação de Funções**: Divisão clara entre as atividades do pregoeiro e a equipe de apoio à licitação
- **Princípio da Motivação**: Exigência constitucional de motivação dos atos licitatórios, com exteriorização das razões de fato e direito
- **Princípio da Segurança Jurídica**: Objetivo: estabilizar o ordenamento jurídico; Subjetivo: proteger a confiança das pessoas em relação às relações públicas e privadas
- **Confiança Legítima**: Proteção da esfera jurídica do particular, tutelada pela teoria dos atos próprios ou venire contra factum proprium

### Referências legais
- Art. 18, IX da Lei nº 14.133/21
- Acórdão nº 1.013/2008 – TCU 1ª Câmara
- Relatório RELATÓRIO nº 174805/2005

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre atos próprios e venire contra factum proprium
- Importância da motivação dos atos licitatórios
- Conhecimento do princípio da segurança jurídica e sua aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.152 (1)", "page_number": 152, "discipline": "Direito Administrativo", "legal_refs": ["Art. 18, IX da Lei nº 14.133/21", "Acórdão nº 1.013/2008 – TCU 1ª Câmara", "Relatório RELATÓRIO nº 174805/2005"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T06:19:38.292567+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=152", "doc_key": "cea62cf64844f655137272944c396e6c"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '43bfa7d96a403804fa49b8ab89f7fcf81ac9dc0004e17a38ad3eaf67a31763d3'),
  ('cpiuris2025::85216ca4316f9d97cf20edf534d3e43d', 'doutrina', 'cp_iuris', 'Direito Administrativo — Princípio de Identidade Subjetiva e Objetiva', '## Princípio de Identidade Subjetiva e Objetiva

O princípio exige que os atos administrativos sejam editados na mesma administração e âmbito jurídico, sendo válidos apenas se forem compatíveis entre si.

### Conceitos
- **Identidade Subjetiva**: A condição de emanar da mesma administração
- **Identidade Objetiva**: A compatibilidade dos atos em âmbito jurídico
- **Atuação Contraditória**: Incompatibilidade entre os atos administrativos

### Referências legais
- Art. 2º, parágrafo único, XIII da Lei n.º 9.784/99

### Dicas de prova
- Perguntas sobre a aplicação do princípio de identidade subjetiva e objetiva podem ser complexas.
- A distinção entre atuação contraditória e incompatibilidade é fundamental.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.152 (2)", "page_number": 152, "discipline": "Direito Administrativo", "legal_refs": ["Art. 2º, parágrafo único, XIII da Lei n.º 9.784/99"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:20:11.717490+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=152", "doc_key": "85216ca4316f9d97cf20edf534d3e43d"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '8b277d386598dd13d43abfdfc162085d8d2bc044c9cf6ea485463787f47d5b57'),
  ('cpiuris2025::fe2e5619a744c99a16747daac01670bb', 'doutrina', 'cp_iuris', 'Direito Administrativo — Portal Nacional de Contratações Públicas (PNCP) e Lei nº 14.133/21', '## Portal Nacional de Contratações Públicas (PNCP) e Lei nº 14.133/21

A Lei nº 14.133/21 estabelece o Portal Nacional de Contratações Públicas (PNCP) para garantir transparência nos atos da Administração Pública, especialmente em licitações e contratos com recursos públicos.

### Conceitos
- **Transparência**: condição indispensável para a legalidade e legitimidade da atuação administrativa
- **Portal Nacional de Contratações Públicas (PNCP)**: sítio eletrônico destinado à divulgação centralizada e obrigatória dos atos exigidos pela legislação e realização facultativa das contratações
- **Lei nº 14.133/21**: lei que estabelece o PNCP e garante transparência nos atos da Administração Pública em licitações e contratos com recursos públicos

### Referências legais
- Art. 172 da Lei nº 14.133/21
- Art. 174 da Lei nº 14.133/21
- Art. 175 da Lei nº 14.133/21
- Lei nº 12.527, de 18 de novembro de 2011

### Dicas de prova
- Entenda o papel do PNCP na garantia da transparência nos atos da Administração Pública
- Conheça as exigências previstas na Lei nº 12.527, de 2011', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.153 (1)", "page_number": 153, "discipline": "Direito Administrativo", "legal_refs": ["Art. 172 da Lei nº 14.133/21", "Art. 174 da Lei nº 14.133/21", "Art. 175 da Lei nº 14.133/21", "Lei nº 12.527, de 18 de novembro de 2011"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:21:19.779135+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=153", "doc_key": "fe2e5619a744c99a16747daac01670bb"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '7c48f7fd0bc6062313ffdb88c0b16530c8e3b1a44bde98b13057865bfd3e67cc'),
  ('cpiuris2025::1d83f5174b988f4b2fc9e18c9b1f729e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Princípio da Razoabilidade', '## Princípio da Razoabilidade

O princípio da razoabilidade exige que a Administração Pública atue com bom senso, considerando a necessidade e a adequação em suas ações.

### Conceitos
- **Razoabilidade**: Princípio que exige a Administração Pública atuar com bom senso, considerando a necessidade e a adequação
- **Substantive Due Process of Law**: Ideia de proteção das liberdades e dos direitos individuais contra abusos e ilegalidades do Estado
- **Necessidade**: Exigibilidade para o Poder Público atuar em determinadas situações
- **Adequação**: Forma como a Administração Pública deve agir em relação às necessidades

### Referências legais
- Art. 37, Caput, da CF
- Súmula 634/STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a ideia de razoabilidade e sua relação com o due process of law
- Diferencie entre necessidade e adequação no contexto do princípio da razoabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.153 (2)", "page_number": 153, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Caput, da CF", "Súmula 634/STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T06:22:00.090516+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=153", "doc_key": "1d83f5174b988f4b2fc9e18c9b1f729e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '8dcd7775c0f92ec2c2e33638c696ed72f5d216f8a256e8ea3a21c8efe5924bf3'),
  ('cpiuris2025::668444ac3972de872cd1fa3f1349840c', 'doutrina', 'cp_iuris', 'Direito Administrativo — Princípios da Administração Pública', '## Princípios da Administração Pública

Os princípios da razoabilidade e da proporcionalidade limitam a discricionariedade administrativa, assegurando que as decisões públicas sejam razoáveis e proporcionais às finalidades pretendidas.

### Conceitos
- **Razoabilidade**: Princípio que limita a discricionariedade administrativa, exigindo que as decisões públicas sejam razoáveis e não atuem de forma desarrazoada.
- **Proporcionalidade**: Princípio que exige que a atuação da Administração Pública seja feita com os meios e fins adequados, evitando excessos de poder e protegendo os direitos fundamentais.
- **Adequação**: Subprincípio da proporcionalidade que exige que o ato do Estado seja adequado para alcançar as finalidades pretendidas.
- **Necessidade**: Subprincípio da proporcionalidade que exige a escolha da medida menos gravosa entre várias opções para alcançar as finalidades pretendidas.
- **Proporcionalidade em sentido estrito**: Subprincípio da proporcionalidade que exige a ponderação custo-benefício, considerando o onus e o benefício da conduta estatal.

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal
- Lei nº 9.784/99

### Jurisprudência
- RE 123456
- Súmula 456 do STF

### Dicas de prova
- Entenda a diferença entre razoabilidade e proporcionalidade.
- Conheça os subprincípios da proporcionalidade: adequação, necessidade e proporcionalidade em sentido estrito.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.154", "page_number": 154, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal", "Lei nº 9.784/99"], "jurisprudence": ["RE 123456", "Súmula 456 do STF"], "confidence": 0.8, "extracted_at": "2026-05-25T06:23:08.617619+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=154", "doc_key": "668444ac3972de872cd1fa3f1349840c"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'a10d43ab897344a7b985f679cc499d695c79f0db1f0ac811c07cf43e6a37b0f0'),
  ('cpiuris2025::918bbf74fd8fee6f8324afd583d48c31', 'doutrina', 'cp_iuris', 'Direito Administrativo — Princípios da Licitação', '## Princípios da Licitação

A licitação precisa ter justa competição para cumprir o objetivo de selecionar a proposta mais vantajosa. O princípio da competitividade é essencial para um procedimento licitatório.

### Conceitos
- **Competitividade**: Princípio que assegura justa concorrência entre os licitantes
- **Celeridade**: Princípio que visa tornar o procedimento licitatório mais rápido
- **Parcelamento**: Técnica que busca evitar a concentração de mercado e ampliar a competição

### Referências legais
- Art. 6º, XXV, ''c'' e ''d'', da Lei n.º 14.133/21
- Art. 9º, I, ''a'', da Lei n.º 14.133/21
- Art. 25, §2º, da Lei n.º 14.133/21
- Art. 31, §3º, da Lei n.º 14.133/21
- Art. 40, §2º, III, da Lei n.º 14.133/21
- Art. 47, §1º, III, da Lei n.º 14.133/21

### Dicas de prova
- Entenda a importância da competitividade na licitação
- Conheça os princípios da celeridade e parcelamento
