  ('cpiuris2025::856758563decb724c264959342c26055', 'doutrina', 'cp_iuris', 'Direito Administrativo — Princípio da Celeridade', '## Princípio da Celeridade

O princípio da celeridade busca afastar rigorismos excessivos e formalidades desnecessárias em licitações, visando resultados mais rápidos e menos recursos financeiros e pessoais.

### Conceitos
- **Princípio da Celeridade**: Busca reduzir tempo de resolução de licitações
- **Formalidade desnecessária**: Exigência que não compromete a qualificação do licitante ou compreensão do conteúdo de sua proposta
- **Aferição da qualificação do licitante**: Verificação se o licitante tem as condições necessárias para participar da licitação
- **Prova de autenticidade**: Verificação se um documento é autêntico ou não
- **Reconhecimento de firma**: Verificação se a assinatura de uma pessoa é legítima

### Referências legais
- Art. 12 da Lei n.º 14.133/21

### Dicas de prova
- Entenda o conceito de celeridade e suas implicações na licitação
- Conheça as formalidades desnecessárias e como elas podem ser afastadas
- Aprenda a distinguir entre exigências formais e essenciais para a licitação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.155 (2)", "page_number": 155, "discipline": "Direito Administrativo", "legal_refs": ["Art. 12 da Lei n.º 14.133/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:25:05.254894+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=155", "doc_key": "856758563decb724c264959342c26055"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'd23309220af9010d39f8be0b48b38f708a5684ec11ea6c5eaeabaf2c806575b3'),
  ('cpiuris2025::e21b95ec7a7b21583ac59700f99daf14', 'doutrina', 'cp_iuris', 'Direito Administrativo — Economicidade e Princípio da Eficácia na Licitação', '## Economicidade e Princípio da Eficácia na Licitação

A economicidade é um princípio constitucional que visa garantir a eficiência nos procedimentos licitatórios, com o objetivo de minimizar os custos públicos. A eficácia exige resultados satisfatórios, garantindo a realização dos objetivos da licitação.

### Conceitos
- **Economicidade**: Princípio constitucional que visa garantir a eficiência nos procedimentos licitatórios
- **Princípio da Eficácia**: Exige resultados satisfatórios, garantindo a realização dos objetivos da licitação
- **Custo-Benefício**: Análise das alternativas escolhidas pelo agente público para verificar se foram as melhores (com o mínimo de dispêndio) para a aplicação dos recursos públicos
- **Análise do Custo-Benefício**: Procedimento que visa avaliar os custos e benefícios das alternativas escolhidas pelo agente público
- **Plano de Contratações Anual**: Documento que projeta todas as licitações e contratações que podem ser realizadas ao longo do ano, dividindo-as por categorias e definindo prioridades
- **Licitação**: Procedimento público para a contratação de serviços ou obras

### Referências legais
- Art. 70 da Constituição da República
- Art. 18, § 1º, IX, da Lei n.º 14.133/21
- Art. 25, § 6º

### Dicas de prova
- Entenda a importância da economicidade na licitação e como ela se relaciona com o princípio da eficácia
- Análise do custo-benefício é fundamental para garantir a eficiência nos procedimentos licitatórios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.156", "page_number": 156, "discipline": "Direito Administrativo", "legal_refs": ["Art. 70 da Constituição da República", "Art. 18, § 1º, IX, da Lei n.º 14.133/21", "Art. 25, § 6º"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T06:26:13.003525+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=156", "doc_key": "e21b95ec7a7b21583ac59700f99daf14"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '0737928ce8046fac9defe57883da31c44f2138b70cfe06988380860358b714ce')
